        // Chapter: Graphics / Text
        // Short Description: Set font independent of OS
        public void set_display_font(
            HTuple hv_WindowHandle,
            HTuple hv_Size,
            HTuple hv_Font,
            HTuple hv_Bold,
            HTuple hv_Slant
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_OS = new HTuple(),
                hv_Fonts = new HTuple();
            HTuple hv_Style = new HTuple(),
                hv_Exception = new HTuple();
            HTuple hv_AvailableFonts = new HTuple(),
                hv_Fdx = new HTuple();
            HTuple hv_Indices = new HTuple();
            HTuple hv_Font_COPY_INP_TMP = new HTuple(hv_Font);
            HTuple hv_Size_COPY_INP_TMP = new HTuple(hv_Size);

            // Initialize local and output iconic variables
            try
            {
                //This procedure sets the text font of the current window with
                //the specified attributes.
                //
                //Input parameters:
                //WindowHandle: The graphics window for which the font will be set
                //Size: The font size. If Size=-1, the default of 16 is used.
                //Bold: If set to 'true', a bold font is used
                //Slant: If set to 'true', a slanted font is used
                //
                hv_OS.Dispose();
                HOperatorSet.GetSystem("operating_system", out hv_OS);
                if (
                    (int)(
                        (new HTuple(hv_Size_COPY_INP_TMP.TupleEqual(new HTuple()))).TupleOr(
                            new HTuple(hv_Size_COPY_INP_TMP.TupleEqual(-1))
                        )
                    ) != 0
                )
                {
                    hv_Size_COPY_INP_TMP.Dispose();
                    hv_Size_COPY_INP_TMP = 16;
                }
                if ((int)(new HTuple(((hv_OS.TupleSubstr(0, 2))).TupleEqual("Win"))) != 0)
                {
                    //Restore previous behaviour
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Size = (
                                (1.13677 * hv_Size_COPY_INP_TMP)
                            ).TupleInt();
                            hv_Size_COPY_INP_TMP.Dispose();
                            hv_Size_COPY_INP_TMP = ExpTmpLocalVar_Size;
                        }
                    }
                }
                else
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Size = hv_Size_COPY_INP_TMP.TupleInt();
                            hv_Size_COPY_INP_TMP.Dispose();
                            hv_Size_COPY_INP_TMP = ExpTmpLocalVar_Size;
                        }
                    }
                }
                if ((int)(new HTuple(hv_Font_COPY_INP_TMP.TupleEqual("Courier"))) != 0)
                {
                    hv_Fonts.Dispose();
                    hv_Fonts = new HTuple();
                    hv_Fonts[0] = "Courier";
                    hv_Fonts[1] = "Courier 10 Pitch";
                    hv_Fonts[2] = "Courier New";
                    hv_Fonts[3] = "CourierNew";
                    hv_Fonts[4] = "Liberation Mono";
                }
                else if ((int)(new HTuple(hv_Font_COPY_INP_TMP.TupleEqual("mono"))) != 0)
                {
                    hv_Fonts.Dispose();
                    hv_Fonts = new HTuple();
                    hv_Fonts[0] = "Consolas";
                    hv_Fonts[1] = "Menlo";
                    hv_Fonts[2] = "Courier";
                    hv_Fonts[3] = "Courier 10 Pitch";
                    hv_Fonts[4] = "FreeMono";
                    hv_Fonts[5] = "Liberation Mono";
                }
                else if ((int)(new HTuple(hv_Font_COPY_INP_TMP.TupleEqual("sans"))) != 0)
                {
                    hv_Fonts.Dispose();
                    hv_Fonts = new HTuple();
                    hv_Fonts[0] = "Luxi Sans";
                    hv_Fonts[1] = "DejaVu Sans";
                    hv_Fonts[2] = "FreeSans";
                    hv_Fonts[3] = "Arial";
                    hv_Fonts[4] = "Liberation Sans";
                }
                else if ((int)(new HTuple(hv_Font_COPY_INP_TMP.TupleEqual("serif"))) != 0)
                {
                    hv_Fonts.Dispose();
                    hv_Fonts = new HTuple();
                    hv_Fonts[0] = "Times New Roman";
                    hv_Fonts[1] = "Luxi Serif";
                    hv_Fonts[2] = "DejaVu Serif";
                    hv_Fonts[3] = "FreeSerif";
                    hv_Fonts[4] = "Utopia";
                    hv_Fonts[5] = "Liberation Serif";
                }
                else
                {
                    hv_Fonts.Dispose();
                    hv_Fonts = new HTuple(hv_Font_COPY_INP_TMP);
                }
                hv_Style.Dispose();
                hv_Style = "";
                if ((int)(new HTuple(hv_Bold.TupleEqual("true"))) != 0)
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Style = hv_Style + "Bold";
                            hv_Style.Dispose();
                            hv_Style = ExpTmpLocalVar_Style;
                        }
                    }
                }
                else if ((int)(new HTuple(hv_Bold.TupleNotEqual("false"))) != 0)
                {
                    hv_Exception.Dispose();
                    hv_Exception = "Wrong value of control parameter Bold";
                    throw new HalconException(hv_Exception);
                }
                if ((int)(new HTuple(hv_Slant.TupleEqual("true"))) != 0)
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Style = hv_Style + "Italic";
                            hv_Style.Dispose();
                            hv_Style = ExpTmpLocalVar_Style;
                        }
                    }
                }
                else if ((int)(new HTuple(hv_Slant.TupleNotEqual("false"))) != 0)
                {
                    hv_Exception.Dispose();
                    hv_Exception = "Wrong value of control parameter Slant";
                    throw new HalconException(hv_Exception);
                }
                if ((int)(new HTuple(hv_Style.TupleEqual(""))) != 0)
                {
                    hv_Style.Dispose();
                    hv_Style = "Normal";
                }
                hv_AvailableFonts.Dispose();
                HOperatorSet.QueryFont(hv_WindowHandle, out hv_AvailableFonts);
                hv_Font_COPY_INP_TMP.Dispose();
                hv_Font_COPY_INP_TMP = "";
                for (
                    hv_Fdx = 0;
                    (int)hv_Fdx <= (int)((new HTuple(hv_Fonts.TupleLength())) - 1);
                    hv_Fdx = (int)hv_Fdx + 1
                )
                {
                    hv_Indices.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Indices = hv_AvailableFonts.TupleFind(hv_Fonts.TupleSelect(hv_Fdx));
                    }
                    if (
                        (int)(new HTuple((new HTuple(hv_Indices.TupleLength())).TupleGreater(0)))
                        != 0
                    )
                    {
                        if (
                            (int)(new HTuple(((hv_Indices.TupleSelect(0))).TupleGreaterEqual(0)))
                            != 0
                        )
                        {
                            hv_Font_COPY_INP_TMP.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_Font_COPY_INP_TMP = hv_Fonts.TupleSelect(hv_Fdx);
                            }
                            break;
                        }
                    }
                }
                if ((int)(new HTuple(hv_Font_COPY_INP_TMP.TupleEqual(""))) != 0)
                {
                    throw new HalconException("Wrong value of control parameter Font");
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_Font =
                            (((hv_Font_COPY_INP_TMP + "-") + hv_Style) + "-")
                            + hv_Size_COPY_INP_TMP;
                        hv_Font_COPY_INP_TMP.Dispose();
                        hv_Font_COPY_INP_TMP = ExpTmpLocalVar_Font;
                    }
                }
                HOperatorSet.SetFont(hv_WindowHandle, hv_Font_COPY_INP_TMP);

                hv_Font_COPY_INP_TMP.Dispose();
                hv_Size_COPY_INP_TMP.Dispose();
                hv_OS.Dispose();
                hv_Fonts.Dispose();
                hv_Style.Dispose();
                hv_Exception.Dispose();
                hv_AvailableFonts.Dispose();
                hv_Fdx.Dispose();
                hv_Indices.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                hv_Font_COPY_INP_TMP.Dispose();
                hv_Size_COPY_INP_TMP.Dispose();
                hv_OS.Dispose();
                hv_Fonts.Dispose();
                hv_Style.Dispose();
                hv_Exception.Dispose();
                hv_AvailableFonts.Dispose();
                hv_Fdx.Dispose();
                hv_Indices.Dispose();

                throw HDevExpDefaultException;
            }
        }

        // Local procedures
        // Chapter: Math / Vector
        // Short Description: Calculates the cross product of the two 3d vectors given in V1 and V2
        public void cross_product(HTuple hv_V1, HTuple hv_V2, out HTuple hv_CrossProduct)
        {
            // Local iconic variables
            // Initialize local and output iconic variables
            hv_CrossProduct = new HTuple();
            //Determine the cross product of the two given vectors
            //Note that only the first three values of the given vectors are taken into account
            hv_CrossProduct.Dispose();
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                hv_CrossProduct = new HTuple();
                hv_CrossProduct = hv_CrossProduct.TupleConcat(
                    ((hv_V1.TupleSelect(1)) * (hv_V2.TupleSelect(2)))
                        - ((hv_V1.TupleSelect(2)) * (hv_V2.TupleSelect(1)))
                );
                hv_CrossProduct = hv_CrossProduct.TupleConcat(
                    ((hv_V1.TupleSelect(2)) * (hv_V2.TupleSelect(0)))
                        - ((hv_V1.TupleSelect(0)) * (hv_V2.TupleSelect(2)))
                );
                hv_CrossProduct = hv_CrossProduct.TupleConcat(
                    ((hv_V1.TupleSelect(0)) * (hv_V2.TupleSelect(1)))
                        - ((hv_V1.TupleSelect(1)) * (hv_V2.TupleSelect(0)))
                );
            }

            return;
        }

        public void determine_approximate_cylinder_pose_in_center_of_cameras(
            HTuple hv_CameraSetupModelZeroDist,
            HTuple hv_NumCameras,
            out HTuple hv_PoseCylinderApprox,
            out HTuple hv_HomMat3DCylinderApprox
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_XCam = new HTuple(),
                hv_YCam = new HTuple();
            HTuple hv_ZCam = new HTuple(),
                hv_Cam = new HTuple(),
                hv_CamPose = new HTuple();
            HTuple hv_CylinderPointApprox = new HTuple(),
                hv_LenI = new HTuple();
            HTuple hv_CylinderXTmp = new HTuple(),
                hv_NX = new HTuple();
            HTuple hv_NY = new HTuple(),
                hv_NZ = new HTuple(),
                hv_C = new HTuple();
            HTuple hv_CylinderZTmp = new HTuple(),
                hv_CylinderYTmp = new HTuple();
            // Initialize local and output iconic variables
            hv_PoseCylinderApprox = new HTuple();
            hv_HomMat3DCylinderApprox = new HTuple();
            try
            {
                hv_XCam.Dispose();
                hv_XCam = new HTuple();
                hv_YCam.Dispose();
                hv_YCam = new HTuple();
                hv_ZCam.Dispose();
                hv_ZCam = new HTuple();
                HTuple end_val3 = hv_NumCameras - 1;
                HTuple step_val3 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val3, step_val3);
                    hv_Cam = hv_Cam.TupleAdd(step_val3)
                )
                {
                    hv_CamPose.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDist,
                        hv_Cam,
                        "pose",
                        out hv_CamPose
                    );
                    if (hv_XCam == null)
                        hv_XCam = new HTuple();
                    hv_XCam[hv_Cam] = hv_CamPose.TupleSelect(0);
                    if (hv_YCam == null)
                        hv_YCam = new HTuple();
                    hv_YCam[hv_Cam] = hv_CamPose.TupleSelect(1);
                    if (hv_ZCam == null)
                        hv_ZCam = new HTuple();
                    hv_ZCam[hv_Cam] = hv_CamPose.TupleSelect(2);
                }
                hv_CylinderPointApprox.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_CylinderPointApprox = new HTuple();
                    hv_CylinderPointApprox = hv_CylinderPointApprox.TupleConcat(
                        hv_XCam.TupleMean()
                    );
                    hv_CylinderPointApprox = hv_CylinderPointApprox.TupleConcat(
                        hv_YCam.TupleMean()
                    );
                    hv_CylinderPointApprox = hv_CylinderPointApprox.TupleConcat(
                        hv_ZCam.TupleMean()
                    );
                }
                hv_LenI.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_LenI =
                        1.0
                        / (
                            (
                                (((hv_CylinderPointApprox * hv_CylinderPointApprox)).TupleSum())
                            ).TupleSqrt()
                        );
                }
                hv_CylinderXTmp.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_CylinderXTmp = hv_CylinderPointApprox * hv_LenI;
                }
                hv_NX.Dispose();
                hv_NY.Dispose();
                hv_NZ.Dispose();
                hv_C.Dispose();
                fit_plane(hv_XCam, hv_YCam, hv_ZCam, out hv_NX, out hv_NY, out hv_NZ, out hv_C);
                hv_CylinderZTmp.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_CylinderZTmp = new HTuple();
                    hv_CylinderZTmp = hv_CylinderZTmp.TupleConcat(hv_NX, hv_NY, hv_NZ);
                }
                //Ensure correct orientation of the cylinder axis
                if ((int)(new HTuple(hv_NX.TupleGreater(0))) != 0)
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_CylinderZTmp = -hv_CylinderZTmp;
                            hv_CylinderZTmp.Dispose();
                            hv_CylinderZTmp = ExpTmpLocalVar_CylinderZTmp;
                        }
                    }
                }
                hv_CylinderYTmp.Dispose();
                cross_product(hv_CylinderZTmp, hv_CylinderXTmp, out hv_CylinderYTmp);
                hv_HomMat3DCylinderApprox.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_HomMat3DCylinderApprox = new HTuple();
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderXTmp.TupleSelect(0)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderYTmp.TupleSelect(0)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderZTmp.TupleSelect(0)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderPointApprox.TupleSelect(0)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderXTmp.TupleSelect(1)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderYTmp.TupleSelect(1)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderZTmp.TupleSelect(1)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderPointApprox.TupleSelect(1)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderXTmp.TupleSelect(2)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderYTmp.TupleSelect(2)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderZTmp.TupleSelect(2)
                    );
                    hv_HomMat3DCylinderApprox = hv_HomMat3DCylinderApprox.TupleConcat(
                        hv_CylinderPointApprox.TupleSelect(2)
                    );
                }
                hv_PoseCylinderApprox.Dispose();
                HOperatorSet.HomMat3dToPose(hv_HomMat3DCylinderApprox, out hv_PoseCylinderApprox);

                hv_XCam.Dispose();
                hv_YCam.Dispose();
                hv_ZCam.Dispose();
                hv_Cam.Dispose();
                hv_CamPose.Dispose();
                hv_CylinderPointApprox.Dispose();
                hv_LenI.Dispose();
                hv_CylinderXTmp.Dispose();
                hv_NX.Dispose();
                hv_NY.Dispose();
                hv_NZ.Dispose();
                hv_C.Dispose();
                hv_CylinderZTmp.Dispose();
                hv_CylinderYTmp.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                hv_XCam.Dispose();
                hv_YCam.Dispose();
                hv_ZCam.Dispose();
                hv_Cam.Dispose();
                hv_CamPose.Dispose();
                hv_CylinderPointApprox.Dispose();
                hv_LenI.Dispose();
                hv_CylinderXTmp.Dispose();
                hv_NX.Dispose();
                hv_NY.Dispose();
                hv_NZ.Dispose();
                hv_C.Dispose();
                hv_CylinderZTmp.Dispose();
                hv_CylinderYTmp.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void determine_min_max_silhouette_distance(
            HTuple hv_CameraSetupModelZeroDist,
            HTuple hv_NumCameras,
            HTuple hv_PoseCylinderApprox,
            HTuple hv_CylinderRadius,
            HTuple hv_MinZ,
            HTuple hv_MaxZ,
            HTuple hv_Width,
            out HTuple hv_MinPairDist,
            out HTuple hv_MaxPairDist
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_SerializedItemHandle = new HTuple();
            HTuple hv_CameraSetupModelPCA = new HTuple(),
                hv_MaxShift = new HTuple();
            HTuple hv_MinDist = new HTuple(),
                hv_MaxDist = new HTuple();
            HTuple hv_Cam = new HTuple(),
                hv_CamParam = new HTuple();
            HTuple hv_CamPose = new HTuple(),
                hv_HomMat3D = new HTuple();
            HTuple hv_HomMat3DInvert = new HTuple(),
                hv_Sx = new HTuple();
            HTuple hv_Sy = new HTuple(),
                hv_Focus = new HTuple(),
                hv_S = new HTuple();
            HTuple hv_PMinCam = new HTuple(),
                hv_DistPMinCam = new HTuple();
            HTuple hv_Qx = new HTuple(),
                hv_Qy = new HTuple(),
                hv_Qz = new HTuple();
            HTuple hv_Row = new HTuple(),
                hv_Column = new HTuple();
            HTuple hv_CylRadPx = new HTuple(),
                hv_Shift1 = new HTuple();
            HTuple hv_Shift2 = new HTuple(),
                hv_PMaxCam = new HTuple();
            HTuple hv_DistPMaxCam = new HTuple(),
                hv_Foot = new HTuple();
            HTuple hv_PFootCam = new HTuple(),
                hv_DistPFootCam = new HTuple();
            // Initialize local and output iconic variables
            hv_MinPairDist = new HTuple();
            hv_MaxPairDist = new HTuple();
            try
            {
                hv_SerializedItemHandle.Dispose();
                HOperatorSet.SerializeCameraSetupModel(
                    hv_CameraSetupModelZeroDist,
                    out hv_SerializedItemHandle
                );
                hv_CameraSetupModelPCA.Dispose();
                HOperatorSet.DeserializeCameraSetupModel(
                    hv_SerializedItemHandle,
                    out hv_CameraSetupModelPCA
                );
                HOperatorSet.SetCameraSetupParam(
                    hv_CameraSetupModelPCA,
                    "general",
                    "coord_transf_pose",
                    hv_PoseCylinderApprox
                );
                hv_MaxShift.Dispose();
                hv_MaxShift = 0;
                hv_MinDist.Dispose();
                hv_MinDist = new HTuple();
                hv_MaxDist.Dispose();
                hv_MaxDist = new HTuple();
                HTuple end_val6 = hv_NumCameras - 1;
                HTuple step_val6 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val6, step_val6);
                    hv_Cam = hv_Cam.TupleAdd(step_val6)
                )
                {
                    hv_CamParam.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelPCA,
                        hv_Cam,
                        "params",
                        out hv_CamParam
                    );
                    hv_CamPose.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelPCA,
                        hv_Cam,
                        "pose",
                        out hv_CamPose
                    );
                    hv_HomMat3D.Dispose();
                    HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                    hv_HomMat3DInvert.Dispose();
                    HOperatorSet.HomMat3dInvert(hv_HomMat3D, out hv_HomMat3DInvert);
                    hv_Sx.Dispose();
                    get_cam_par_data(hv_CamParam, "sx", out hv_Sx);
                    hv_Sy.Dispose();
                    get_cam_par_data(hv_CamParam, "sy", out hv_Sy);
                    hv_Focus.Dispose();
                    get_cam_par_data(hv_CamParam, "focus", out hv_Focus);
                    hv_S.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_S = 0.5 * (hv_Sx + hv_Sy);
                    }

                    //Determine the distance of the cylinder axis from the camera and
                    //determine the maximum shift of the cylinder such that it is still
                    //completely visible in the image
                    //- at position MinZ
                    hv_PMinCam.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PMinCam =
                            (hv_CamPose.TupleSelectRange(0, 2))
                            - (((new HTuple(0)).TupleConcat(0)).TupleConcat(hv_MinZ));
                    }
                    hv_DistPMinCam.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistPMinCam = ((((hv_PMinCam * hv_PMinCam)).TupleSum())).TupleSqrt();
                    }
                    hv_Qx.Dispose();
                    hv_Qy.Dispose();
                    hv_Qz.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3DInvert,
                        0,
                        0,
                        hv_MinZ,
                        out hv_Qx,
                        out hv_Qy,
                        out hv_Qz
                    );
                    hv_Row.Dispose();
                    hv_Column.Dispose();
                    HOperatorSet.Project3dPoint(
                        hv_Qx,
                        hv_Qy,
                        hv_Qz,
                        hv_CamParam,
                        out hv_Row,
                        out hv_Column
                    );
                    hv_CylRadPx.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_CylRadPx = ((hv_Focus / hv_DistPMinCam) * hv_CylinderRadius) / hv_S;
                    }
                    hv_Shift1.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Shift1 =
                            (((hv_Column - hv_CylRadPx) * hv_S) * hv_DistPMinCam) / hv_Focus;
                    }
                    hv_Shift2.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Shift2 =
                            (((hv_Width - (hv_Column + hv_CylRadPx)) * hv_S) * hv_DistPMinCam)
                            / hv_Focus;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MaxShift = (
                                (((hv_MaxShift.TupleConcat(hv_Shift1))).TupleConcat(hv_Shift2))
                            ).TupleMax();
                            hv_MaxShift.Dispose();
                            hv_MaxShift = ExpTmpLocalVar_MaxShift;
                        }
                    }

                    //- at position MaxZ
                    hv_PMaxCam.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PMaxCam =
                            (hv_CamPose.TupleSelectRange(0, 2))
                            - (((new HTuple(0)).TupleConcat(0)).TupleConcat(hv_MaxZ));
                    }
                    hv_DistPMaxCam.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistPMaxCam = ((((hv_PMaxCam * hv_PMaxCam)).TupleSum())).TupleSqrt();
                    }
                    hv_Qx.Dispose();
                    hv_Qy.Dispose();
                    hv_Qz.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3DInvert,
                        0,
                        0,
                        hv_MaxZ,
                        out hv_Qx,
                        out hv_Qy,
                        out hv_Qz
                    );
                    hv_Row.Dispose();
                    hv_Column.Dispose();
                    HOperatorSet.Project3dPoint(
                        hv_Qx,
                        hv_Qy,
                        hv_Qz,
                        hv_CamParam,
                        out hv_Row,
                        out hv_Column
                    );
                    hv_CylRadPx.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_CylRadPx = ((hv_Focus / hv_DistPMaxCam) * hv_CylinderRadius) / hv_S;
                    }
                    hv_Shift1.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Shift1 =
                            (((hv_Column - hv_CylRadPx) * hv_S) * hv_DistPMaxCam) / hv_Focus;
                    }
                    hv_Shift2.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Shift2 =
                            (((hv_Width - (hv_Column + hv_CylRadPx)) * hv_S) * hv_DistPMaxCam)
                            / hv_Focus;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MaxShift = (
                                (((hv_MaxShift.TupleConcat(hv_Shift1))).TupleConcat(hv_Shift2))
                            ).TupleMax();
                            hv_MaxShift.Dispose();
                            hv_MaxShift = ExpTmpLocalVar_MaxShift;
                        }
                    }

                    //- at a position where the camera looks "perpendicular" to the cylinder
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Foot.Dispose();
                        point_to_line_perpendicular_foot(
                            hv_CamPose.TupleSelectRange(0, 2),
                            ((new HTuple(0)).TupleConcat(0)).TupleConcat(0),
                            ((new HTuple(0)).TupleConcat(0)).TupleConcat(1),
                            out hv_Foot
                        );
                    }
                    hv_PFootCam.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PFootCam = (hv_CamPose.TupleSelectRange(0, 2)) - hv_Foot;
                    }
                    hv_DistPFootCam.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistPFootCam = ((((hv_PFootCam * hv_PFootCam)).TupleSum())).TupleSqrt();
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Qx.Dispose();
                        hv_Qy.Dispose();
                        hv_Qz.Dispose();
                        HOperatorSet.AffineTransPoint3d(
                            hv_HomMat3DInvert,
                            0,
                            0,
                            hv_Foot.TupleSelect(2),
                            out hv_Qx,
                            out hv_Qy,
                            out hv_Qz
                        );
                    }
                    hv_Row.Dispose();
                    hv_Column.Dispose();
                    HOperatorSet.Project3dPoint(
                        hv_Qx,
                        hv_Qy,
                        hv_Qz,
                        hv_CamParam,
                        out hv_Row,
                        out hv_Column
                    );
                    hv_CylRadPx.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_CylRadPx = ((hv_Focus / hv_DistPFootCam) * hv_CylinderRadius) / hv_S;
                    }
                    hv_Shift1.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Shift1 =
                            (((hv_Column - hv_CylRadPx) * hv_S) * hv_DistPFootCam) / hv_Focus;
                    }
                    hv_Shift2.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Shift2 =
                            (((hv_Width - (hv_Column + hv_CylRadPx)) * hv_S) * hv_DistPFootCam)
                            / hv_Focus;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MaxShift = (
                                (((hv_MaxShift.TupleConcat(hv_Shift1))).TupleConcat(hv_Shift2))
                            ).TupleMax();
                            hv_MaxShift.Dispose();
                            hv_MaxShift = ExpTmpLocalVar_MaxShift;
                        }
                    }

                    if (hv_MinDist == null)
                        hv_MinDist = new HTuple();
                    hv_MinDist[hv_Cam] = (
                        (
                            ((hv_DistPMinCam.TupleConcat(hv_DistPMaxCam))).TupleConcat(
                                hv_DistPFootCam
                            )
                        )
                    ).TupleMin();
                    if (hv_MaxDist == null)
                        hv_MaxDist = new HTuple();
                    hv_MaxDist[hv_Cam] = (
                        (
                            ((hv_DistPMinCam.TupleConcat(hv_DistPMaxCam))).TupleConcat(
                                hv_DistPFootCam
                            )
                        )
                    ).TupleMax();
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_MaxShift = 1.05 * hv_MaxShift;
                        hv_MaxShift.Dispose();
                        hv_MaxShift = ExpTmpLocalVar_MaxShift;
                    }
                }

                //Approximately determine the minimum and maximum distance between the
                //opposite silhouettes of the cylinder in the images assuming that this
                //distance is measured perpendicular to the cylinder axis
                hv_MinPairDist.Dispose();
                hv_MinPairDist = new HTuple();
                hv_MaxPairDist.Dispose();
                hv_MaxPairDist = new HTuple();
                HTuple end_val61 = hv_NumCameras - 1;
                HTuple step_val61 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val61, step_val61);
                    hv_Cam = hv_Cam.TupleAdd(step_val61)
                )
                {
                    if (hv_MinPairDist == null)
                        hv_MinPairDist = new HTuple();
                    hv_MinPairDist[hv_Cam] =
                        (
                            ((2.0 * hv_Focus) / ((hv_MaxDist.TupleSelect(hv_Cam)) + hv_MaxShift))
                            * hv_CylinderRadius
                        ) / hv_S;
                    if (hv_MaxPairDist == null)
                        hv_MaxPairDist = new HTuple();
                    hv_MaxPairDist[hv_Cam] =
                        (
                            ((2.0 * hv_Focus) / ((hv_MinDist.TupleSelect(hv_Cam)) - hv_MaxShift))
                            * hv_CylinderRadius
                        ) / hv_S;
                }

                hv_SerializedItemHandle.Dispose();
                hv_CameraSetupModelPCA.Dispose();
                hv_MaxShift.Dispose();
                hv_MinDist.Dispose();
                hv_MaxDist.Dispose();
                hv_Cam.Dispose();
                hv_CamParam.Dispose();
                hv_CamPose.Dispose();
                hv_HomMat3D.Dispose();
                hv_HomMat3DInvert.Dispose();
                hv_Sx.Dispose();
                hv_Sy.Dispose();
                hv_Focus.Dispose();
                hv_S.Dispose();
                hv_PMinCam.Dispose();
                hv_DistPMinCam.Dispose();
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                hv_Row.Dispose();
                hv_Column.Dispose();
                hv_CylRadPx.Dispose();
                hv_Shift1.Dispose();
                hv_Shift2.Dispose();
                hv_PMaxCam.Dispose();
                hv_DistPMaxCam.Dispose();
                hv_Foot.Dispose();
                hv_PFootCam.Dispose();
                hv_DistPFootCam.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                hv_SerializedItemHandle.Dispose();
                hv_CameraSetupModelPCA.Dispose();
                hv_MaxShift.Dispose();
                hv_MinDist.Dispose();
                hv_MaxDist.Dispose();
                hv_Cam.Dispose();
                hv_CamParam.Dispose();
                hv_CamPose.Dispose();
                hv_HomMat3D.Dispose();
                hv_HomMat3DInvert.Dispose();
                hv_Sx.Dispose();
                hv_Sy.Dispose();
                hv_Focus.Dispose();
                hv_S.Dispose();
                hv_PMinCam.Dispose();
                hv_DistPMinCam.Dispose();
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                hv_Row.Dispose();
                hv_Column.Dispose();
                hv_CylRadPx.Dispose();
                hv_Shift1.Dispose();
                hv_Shift2.Dispose();
                hv_PMaxCam.Dispose();
                hv_DistPMaxCam.Dispose();
                hv_Foot.Dispose();
                hv_PFootCam.Dispose();
                hv_DistPFootCam.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void determine_required_cylinder_model_extent(
            HTuple hv_LabelMinRow,
            HTuple hv_LabelMaxRow,
            HTuple hv_Width,
            HTuple hv_CameraSetupModelZeroDist,
            HTuple hv_NumCameras,
            HTuple hv_HomMat3DCylinderApprox,
            out HTuple hv_MinZ,
            out HTuple hv_MaxZ
        )
        {
            // Local iconic variables

            HObject ho_ContourROI;

            // Local control variables

            HTuple hv_Cam = new HTuple(),
                hv_CamParam = new HTuple();
            HTuple hv_CamPose = new HTuple(),
                hv_HomMat3D = new HTuple();
            HTuple hv_HomMat3DCompose = new HTuple(),
                hv_Qx = new HTuple();
            HTuple hv_Qy = new HTuple(),
                hv_Qz = new HTuple(),
                hv_AxisRow = new HTuple();
            HTuple hv_AxisColumn = new HTuple(),
                hv_IntersectionRow = new HTuple();
            HTuple hv_IntersectionColumn = new HTuple(),
                hv_IsOverlapping = new HTuple();
            HTuple hv_PxC = new HTuple(),
                hv_PyC = new HTuple(),
                hv_PzC = new HTuple();
            HTuple hv_QxC = new HTuple(),
                hv_QyC = new HTuple(),
                hv_QzC = new HTuple();
            HTuple hv_HomMat3DInvert = new HTuple(),
                hv_Px = new HTuple();
            HTuple hv_Py = new HTuple(),
                hv_Pz = new HTuple(),
                hv_P1 = new HTuple();
            HTuple hv_P2 = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_ContourROI);
            hv_MinZ = new HTuple();
            hv_MaxZ = new HTuple();
            try
            {
                hv_MinZ.Dispose();
                hv_MinZ = 999;
                hv_MaxZ.Dispose();
                hv_MaxZ = -999;
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_ContourROI.Dispose();
                    HOperatorSet.GenContourPolygonXld(
                        out ho_ContourROI,
                        (
                            (
                                (
                                    (
                                        ((hv_LabelMinRow.TupleConcat(hv_LabelMaxRow))).TupleConcat(
                                            hv_LabelMaxRow
                                        )
                                    )
                                ).TupleConcat(hv_LabelMinRow)
                            )
                        ).TupleConcat(hv_LabelMinRow),
                        (
                            (
                                (
                                    (((new HTuple(0)).TupleConcat(0)).TupleConcat(hv_Width - 1))
                                ).TupleConcat(hv_Width - 1)
                            )
                        ).TupleConcat(0)
                    );
                }
                HTuple end_val3 = hv_NumCameras - 1;
                HTuple step_val3 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val3, step_val3);
                    hv_Cam = hv_Cam.TupleAdd(step_val3)
                )
                {
                    hv_CamParam.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDist,
                        hv_Cam,
                        "params",
                        out hv_CamParam
                    );
                    hv_CamPose.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDist,
                        hv_Cam,
                        "pose",
                        out hv_CamPose
                    );
                    //Project the cylinder axis into the image
                    hv_HomMat3D.Dispose();
                    HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                    hv_HomMat3DCompose.Dispose();
                    HOperatorSet.HomMat3dCompose(
                        hv_HomMat3D,
                        hv_HomMat3DCylinderApprox,
                        out hv_HomMat3DCompose
                    );
                    hv_Qx.Dispose();
                    hv_Qy.Dispose();
                    hv_Qz.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3DCompose,
                        (new HTuple(0)).TupleConcat(0),
                        (new HTuple(0)).TupleConcat(0),
                        (new HTuple(-1)).TupleConcat(1),
                        out hv_Qx,
                        out hv_Qy,
                        out hv_Qz
                    );
                    hv_AxisRow.Dispose();
                    hv_AxisColumn.Dispose();
                    HOperatorSet.Project3dPoint(
                        hv_Qx,
                        hv_Qy,
                        hv_Qz,
                        hv_CamParam,
                        out hv_AxisRow,
                        out hv_AxisColumn
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_IntersectionRow.Dispose();
                        hv_IntersectionColumn.Dispose();
                        hv_IsOverlapping.Dispose();
                        HOperatorSet.IntersectionLineContourXld(
                            ho_ContourROI,
                            hv_AxisRow.TupleSelect(0),
                            hv_AxisColumn.TupleSelect(0),
                            hv_AxisRow.TupleSelect(1),
                            hv_AxisColumn.TupleSelect(1),
                            out hv_IntersectionRow,
                            out hv_IntersectionColumn,
                            out hv_IsOverlapping
                        );
                    }
                    hv_PxC.Dispose();
                    hv_PyC.Dispose();
                    hv_PzC.Dispose();
                    hv_QxC.Dispose();
                    hv_QyC.Dispose();
                    hv_QzC.Dispose();
                    HOperatorSet.GetLineOfSight(
                        hv_IntersectionRow,
                        hv_IntersectionColumn,
                        hv_CamParam,
                        out hv_PxC,
                        out hv_PyC,
                        out hv_PzC,
                        out hv_QxC,
                        out hv_QyC,
                        out hv_QzC
                    );
                    hv_HomMat3DInvert.Dispose();
                    HOperatorSet.HomMat3dInvert(hv_HomMat3DCompose, out hv_HomMat3DInvert);
                    hv_Px.Dispose();
                    hv_Py.Dispose();
                    hv_Pz.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3DInvert,
                        hv_PxC,
                        hv_PyC,
                        hv_PzC,
                        out hv_Px,
                        out hv_Py,
                        out hv_Pz
                    );
                    hv_Qx.Dispose();
                    hv_Qy.Dispose();
                    hv_Qz.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3DInvert,
                        hv_QxC,
                        hv_QyC,
                        hv_QzC,
                        out hv_Qx,
                        out hv_Qy,
                        out hv_Qz
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_P1.Dispose();
                        skew_lines_perpendicular_foot(
                            ((new HTuple(0)).TupleConcat(0)).TupleConcat(0),
                            ((new HTuple(0)).TupleConcat(0)).TupleConcat(1),
                            (
                                (((hv_Px.TupleSelect(0))).TupleConcat(hv_Py.TupleSelect(0)))
                            ).TupleConcat(hv_Pz.TupleSelect(0)),
                            (
                                (
                                    (((hv_Qx.TupleSelect(0)) - (hv_Px.TupleSelect(0)))).TupleConcat(
                                        (hv_Qy.TupleSelect(0)) - (hv_Py.TupleSelect(0))
                                    )
                                )
                            ).TupleConcat((hv_Qz.TupleSelect(0)) - (hv_Pz.TupleSelect(0))),
                            1,
                            out hv_P1
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_P2.Dispose();
                        skew_lines_perpendicular_foot(
                            ((new HTuple(0)).TupleConcat(0)).TupleConcat(0),
                            ((new HTuple(0)).TupleConcat(0)).TupleConcat(1),
                            (
                                (((hv_Px.TupleSelect(1))).TupleConcat(hv_Py.TupleSelect(1)))
                            ).TupleConcat(hv_Pz.TupleSelect(1)),
                            (
                                (
                                    (((hv_Qx.TupleSelect(1)) - (hv_Px.TupleSelect(1)))).TupleConcat(
                                        (hv_Qy.TupleSelect(1)) - (hv_Py.TupleSelect(1))
                                    )
                                )
                            ).TupleConcat((hv_Qz.TupleSelect(1)) - (hv_Pz.TupleSelect(1))),
                            1,
                            out hv_P2
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MinZ = (
                                (
                                    ((hv_MinZ.TupleConcat(hv_P1.TupleSelect(2)))).TupleConcat(
                                        hv_P2.TupleSelect(2)
                                    )
                                )
                            ).TupleMin();
                            hv_MinZ.Dispose();
                            hv_MinZ = ExpTmpLocalVar_MinZ;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MaxZ = (
                                (
                                    ((hv_MaxZ.TupleConcat(hv_P1.TupleSelect(2)))).TupleConcat(
                                        hv_P2.TupleSelect(2)
                                    )
                                )
                            ).TupleMax();
                            hv_MaxZ.Dispose();
                            hv_MaxZ = ExpTmpLocalVar_MaxZ;
                        }
                    }
                }
                ho_ContourROI.Dispose();

                hv_Cam.Dispose();
                hv_CamParam.Dispose();
                hv_CamPose.Dispose();
                hv_HomMat3D.Dispose();
                hv_HomMat3DCompose.Dispose();
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                hv_AxisRow.Dispose();
                hv_AxisColumn.Dispose();
                hv_IntersectionRow.Dispose();
                hv_IntersectionColumn.Dispose();
                hv_IsOverlapping.Dispose();
                hv_PxC.Dispose();
                hv_PyC.Dispose();
                hv_PzC.Dispose();
                hv_QxC.Dispose();
                hv_QyC.Dispose();
                hv_QzC.Dispose();
                hv_HomMat3DInvert.Dispose();
                hv_Px.Dispose();
                hv_Py.Dispose();
                hv_Pz.Dispose();
                hv_P1.Dispose();
                hv_P2.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_ContourROI.Dispose();

                hv_Cam.Dispose();
                hv_CamParam.Dispose();
                hv_CamPose.Dispose();
                hv_HomMat3D.Dispose();
                hv_HomMat3DCompose.Dispose();
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                hv_AxisRow.Dispose();
                hv_AxisColumn.Dispose();
                hv_IntersectionRow.Dispose();
                hv_IntersectionColumn.Dispose();
                hv_IsOverlapping.Dispose();
                hv_PxC.Dispose();
                hv_PyC.Dispose();
                hv_PzC.Dispose();
                hv_QxC.Dispose();
                hv_QyC.Dispose();
                hv_QzC.Dispose();
                hv_HomMat3DInvert.Dispose();
                hv_Px.Dispose();
                hv_Py.Dispose();
                hv_Pz.Dispose();
                hv_P1.Dispose();
                hv_P2.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void determine_rotation_axis_3d(
            HObject ho_ImagesRectified,
            HTuple hv_CylinderRadius,
            HTuple hv_MeasureHandles,
            HTuple hv_Width,
            HTuple hv_Height,
            HTuple hv_CameraSetupModelZeroDist,
            HTuple hv_NumCameras,
            HTuple hv_PoseCylinderApprox,
            HTuple hv_MinPairDist,
            HTuple hv_MaxPairDist,
            HTuple hv_SilhouetteMeasureSigma,
            HTuple hv_SilhouetteMeasureThreshold,
            HTuple hv_SilhouetteMaxTilt,
            HTuple hv_MaxError,
            out HTuple hv_PoseCylinder,
            out HTuple hv_CameraSetupModelZeroDistInCylinderOrigin
        )
        {
            // Local iconic variables

            HObject ho_ImageRectified = null,
                ho_Cross = null;
            HObject ho_Image = null,
                ho_ImageCyl = null,
                ho_Region = null;
            HObject ho_Contours = null,
                ho_CrossUsed = null;

            // Local control variables

            HTuple hv_SerializedItemHandle = new HTuple();
            HTuple hv_CameraSetupModelZeroDistCylApprox = new HTuple();
            HTuple hv_A2x = new HTuple(),
                hv_A2y = new HTuple(),
                hv_A2z = new HTuple();
            HTuple hv_B2x = new HTuple(),
                hv_B2y = new HTuple(),
                hv_B2z = new HTuple();
            HTuple hv_SilhRow = new HTuple(),
                hv_SilhCol = new HTuple();
            HTuple hv_SilhCam = new HTuple(),
                hv_SilhRowElim = new HTuple();
            HTuple hv_SilhColElim = new HTuple(),
                hv_SilhCamElim = new HTuple();
            HTuple hv_Cam = new HTuple(),
                hv_CamParam = new HTuple();
            HTuple hv_CamPose = new HTuple(),
                hv_Row = new HTuple();
            HTuple hv_Column = new HTuple(),
                hv_FuzzyFunction = new HTuple();
            HTuple hv_I = new HTuple(),
                hv_RowEdgeFirst = new HTuple();
            HTuple hv_ColumnEdgeFirst = new HTuple(),
                hv_AmplitudeFirst = new HTuple();
            HTuple hv_RowEdgeSecond = new HTuple(),
                hv_ColumnEdgeSecond = new HTuple();
            HTuple hv_AmplitudeSecond = new HTuple(),
                hv_RowPairCenter = new HTuple();
            HTuple hv_ColumnPairCenter = new HTuple(),
                hv_FuzzyScore = new HTuple();
            HTuple hv_IntraDistance = new HTuple(),
                hv_SIF = new HTuple();
            HTuple hv_SIS = new HTuple(),
                hv_WindowHandle = new HTuple();
            HTuple hv_PX = new HTuple(),
                hv_PY = new HTuple(),
                hv_PZ = new HTuple();
            HTuple hv_QX = new HTuple(),
                hv_QY = new HTuple(),
                hv_QZ = new HTuple();
            HTuple hv_HomMat3D = new HTuple(),
                hv_PX0 = new HTuple();
            HTuple hv_PY0 = new HTuple(),
                hv_PZ0 = new HTuple(),
                hv_QX0 = new HTuple();
            HTuple hv_QY0 = new HTuple(),
                hv_QZ0 = new HTuple(),
                hv_CamI = new HTuple();
            HTuple hv_NumPoints = new HTuple(),
                hv_A1x = new HTuple();
            HTuple hv_A1y = new HTuple(),
                hv_A1z = new HTuple(),
                hv_B1x = new HTuple();
            HTuple hv_B1y = new HTuple(),
                hv_B1z = new HTuple(),
                hv_Dx = new HTuple();
            HTuple hv_ErrorLog = new HTuple(),
                hv_Iter = new HTuple();
            HTuple hv_IterInter = new HTuple(),
                hv_MaxIter = new HTuple();
            HTuple hv_MaxIterInter = new HTuple(),
                hv_LastError = new HTuple();
            HTuple hv_SDevFactor = new HTuple(),
                hv_Dist = new HTuple();
            HTuple hv_E = new HTuple(),
                hv_Delta = new HTuple(),
                hv_DistTmp = new HTuple();
            HTuple hv_DistDAx = new HTuple(),
                hv_DistDAy = new HTuple();
            HTuple hv_DistDBx = new HTuple(),
                hv_DistDBy = new HTuple();
            HTuple hv_A = new HTuple(),
                hv_SeqR = new HTuple(),
                hv_SeqC = new HTuple();
            HTuple hv_y = new HTuple(),
                hv_X = new HTuple(),
                hv_Values = new HTuple();
            HTuple hv_SDevE = new HTuple(),
                hv_MaskUse = new HTuple();
            HTuple hv_SilhCamTmp = new HTuple(),
                hv_CamOk = new HTuple();
            HTuple hv_NumPointsRemaining = new HTuple(),
                hv_CamPose0 = new HTuple();
            HTuple hv_Foot = new HTuple(),
                hv_XAxis = new HTuple();
            HTuple hv_ZAxis = new HTuple(),
                hv_YAxis = new HTuple();
            HTuple hv_HomMat3DCylinderEst = new HTuple(),
                hv_PoseCylinderEst = new HTuple();
            HTuple hv_WL = new HTuple(),
                hv_HL = new HTuple(),
                hv_WH = new HTuple();
            HTuple hv_ObjectModel3DCylinder = new HTuple(),
                hv_WindowHandleI = new HTuple();
            HTuple hv_PoseInvert = new HTuple(),
                hv_UsedId = new HTuple();
            HTuple hv_RejectedId = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_ImageRectified);
            HOperatorSet.GenEmptyObj(out ho_Cross);
            HOperatorSet.GenEmptyObj(out ho_Image);
            HOperatorSet.GenEmptyObj(out ho_ImageCyl);
            HOperatorSet.GenEmptyObj(out ho_Region);
            HOperatorSet.GenEmptyObj(out ho_Contours);
            HOperatorSet.GenEmptyObj(out ho_CrossUsed);
            hv_PoseCylinder = new HTuple();
            hv_CameraSetupModelZeroDistInCylinderOrigin = new HTuple();
            try
            {
                //global tuple DisplayIntermediateResults
                //global tuple WindowWidthLimit
                //global tuple WindowHeightLimit
                //
                //Set origin of camera setup model to approximate cylinder pose
                hv_SerializedItemHandle.Dispose();
                HOperatorSet.SerializeCameraSetupModel(
                    hv_CameraSetupModelZeroDist,
                    out hv_SerializedItemHandle
                );
                hv_CameraSetupModelZeroDistCylApprox.Dispose();
                HOperatorSet.DeserializeCameraSetupModel(
                    hv_SerializedItemHandle,
                    out hv_CameraSetupModelZeroDistCylApprox
                );
                HOperatorSet.SetCameraSetupParam(
                    hv_CameraSetupModelZeroDistCylApprox,
                    "general",
                    "coord_transf_pose",
                    hv_PoseCylinderApprox
                );
                //
                //Collect possible silhouette points from all images
                hv_A2x.Dispose();
                hv_A2x = new HTuple();
                hv_A2y.Dispose();
                hv_A2y = new HTuple();
                hv_A2z.Dispose();
                hv_A2z = new HTuple();
                hv_B2x.Dispose();
                hv_B2x = new HTuple();
                hv_B2y.Dispose();
                hv_B2y = new HTuple();
                hv_B2z.Dispose();
                hv_B2z = new HTuple();
                //Collect image coordinates for visualization and analysis
                hv_SilhRow.Dispose();
                hv_SilhRow = new HTuple();
                hv_SilhCol.Dispose();
                hv_SilhCol = new HTuple();
                hv_SilhCam.Dispose();
                hv_SilhCam = new HTuple();

                hv_SilhRowElim.Dispose();
                hv_SilhRowElim = new HTuple();
                hv_SilhColElim.Dispose();
                hv_SilhColElim = new HTuple();
                hv_SilhCamElim.Dispose();
                hv_SilhCamElim = new HTuple();

                HTuple end_val25 = hv_NumCameras - 1;
                HTuple step_val25 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val25, step_val25);
                    hv_Cam = hv_Cam.TupleAdd(step_val25)
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageRectified.Dispose();
                        HOperatorSet.SelectObj(
                            ho_ImagesRectified,
                            out ho_ImageRectified,
                            hv_Cam + 1
                        );
                    }
                    hv_CamParam.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDistCylApprox,
                        hv_Cam,
                        "params",
                        out hv_CamParam
                    );
                    hv_CamPose.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDistCylApprox,
                        hv_Cam,
                        "pose",
                        out hv_CamPose
                    );
                    hv_Row.Dispose();
                    hv_Row = new HTuple();
                    hv_Column.Dispose();
                    hv_Column = new HTuple();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_FuzzyFunction.Dispose();
                        HOperatorSet.CreateFunct1dPairs(
                            (
                                (
                                    (
                                        (
                                            (
                                                ((hv_MinPairDist.TupleSelect(hv_Cam)) - 10)
                                            ).TupleConcat(hv_MinPairDist.TupleSelect(hv_Cam))
                                        )
                                    ).TupleConcat(
                                        (hv_MaxPairDist.TupleSelect(hv_Cam))
                                            / (hv_SilhouetteMaxTilt.TupleCos())
                                    )
                                )
                            ).TupleConcat(
                                (
                                    (hv_MaxPairDist.TupleSelect(hv_Cam))
                                    / (hv_SilhouetteMaxTilt.TupleCos())
                                ) + 10
                            ),
                            (((new HTuple(0)).TupleConcat(1)).TupleConcat(1)).TupleConcat(0),
                            out hv_FuzzyFunction
                        );
                    }
                    for (
                        hv_I = 0;
                        (int)hv_I <= (int)((new HTuple(hv_MeasureHandles.TupleLength())) - 1);
                        hv_I = (int)hv_I + 1
                    )
                    {
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetFuzzyMeasure(
                                hv_MeasureHandles.TupleSelect(hv_I),
                                "size",
                                hv_FuzzyFunction
                            );
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_RowEdgeFirst.Dispose();
                            hv_ColumnEdgeFirst.Dispose();
                            hv_AmplitudeFirst.Dispose();
                            hv_RowEdgeSecond.Dispose();
                            hv_ColumnEdgeSecond.Dispose();
                            hv_AmplitudeSecond.Dispose();
                            hv_RowPairCenter.Dispose();
                            hv_ColumnPairCenter.Dispose();
                            hv_FuzzyScore.Dispose();
                            hv_IntraDistance.Dispose();
                            HOperatorSet.FuzzyMeasurePairing(
                                ho_ImageRectified,
                                hv_MeasureHandles.TupleSelect(hv_I),
                                hv_SilhouetteMeasureSigma,
                                hv_SilhouetteMeasureThreshold,
                                0.5,
                                "all",
                                "no_restriction",
                                0,
                                out hv_RowEdgeFirst,
                                out hv_ColumnEdgeFirst,
                                out hv_AmplitudeFirst,
                                out hv_RowEdgeSecond,
                                out hv_ColumnEdgeSecond,
                                out hv_AmplitudeSecond,
                                out hv_RowPairCenter,
                                out hv_ColumnPairCenter,
                                out hv_FuzzyScore,
                                out hv_IntraDistance
                            );
                        }
                        //Select only first and last edge if the background can be assumed
                        //to be textureless
                        if (
                            (int)(
                                new HTuple(
                                    (new HTuple(hv_RowEdgeFirst.TupleLength())).TupleGreater(0)
                                )
                            ) != 0
                        )
                        {
                            hv_SIF.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_SIF = (
                                    new HTuple(((-hv_RowEdgeFirst)).TupleSortIndex())
                                ).TupleSelect(0);
                            }
                            hv_SIS.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_SIS = (
                                    new HTuple(hv_RowEdgeSecond.TupleSortIndex())
                                ).TupleSelect(0);
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_Row = (
                                        (hv_Row.TupleConcat(hv_RowEdgeFirst.TupleSelect(hv_SIF)))
                                    ).TupleConcat(hv_RowEdgeSecond.TupleSelect(hv_SIS));
                                    hv_Row.Dispose();
                                    hv_Row = ExpTmpLocalVar_Row;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_Column = (
                                        (
                                            hv_Column.TupleConcat(
                                                hv_ColumnEdgeFirst.TupleSelect(hv_SIF)
                                            )
                                        )
                                    ).TupleConcat(hv_ColumnEdgeSecond.TupleSelect(hv_SIS));
                                    hv_Column.Dispose();
                                    hv_Column = ExpTmpLocalVar_Column;
                                }
                            }
                        }
                    }
                    if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                    {
                        if (HDevWindowStack.IsOpen())
                        {
                            hv_WindowHandle = HDevWindowStack.GetActive();
                        }
                        ho_Cross.Dispose();
                        HOperatorSet.GenCrossContourXld(
                            out ho_Cross,
                            hv_Row,
                            hv_Column,
                            10,
                            0.785398
                        );
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                        }
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.DispObj(ho_ImageRectified, HDevWindowStack.GetActive());
                        }
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.DispObj(ho_Cross, HDevWindowStack.GetActive());
                        }
                        // stop(...); only in hdevelop
                    }

                    //Only for visualization of selected points
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_SilhRow = hv_SilhRow.TupleConcat(hv_Row);
                            hv_SilhRow.Dispose();
                            hv_SilhRow = ExpTmpLocalVar_SilhRow;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_SilhCol = hv_SilhCol.TupleConcat(hv_Column);
                            hv_SilhCol.Dispose();
                            hv_SilhCol = ExpTmpLocalVar_SilhCol;
                        }
                    }

                    //For visualization and check of the distribution of the remaining points
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_SilhCam = hv_SilhCam.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_Cam)
                            );
                            hv_SilhCam.Dispose();
                            hv_SilhCam = ExpTmpLocalVar_SilhCam;
                        }
                    }

                    hv_PX.Dispose();
                    hv_PY.Dispose();
                    hv_PZ.Dispose();
                    hv_QX.Dispose();
                    hv_QY.Dispose();
                    hv_QZ.Dispose();
                    HOperatorSet.GetLineOfSight(
                        hv_Row,
                        hv_Column,
                        hv_CamParam,
                        out hv_PX,
                        out hv_PY,
                        out hv_PZ,
                        out hv_QX,
                        out hv_QY,
                        out hv_QZ
                    );
                    hv_HomMat3D.Dispose();
                    HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                    hv_PX0.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PX0 = hv_HomMat3D.TupleSelect(3);
                    }
                    hv_PY0.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PY0 = hv_HomMat3D.TupleSelect(7);
                    }
                    hv_PZ0.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PZ0 = hv_HomMat3D.TupleSelect(11);
                    }
                    hv_QX0.Dispose();
                    hv_QY0.Dispose();
                    hv_QZ0.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3D,
                        hv_QX,
                        hv_QY,
                        hv_QZ,
                        out hv_QX0,
                        out hv_QY0,
                        out hv_QZ0
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A2x = hv_A2x.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PX0)
                            );
                            hv_A2x.Dispose();
                            hv_A2x = ExpTmpLocalVar_A2x;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A2y = hv_A2y.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PY0)
                            );
                            hv_A2y.Dispose();
                            hv_A2y = ExpTmpLocalVar_A2y;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A2z = hv_A2z.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PZ0)
                            );
                            hv_A2z.Dispose();
                            hv_A2z = ExpTmpLocalVar_A2z;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B2x = hv_B2x.TupleConcat(hv_QX0 - hv_PX0);
                            hv_B2x.Dispose();
                            hv_B2x = ExpTmpLocalVar_B2x;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B2y = hv_B2y.TupleConcat(hv_QY0 - hv_PY0);
                            hv_B2y.Dispose();
                            hv_B2y = ExpTmpLocalVar_B2y;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B2z = hv_B2z.TupleConcat(hv_QZ0 - hv_PZ0);
                            hv_B2z.Dispose();
                            hv_B2z = ExpTmpLocalVar_B2z;
                        }
                    }
                }

                //Determine the number of points from each camera
                HTuple end_val75 = hv_NumCameras - 1;
                HTuple step_val75 = 1;
                for (
                    hv_CamI = 0;
                    hv_CamI.Continue(end_val75, step_val75);
                    hv_CamI = hv_CamI.TupleAdd(step_val75)
                )
                {
                    if (hv_NumPoints == null)
                        hv_NumPoints = new HTuple();
                    hv_NumPoints[hv_CamI] = (
                        (((hv_SilhCam.TupleFind(hv_CamI))).TupleNotEqualElem(-1))
                    ).TupleSum();
                }

                //Initial values for the cylinder axis (x := A1 + t*B1)
                hv_A1x.Dispose();
                hv_A1x = 0.0;
                hv_A1y.Dispose();
                hv_A1y = 0.0;
                hv_A1z.Dispose();
                hv_A1z = 0;
                hv_B1x.Dispose();
                hv_B1x = 0.0;
                hv_B1y.Dispose();
                hv_B1y = 0.0;
                hv_B1z.Dispose();
                hv_B1z = 1;
                hv_Dx.Dispose();
                hv_Dx = 99999;
                hv_ErrorLog.Dispose();
                hv_ErrorLog = new HTuple();
                hv_Iter.Dispose();
                hv_Iter = 0;
                hv_IterInter.Dispose();
                hv_IterInter = 0;
                hv_MaxIter.Dispose();
                hv_MaxIter = 100;
                hv_MaxIterInter.Dispose();
                hv_MaxIterInter = 5;
                hv_LastError.Dispose();
                hv_LastError = 99999;
                hv_SDevFactor.Dispose();
                hv_SDevFactor = 5.0;
                while ((int)(new HTuple(hv_Iter.TupleLess(hv_MaxIter))) != 0)
                {
                    hv_Dist.Dispose();
                    distance_skew_lines(
                        hv_A1x,
                        hv_A1y,
                        hv_A1z,
                        hv_B1x,
                        hv_B1y,
                        hv_B1z,
                        hv_A2x,
                        hv_A2y,
                        hv_A2z,
                        hv_B2x,
                        hv_B2y,
                        hv_B2z,
                        out hv_Dist
                    );
                    hv_E.Dispose();
