                hv_SilhCol = new HTuple();
            HTuple hv_SilhCam = new HTuple(),
                hv_SilhRowElim = new HTuple();
            HTuple hv_SilhColElim = new HTuple(),
                hv_SilhCamElim = new HTuple();
            HTuple hv_Cam = new HTuple(),
                hv_CamParam = new HTuple();
            HTuple hv_CamPose = new HTuple(),
                hv_Row = new HTuple();
            HTuple hv_Column = new HTuple(),
                hv_FuzzyFunction = new HTuple();
            HTuple hv_I = new HTuple(),
                hv_RowEdgeFirst = new HTuple();
            HTuple hv_ColumnEdgeFirst = new HTuple(),
                hv_AmplitudeFirst = new HTuple();
            HTuple hv_RowEdgeSecond = new HTuple(),
                hv_ColumnEdgeSecond = new HTuple();
            HTuple hv_AmplitudeSecond = new HTuple(),
                hv_RowPairCenter = new HTuple();
            HTuple hv_ColumnPairCenter = new HTuple(),
                hv_FuzzyScore = new HTuple();
            HTuple hv_IntraDistance = new HTuple(),
                hv_SIF = new HTuple();
            HTuple hv_SIS = new HTuple(),
                hv_PX = new HTuple(),
                hv_PY = new HTuple();
            HTuple hv_PZ = new HTuple(),
                hv_QX = new HTuple(),
                hv_QY = new HTuple();
            HTuple hv_QZ = new HTuple(),
                hv_HomMat3D = new HTuple();
            HTuple hv_PX0 = new HTuple(),
                hv_PY0 = new HTuple(),
                hv_PZ0 = new HTuple();
            HTuple hv_QX0 = new HTuple(),
                hv_QY0 = new HTuple(),
                hv_QZ0 = new HTuple();
            HTuple hv_CamI = new HTuple(),
                hv_NumPoints = new HTuple();
            HTuple hv_A1x = new HTuple(),
                hv_A1y = new HTuple(),
                hv_A1z = new HTuple();
            HTuple hv_B1x = new HTuple(),
                hv_B1y = new HTuple(),
                hv_B1z = new HTuple();
            HTuple hv_Dx = new HTuple(),
                hv_ErrorLog = new HTuple();
            HTuple hv_Iter = new HTuple(),
                hv_IterInter = new HTuple();
            HTuple hv_MaxIter = new HTuple(),
                hv_MaxIterInter = new HTuple();
            HTuple hv_LastError = new HTuple(),
                hv_SDevFactor = new HTuple();
            HTuple hv_Dist = new HTuple(),
                hv_E = new HTuple(),
                hv_Delta = new HTuple();
            HTuple hv_DistTmp = new HTuple(),
                hv_DistDAx = new HTuple();
            HTuple hv_DistDAy = new HTuple(),
                hv_DistDBx = new HTuple();
            HTuple hv_DistDBy = new HTuple(),
                hv_A = new HTuple();
            HTuple hv_SeqR = new HTuple(),
                hv_SeqC = new HTuple();
            HTuple hv_y = new HTuple(),
                hv_X = new HTuple(),
                hv_Values = new HTuple();
            HTuple hv_SDevE = new HTuple(),
                hv_MaskUse = new HTuple();
            HTuple hv_SilhCamTmp = new HTuple(),
                hv_CamOk = new HTuple();
            HTuple hv_NumPointsRemaining = new HTuple(),
                hv_CamPose0 = new HTuple();
            HTuple hv_Foot = new HTuple(),
                hv_XAxis = new HTuple();
            HTuple hv_ZAxis = new HTuple(),
                hv_YAxis = new HTuple();
            HTuple hv_HomMat3DCylinderEst = new HTuple(),
                hv_PoseCylinderEst = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_ImageRectified);
            hv_PoseCylinder = new HTuple();
            hv_CameraSetupModelZeroDistInCylinderOrigin = new HTuple();
            try
            {
                //Set origin of camera setup model to approximate cylinder pose
                hv_SerializedItemHandle.Dispose();
                HOperatorSet.SerializeCameraSetupModel(
                    hv_CameraSetupModelZeroDist,
                    out hv_SerializedItemHandle
                );
                hv_CameraSetupModelZeroDistCylApprox.Dispose();
                HOperatorSet.DeserializeCameraSetupModel(
                    hv_SerializedItemHandle,
                    out hv_CameraSetupModelZeroDistCylApprox
                );
                HOperatorSet.SetCameraSetupParam(
                    hv_CameraSetupModelZeroDistCylApprox,
                    "general",
                    "coord_transf_pose",
                    hv_PoseCylinderApprox
                );

                //Collect possible silhouette points from all images
                hv_A2x.Dispose();
                hv_A2x = new HTuple();
                hv_A2y.Dispose();
                hv_A2y = new HTuple();
                hv_A2z.Dispose();
                hv_A2z = new HTuple();
                hv_B2x.Dispose();
                hv_B2x = new HTuple();
                hv_B2y.Dispose();
                hv_B2y = new HTuple();
                hv_B2z.Dispose();
                hv_B2z = new HTuple();
                //Collect image coordinates for visualization and analysis
                hv_SilhRow.Dispose();
                hv_SilhRow = new HTuple();
                hv_SilhCol.Dispose();
                hv_SilhCol = new HTuple();
                hv_SilhCam.Dispose();
                hv_SilhCam = new HTuple();

                hv_SilhRowElim.Dispose();
                hv_SilhRowElim = new HTuple();
                hv_SilhColElim.Dispose();
                hv_SilhColElim = new HTuple();
                hv_SilhCamElim.Dispose();
                hv_SilhCamElim = new HTuple();

                HTuple end_val21 = hv_NumCameras - 1;
                HTuple step_val21 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val21, step_val21);
                    hv_Cam = hv_Cam.TupleAdd(step_val21)
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageRectified.Dispose();
                        HOperatorSet.SelectObj(
                            ho_ImagesRectified,
                            out ho_ImageRectified,
                            hv_Cam + 1
                        );
                    }
                    hv_CamParam.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDistCylApprox,
                        hv_Cam,
                        "params",
                        out hv_CamParam
                    );
                    hv_CamPose.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDistCylApprox,
                        hv_Cam,
                        "pose",
                        out hv_CamPose
                    );
                    hv_Row.Dispose();
                    hv_Row = new HTuple();
                    hv_Column.Dispose();
                    hv_Column = new HTuple();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_FuzzyFunction.Dispose();
                        HOperatorSet.CreateFunct1dPairs(
                            (
                                (
                                    (
                                        (
                                            (
                                                ((hv_MinPairDist.TupleSelect(hv_Cam)) - 10)
                                            ).TupleConcat(hv_MinPairDist.TupleSelect(hv_Cam))
                                        )
                                    ).TupleConcat(
                                        (hv_MaxPairDist.TupleSelect(hv_Cam))
                                            / (hv_SilhouetteMaxTilt.TupleCos())
                                    )
                                )
                            ).TupleConcat(
                                (
                                    (hv_MaxPairDist.TupleSelect(hv_Cam))
                                    / (hv_SilhouetteMaxTilt.TupleCos())
                                ) + 10
                            ),
                            (((new HTuple(0)).TupleConcat(1)).TupleConcat(1)).TupleConcat(0),
                            out hv_FuzzyFunction
                        );
                    }
                    for (
                        hv_I = 0;
                        (int)hv_I <= (int)((new HTuple(hv_MeasureHandles.TupleLength())) - 1);
                        hv_I = (int)hv_I + 1
                    )
                    {
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetFuzzyMeasure(
                                hv_MeasureHandles.TupleSelect(hv_I),
                                "size",
                                hv_FuzzyFunction
                            );
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_RowEdgeFirst.Dispose();
                            hv_ColumnEdgeFirst.Dispose();
                            hv_AmplitudeFirst.Dispose();
                            hv_RowEdgeSecond.Dispose();
                            hv_ColumnEdgeSecond.Dispose();
                            hv_AmplitudeSecond.Dispose();
                            hv_RowPairCenter.Dispose();
                            hv_ColumnPairCenter.Dispose();
                            hv_FuzzyScore.Dispose();
                            hv_IntraDistance.Dispose();
                            HOperatorSet.FuzzyMeasurePairing(
                                ho_ImageRectified,
                                hv_MeasureHandles.TupleSelect(hv_I),
                                hv_SilhouetteMeasureSigma,
                                hv_SilhouetteMeasureThreshold,
                                0.5,
                                "all",
                                "no_restriction",
                                0,
                                out hv_RowEdgeFirst,
                                out hv_ColumnEdgeFirst,
                                out hv_AmplitudeFirst,
                                out hv_RowEdgeSecond,
                                out hv_ColumnEdgeSecond,
                                out hv_AmplitudeSecond,
                                out hv_RowPairCenter,
                                out hv_ColumnPairCenter,
                                out hv_FuzzyScore,
                                out hv_IntraDistance
                            );
                        }
                        //Select only first and last edge if the background can be assumed
                        //to be textureless
                        if (
                            (int)(
                                new HTuple(
                                    (new HTuple(hv_RowEdgeFirst.TupleLength())).TupleGreater(0)
                                )
                            ) != 0
                        )
                        {
                            hv_SIF.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_SIF = (
                                    new HTuple(((-hv_RowEdgeFirst)).TupleSortIndex())
                                ).TupleSelect(0);
                            }
                            hv_SIS.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_SIS = (
                                    new HTuple(hv_RowEdgeSecond.TupleSortIndex())
                                ).TupleSelect(0);
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_Row = (
                                        (hv_Row.TupleConcat(hv_RowEdgeFirst.TupleSelect(hv_SIF)))
                                    ).TupleConcat(hv_RowEdgeSecond.TupleSelect(hv_SIS));
                                    hv_Row.Dispose();
                                    hv_Row = ExpTmpLocalVar_Row;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_Column = (
                                        (
                                            hv_Column.TupleConcat(
                                                hv_ColumnEdgeFirst.TupleSelect(hv_SIF)
                                            )
                                        )
                                    ).TupleConcat(hv_ColumnEdgeSecond.TupleSelect(hv_SIS));
                                    hv_Column.Dispose();
                                    hv_Column = ExpTmpLocalVar_Column;
                                }
                            }
                        }
                    }

                    //Only for visualization of selected points
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_SilhRow = hv_SilhRow.TupleConcat(hv_Row);
                            hv_SilhRow.Dispose();
                            hv_SilhRow = ExpTmpLocalVar_SilhRow;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_SilhCol = hv_SilhCol.TupleConcat(hv_Column);
                            hv_SilhCol.Dispose();
                            hv_SilhCol = ExpTmpLocalVar_SilhCol;
                        }
                    }

                    //For visualization and check of the distribution of the remaining points
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_SilhCam = hv_SilhCam.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_Cam)
                            );
                            hv_SilhCam.Dispose();
                            hv_SilhCam = ExpTmpLocalVar_SilhCam;
                        }
                    }

                    hv_PX.Dispose();
                    hv_PY.Dispose();
                    hv_PZ.Dispose();
                    hv_QX.Dispose();
                    hv_QY.Dispose();
                    hv_QZ.Dispose();
                    HOperatorSet.GetLineOfSight(
                        hv_Row,
                        hv_Column,
                        hv_CamParam,
                        out hv_PX,
                        out hv_PY,
                        out hv_PZ,
                        out hv_QX,
                        out hv_QY,
                        out hv_QZ
                    );
                    hv_HomMat3D.Dispose();
                    HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                    hv_PX0.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PX0 = hv_HomMat3D.TupleSelect(3);
                    }
                    hv_PY0.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PY0 = hv_HomMat3D.TupleSelect(7);
                    }
                    hv_PZ0.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_PZ0 = hv_HomMat3D.TupleSelect(11);
                    }
                    hv_QX0.Dispose();
                    hv_QY0.Dispose();
                    hv_QZ0.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3D,
                        hv_QX,
                        hv_QY,
                        hv_QZ,
                        out hv_QX0,
                        out hv_QY0,
                        out hv_QZ0
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A2x = hv_A2x.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PX0)
                            );
                            hv_A2x.Dispose();
                            hv_A2x = ExpTmpLocalVar_A2x;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A2y = hv_A2y.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PY0)
                            );
                            hv_A2y.Dispose();
                            hv_A2y = ExpTmpLocalVar_A2y;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A2z = hv_A2z.TupleConcat(
                                HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PZ0)
                            );
                            hv_A2z.Dispose();
                            hv_A2z = ExpTmpLocalVar_A2z;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B2x = hv_B2x.TupleConcat(hv_QX0 - hv_PX0);
                            hv_B2x.Dispose();
                            hv_B2x = ExpTmpLocalVar_B2x;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B2y = hv_B2y.TupleConcat(hv_QY0 - hv_PY0);
                            hv_B2y.Dispose();
                            hv_B2y = ExpTmpLocalVar_B2y;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B2z = hv_B2z.TupleConcat(hv_QZ0 - hv_PZ0);
                            hv_B2z.Dispose();
                            hv_B2z = ExpTmpLocalVar_B2z;
                        }
                    }
                }

                //Determine the number of points from each camera
                HTuple end_val63 = hv_NumCameras - 1;
                HTuple step_val63 = 1;
                for (
                    hv_CamI = 0;
                    hv_CamI.Continue(end_val63, step_val63);
                    hv_CamI = hv_CamI.TupleAdd(step_val63)
                )
                {
                    if (hv_NumPoints == null)
                        hv_NumPoints = new HTuple();
                    hv_NumPoints[hv_CamI] = (
                        (((hv_SilhCam.TupleFind(hv_CamI))).TupleNotEqualElem(-1))
                    ).TupleSum();
                }

                //Initial values for the cylinder axis (x := A1 + t*B1)
                hv_A1x.Dispose();
                hv_A1x = 0.0;
                hv_A1y.Dispose();
                hv_A1y = 0.0;
                hv_A1z.Dispose();
                hv_A1z = 0;
                hv_B1x.Dispose();
                hv_B1x = 0.0;
                hv_B1y.Dispose();
                hv_B1y = 0.0;
                hv_B1z.Dispose();
                hv_B1z = 1;
                hv_Dx.Dispose();
                hv_Dx = 99999;
                hv_ErrorLog.Dispose();
                hv_ErrorLog = new HTuple();
                hv_Iter.Dispose();
                hv_Iter = 0;
                hv_IterInter.Dispose();
                hv_IterInter = 0;
                hv_MaxIter.Dispose();
                hv_MaxIter = 10;
                hv_MaxIterInter.Dispose();
                hv_MaxIterInter = 5;
                hv_LastError.Dispose();
                hv_LastError = 99999;
                hv_SDevFactor.Dispose();
                hv_SDevFactor = 5.0;
                while ((int)(new HTuple(hv_Iter.TupleLess(hv_MaxIter))) != 0)
                {
                    hv_Dist.Dispose();
                    distance_skew_lines(
                        hv_A1x,
                        hv_A1y,
                        hv_A1z,
                        hv_B1x,
                        hv_B1y,
                        hv_B1z,
                        hv_A2x,
                        hv_A2y,
                        hv_A2z,
                        hv_B2x,
                        hv_B2y,
                        hv_B2z,
                        out hv_Dist
                    );
                    hv_E.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_E = hv_CylinderRadius - hv_Dist;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_ErrorLog = hv_ErrorLog.TupleConcat(
                                hv_E.TupleMean()
                            );
                            hv_ErrorLog.Dispose();
                            hv_ErrorLog = ExpTmpLocalVar_ErrorLog;
                        }
                    }
                    hv_Delta.Dispose();
                    hv_Delta = 0.001;
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistTmp.Dispose();
                        distance_skew_lines(
                            hv_A1x + hv_Delta,
                            hv_A1y,
                            hv_A1z,
                            hv_B1x,
                            hv_B1y,
                            hv_B1z,
                            hv_A2x,
                            hv_A2y,
                            hv_A2z,
                            hv_B2x,
                            hv_B2y,
                            hv_B2z,
                            out hv_DistTmp
                        );
                    }
                    hv_DistDAx.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistDAx = (hv_DistTmp - hv_Dist) / hv_Delta;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistTmp.Dispose();
                        distance_skew_lines(
                            hv_A1x,
                            hv_A1y + hv_Delta,
                            hv_A1z,
                            hv_B1x,
                            hv_B1y,
                            hv_B1z,
                            hv_A2x,
                            hv_A2y,
                            hv_A2z,
                            hv_B2x,
                            hv_B2y,
                            hv_B2z,
                            out hv_DistTmp
                        );
                    }
                    hv_DistDAy.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistDAy = (hv_DistTmp - hv_Dist) / hv_Delta;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistTmp.Dispose();
                        distance_skew_lines(
                            hv_A1x,
                            hv_A1y,
                            hv_A1z,
                            hv_B1x + hv_Delta,
                            hv_B1y,
                            hv_B1z,
                            hv_A2x,
                            hv_A2y,
                            hv_A2z,
                            hv_B2x,
                            hv_B2y,
                            hv_B2z,
                            out hv_DistTmp
                        );
                    }
                    hv_DistDBx.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistDBx = (hv_DistTmp - hv_Dist) / hv_Delta;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistTmp.Dispose();
                        distance_skew_lines(
                            hv_A1x,
                            hv_A1y,
                            hv_A1z,
                            hv_B1x,
                            hv_B1y + hv_Delta,
                            hv_B1z,
                            hv_A2x,
                            hv_A2y,
                            hv_A2z,
                            hv_B2x,
                            hv_B2y,
                            hv_B2z,
                            out hv_DistTmp
                        );
                    }
                    hv_DistDBy.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DistDBy = (hv_DistTmp - hv_Dist) / hv_Delta;
                    }

                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_A.Dispose();
                        HOperatorSet.CreateMatrix(new HTuple(hv_A2x.TupleLength()), 4, 0, out hv_A);
                    }
                    hv_SeqR.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_SeqR = HTuple.TupleGenSequence(
                            0,
                            (new HTuple(hv_A2x.TupleLength())) - 1,
                            1
                        );
                    }
                    hv_SeqC.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_SeqC = HTuple.TupleGenConst(new HTuple(hv_A2x.TupleLength()), 0);
                    }
                    HOperatorSet.SetValueMatrix(hv_A, hv_SeqR, hv_SeqC, hv_DistDAx);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        HOperatorSet.SetValueMatrix(hv_A, hv_SeqR, hv_SeqC + 1, hv_DistDAy);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        HOperatorSet.SetValueMatrix(hv_A, hv_SeqR, hv_SeqC + 2, hv_DistDBx);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        HOperatorSet.SetValueMatrix(hv_A, hv_SeqR, hv_SeqC + 3, hv_DistDBy);
                    }

                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_y.Dispose();
                        HOperatorSet.CreateMatrix(new HTuple(hv_A2x.TupleLength()), 1, 0, out hv_y);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        HOperatorSet.SetValueMatrix(
                            hv_y,
                            hv_SeqR,
                            hv_SeqC,
                            hv_CylinderRadius - hv_Dist
                        );
                    }

                    //Solve the least squares equation system (x := (ATA)^-1*ATy)
                    hv_X.Dispose();
                    HOperatorSet.SolveMatrix(hv_A, "general", 0, hv_y, out hv_X);
                    hv_Values.Dispose();
                    HOperatorSet.GetFullMatrix(hv_X, out hv_Values);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A1x = hv_A1x + (hv_Values.TupleSelect(0));
                            hv_A1x.Dispose();
                            hv_A1x = ExpTmpLocalVar_A1x;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_A1y = hv_A1y + (hv_Values.TupleSelect(1));
                            hv_A1y.Dispose();
                            hv_A1y = ExpTmpLocalVar_A1y;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B1x = hv_B1x + (hv_Values.TupleSelect(2));
                            hv_B1x.Dispose();
                            hv_B1x = ExpTmpLocalVar_B1x;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_B1y = hv_B1y + (hv_Values.TupleSelect(3));
                            hv_B1y.Dispose();
                            hv_B1y = ExpTmpLocalVar_B1y;
                        }
                    }

                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Iter = hv_Iter + 1;
                            hv_Iter.Dispose();
                            hv_Iter = ExpTmpLocalVar_Iter;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_IterInter = hv_IterInter + 1;
                            hv_IterInter.Dispose();
                            hv_IterInter = ExpTmpLocalVar_IterInter;
                        }
                    }
                    //Eliminate gross errors
                    if (
                        (int)(new HTuple((new HTuple(hv_ErrorLog.TupleLength())).TupleGreater(3)))
                        != 0
                    )
                    {
                        if (
                            (int)(
                                (
                                    new HTuple(
                                        (
                                            new HTuple(
                                                (
                                                    (
                                                        hv_ErrorLog.TupleSelectRange(
                                                            (new HTuple(hv_ErrorLog.TupleLength()))
                                                                - 3,
                                                            (new HTuple(hv_ErrorLog.TupleLength()))
                                                                - 1
                                                        )
                                                    )
                                                ).TupleDeviation()
                                            )
                                        ).TupleLess(1e-5)
                                    )
                                ).TupleOr(
                                    new HTuple(hv_IterInter.TupleGreaterEqual(hv_MaxIterInter))
                                )
                            ) != 0
                        )
                        {
                            hv_IterInter.Dispose();
                            hv_IterInter = 0;
                            if (
                                (int)(
                                    (
                                        new HTuple(
                                            (
                                                new HTuple(
                                                    (
                                                        (
                                                            (
                                                                (
                                                                    hv_ErrorLog.TupleSelect(
                                                                        (
                                                                            new HTuple(
                                                                                hv_ErrorLog.TupleLength()
                                                                            )
                                                                        ) - 1
                                                                    )
                                                                )
                                                            ).TupleFabs()
                                                        )
                                                    ).TupleLess(hv_MaxError)
                                                )
                                            ).TupleAnd(
                                                new HTuple(
                                                    (
                                                        (
                                                            (
                                                                (
                                                                    hv_LastError
                                                                    - (
                                                                        hv_ErrorLog.TupleSelect(
                                                                            (
                                                                                new HTuple(
                                                                                    hv_ErrorLog.TupleLength()
                                                                                )
                                                                            ) - 1
                                                                        )
                                                                    )
                                                                )
                                                            ).TupleFabs()
                                                        )
                                                    ).TupleLess(1e-5)
                                                )
                                            )
                                        )
                                    ).TupleAnd(new HTuple(hv_SDevFactor.TupleLessEqual(3.0)))
                                ) != 0
                            )
                            {
                                //Quit least squares estimation loop
                                hv_MaxIter.Dispose();
                                hv_MaxIter = -1;
                                continue;
                            }
                            hv_LastError.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_LastError = hv_ErrorLog.TupleSelect(
                                    (new HTuple(hv_ErrorLog.TupleLength())) - 1
                                );
                            }

                            //Determine gross errors and eliminate them
                            hv_SDevE.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_SDevE = ((hv_E.TupleFabs())).TupleDeviation();
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_SDevFactor = (
                                        ((new HTuple(3.0)).TupleConcat(hv_SDevFactor - 0.5))
                                    ).TupleMax();
                                    hv_SDevFactor.Dispose();
                                    hv_SDevFactor = ExpTmpLocalVar_SDevFactor;
                                }
                            }
                            hv_MaskUse.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_MaskUse = ((hv_E.TupleFabs())).TupleLessElem(
                                    hv_SDevFactor * hv_SDevE
                                );
                            }
                            //Ensure that some errors are eliminated
                            while (
                                (int)(
                                    (new HTuple(((hv_MaskUse.TupleMin())).TupleEqual(1))).TupleAnd(
                                        new HTuple(hv_SDevFactor.TupleGreater(3.0))
                                    )
                                ) != 0
                            )
                            {
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    {
                                        HTuple ExpTmpLocalVar_SDevFactor = (
                                            ((new HTuple(3.0)).TupleConcat(hv_SDevFactor - 0.1))
                                        ).TupleMax();
                                        hv_SDevFactor.Dispose();
                                        hv_SDevFactor = ExpTmpLocalVar_SDevFactor;
                                    }
                                }
                                hv_MaskUse.Dispose();
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    hv_MaskUse = ((hv_E.TupleFabs())).TupleLessElem(
                                        hv_SDevFactor * hv_SDevE
                                    );
                                }
                            }

                            //Ensure that there are at least 20% of the initial points in at least three cameras
                            hv_SilhCamTmp.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_SilhCamTmp = hv_SilhCam.TupleSelectMask(hv_MaskUse);
                            }
                            hv_CamOk.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_CamOk = HTuple.TupleGenConst(hv_NumCameras, 0);
                            }
                            HTuple end_val142 = hv_NumCameras - 1;
                            HTuple step_val142 = 1;
                            for (
                                hv_CamI = 0;
                                hv_CamI.Continue(end_val142, step_val142);
                                hv_CamI = hv_CamI.TupleAdd(step_val142)
                            )
                            {
                                if (hv_NumPointsRemaining == null)
                                    hv_NumPointsRemaining = new HTuple();
                                hv_NumPointsRemaining[hv_CamI] = (
                                    (((hv_SilhCamTmp.TupleFind(hv_CamI))).TupleNotEqualElem(-1))
                                ).TupleSum();
                            }
                            if (
                                (int)(
                                    new HTuple(
                                        (
                                            (
                                                (
                                                    (
                                                        (
                                                            (
                                                                hv_NumPointsRemaining
                                                                / (hv_NumPoints.TupleReal())
                                                            )
                                                        ).TupleGreaterEqualElem(0.3)
                                                    )
                                                ).TupleSum()
                                            )
                                        ).TupleLessEqual(3)
                                    )
                                ) != 0
                            )
                            {
                                //Quit least squares estimation loop because the distribution of the points would be bad
                                hv_MaxIter.Dispose();
                                hv_MaxIter = -1;
                                continue;
                            }

                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_A2x = hv_A2x.TupleSelectMask(hv_MaskUse);
                                    hv_A2x.Dispose();
                                    hv_A2x = ExpTmpLocalVar_A2x;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_A2y = hv_A2y.TupleSelectMask(hv_MaskUse);
                                    hv_A2y.Dispose();
                                    hv_A2y = ExpTmpLocalVar_A2y;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_A2z = hv_A2z.TupleSelectMask(hv_MaskUse);
                                    hv_A2z.Dispose();
                                    hv_A2z = ExpTmpLocalVar_A2z;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_B2x = hv_B2x.TupleSelectMask(hv_MaskUse);
                                    hv_B2x.Dispose();
                                    hv_B2x = ExpTmpLocalVar_B2x;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_B2y = hv_B2y.TupleSelectMask(hv_MaskUse);
                                    hv_B2y.Dispose();
                                    hv_B2y = ExpTmpLocalVar_B2y;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_B2z = hv_B2z.TupleSelectMask(hv_MaskUse);
                                    hv_B2z.Dispose();
                                    hv_B2z = ExpTmpLocalVar_B2z;
                                }
                            }

                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_SilhRowElim = hv_SilhRowElim.TupleConcat(
                                        hv_SilhRow.TupleSelectMask(1 - hv_MaskUse)
                                    );
                                    hv_SilhRowElim.Dispose();
                                    hv_SilhRowElim = ExpTmpLocalVar_SilhRowElim;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_SilhColElim = hv_SilhColElim.TupleConcat(
                                        hv_SilhCol.TupleSelectMask(1 - hv_MaskUse)
                                    );
                                    hv_SilhColElim.Dispose();
                                    hv_SilhColElim = ExpTmpLocalVar_SilhColElim;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_SilhCamElim = hv_SilhCamElim.TupleConcat(
                                        hv_SilhCam.TupleSelectMask(1 - hv_MaskUse)
                                    );
                                    hv_SilhCamElim.Dispose();
                                    hv_SilhCamElim = ExpTmpLocalVar_SilhCamElim;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                {
                                    HTuple ExpTmpLocalVar_SilhRow = hv_SilhRow.TupleSelectMask(
                                        hv_MaskUse
                                    );
                                    hv_SilhRow.Dispose();
