                        hv_CamPose0.TupleSelectRange(0, 2),
                        ((hv_A1x.TupleConcat(hv_A1y))).TupleConcat(hv_A1z),
                        ((hv_B1x.TupleConcat(hv_B1y))).TupleConcat(hv_B1z),
                        out hv_Foot
                    );
                }
                hv_XAxis.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_XAxis = hv_Foot - (hv_CamPose0.TupleSelectRange(0, 2));
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_XAxis =
                            hv_XAxis / (((((hv_XAxis * hv_XAxis)).TupleSum())).TupleSqrt());
                        hv_XAxis.Dispose();
                        hv_XAxis = ExpTmpLocalVar_XAxis;
                    }
                }
                hv_ZAxis.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ZAxis = new HTuple();
                    hv_ZAxis = hv_ZAxis.TupleConcat(hv_B1x, hv_B1y, hv_B1z);
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_ZAxis =
                            hv_ZAxis / (((((hv_ZAxis * hv_ZAxis)).TupleSum())).TupleSqrt());
                        hv_ZAxis.Dispose();
                        hv_ZAxis = ExpTmpLocalVar_ZAxis;
                    }
                }
                hv_YAxis.Dispose();
                cross_product(hv_ZAxis, hv_XAxis, out hv_YAxis);
                hv_HomMat3DCylinderEst.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
