                    hv_X = new HTuple(),
                    hv_Values = new HTuple();
                HTuple hv_SDevE = new HTuple(),
                    hv_MaskUse = new HTuple();
                HTuple hv_SilhCamTmp = new HTuple(),
                    hv_CamOk = new HTuple();
                HTuple hv_NumPointsRemaining = new HTuple(),
                    hv_CamPose0 = new HTuple();
                HTuple hv_Foot = new HTuple(),
                    hv_XAxis = new HTuple();
                HTuple hv_ZAxis = new HTuple(),
                    hv_YAxis = new HTuple();
                HTuple hv_HomMat3DCylinderEst = new HTuple(),
                    hv_PoseCylinderEst = new HTuple();
                HTuple hv_WL = new HTuple(),
                    hv_HL = new HTuple(),
                    hv_WH = new HTuple();
                HTuple hv_ObjectModel3DCylinder = new HTuple(),
                    hv_WindowHandleI = new HTuple();
                HTuple hv_PoseInvert = new HTuple(),
                    hv_UsedId = new HTuple();
                HTuple hv_RejectedId = new HTuple();
                // Initialize local and output iconic variables
                HOperatorSet.GenEmptyObj(out ho_ImageRectified);
                HOperatorSet.GenEmptyObj(out ho_GrayImage);
                HOperatorSet.GenEmptyObj(out ho_Cross);
                HOperatorSet.GenEmptyObj(out ho_Image);
                HOperatorSet.GenEmptyObj(out ho_ImageCyl);
                HOperatorSet.GenEmptyObj(out ho_Region);
                HOperatorSet.GenEmptyObj(out ho_Contours);
                HOperatorSet.GenEmptyObj(out ho_CrossUsed);
                hv_PoseCylinder = new HTuple();
                hv_Quality = new HTuple();
                hv_CameraSetupModelZeroDistInCylinderOrigin = new HTuple();
                hv_RadiusEstimated = new HTuple();
                try
                {
                    //global tuple DisplayIntermediateResults
                    //global tuple WindowWidthLimit
                    //global tuple WindowHeightLimit

                    //Determine approximate pose of the cylinder
                    //assuming that it stands upright in the center of the cameras.
                    hv_XCam.Dispose();
                    hv_XCam = new HTuple();
                    hv_YCam.Dispose();
                    hv_YCam = new HTuple();
                    hv_ZCam.Dispose();
                    hv_ZCam = new HTuple();
                    HTuple end_val9 = hv_NumCameras - 1;
                    HTuple step_val9 = 1;
                    for (
                        hv_Cam = 0;
                        hv_Cam.Continue(end_val9, step_val9);
                        hv_Cam = hv_Cam.TupleAdd(step_val9)
                    )
                    {
                        hv_CamPose.Dispose();
                        HOperatorSet.GetCameraSetupParam(
                            hv_CameraSetupModelZeroDist,
                            hv_Cam,
                            "pose",
                            out hv_CamPose
                        );
                        if (hv_XCam == null)
                            hv_XCam = new HTuple();
                        hv_XCam[hv_Cam] = hv_CamPose.TupleSelect(0);
                        if (hv_YCam == null)
                            hv_YCam = new HTuple();
                        hv_YCam[hv_Cam] = hv_CamPose.TupleSelect(1);
                        if (hv_ZCam == null)
                            hv_ZCam = new HTuple();
                        hv_ZCam[hv_Cam] = hv_CamPose.TupleSelect(2);
                    }
                    hv_CylinderPointApprox.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_CylinderPointApprox = new HTuple();
                        hv_CylinderPointApprox = hv_CylinderPointApprox.TupleConcat(
                            hv_XCam.TupleMean()
                        );
                        hv_CylinderPointApprox = hv_CylinderPointApprox.TupleConcat(
                            hv_YCam.TupleMean()
                        );
                        hv_CylinderPointApprox = hv_CylinderPointApprox.TupleConcat(
                            hv_ZCam.TupleMean()
                        );
                    }
                    hv_LenI.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_LenI =
                            1.0
                            / (
                                (
                                    (((hv_CylinderPointApprox * hv_CylinderPointApprox)).TupleSum())
                                ).TupleSqrt()
                            );
                    }
                    hv_CylinderXTmp.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_CylinderXTmp = hv_CylinderPointApprox * hv_LenI;
                    }
                    hv_NX.Dispose();
                    hv_NY.Dispose();
                    hv_NZ.Dispose();
                    hv_C.Dispose();
                    fit_plane(hv_XCam, hv_YCam, hv_ZCam, out hv_NX, out hv_NY, out hv_NZ, out hv_C);
                    hv_CylinderZTmp.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_CylinderZTmp = new HTuple();
                        hv_CylinderZTmp = hv_CylinderZTmp.TupleConcat(hv_NX, hv_NY, hv_NZ);
