                        HDevWindowStack.Push(hv_WindowHandleI);
                        set_display_font(hv_WindowHandleI, 16, "mono", "true", "false");
                        disp_message(
                            hv_WindowHandleI,
                            (
                                (
                                    new HTuple(
                                        "green: accepted points\n       (assumed to lie on the\n       silhouette)"
                                    )
                                ).TupleConcat("red:   rejected points")
                            ).TupleConcat("blue:  estimated silhouette"),
                            "window",
                            12,
                            12,
                            (
                                (
                                    ((new HTuple("green")).TupleConcat("green")).TupleConcat(
                                        "green"
                                    )
                                ).TupleConcat("red")
                            ).TupleConcat("blue"),
                            "false"
                        );
                        // stop(...); only in hdevelop
                        HTuple end_val276 = hv_NumCameras - 1;
                        HTuple step_val276 = 1;
                        for (
                            hv_Cam = 0;
                            hv_Cam.Continue(end_val276, step_val276);
                            hv_Cam = hv_Cam.TupleAdd(step_val276)
                        )
                        {
                            HDevWindowStack.SetActive(hv_WH.TupleSelect(hv_Cam));
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.CloseWindow(HDevWindowStack.Pop());
                            }
                        }
                        HDevWindowStack.SetActive(hv_WindowHandleI);
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.CloseWindow(HDevWindowStack.Pop());
                        }
                    }
                    ho_ImageRectified.Dispose();
                    ho_GrayImage.Dispose();
                    ho_Cross.Dispose();
                    ho_Image.Dispose();
                    ho_ImageCyl.Dispose();
                    ho_Region.Dispose();
                    ho_Contours.Dispose();
