        public void determine_source_cameras_for_mosaic_parts(
            out HObject ho_Regions,
            HTuple hv_CameraSetupModelZeroDistInCylinderOrigin,
            HTuple hv_NumCameras,
            HTuple hv_CylinderPointsX,
            HTuple hv_CylinderPointsY,
            HTuple hv_CylinderPointsZ,
            HTuple hv_NumPointsPerSlice,
            HTuple hv_MinZI,
            HTuple hv_MaxZI,
            HTuple hv_MosaicWidth,
            HTuple hv_MosaicHeight
        )
        {
            // Local iconic variables

            HObject ho_ImageLabel1,
                ho_ImageLabel;

            // Local control variables

            HTuple hv_CenterSlice = new HTuple(),
                hv_Indices = new HTuple();
            HTuple hv_Positive = new HTuple(),
                hv_Slice0X = new HTuple();
            HTuple hv_Slice0Y = new HTuple(),
                hv_Slice0Z = new HTuple();
            HTuple hv_CamAngle = new HTuple(),
                hv_BestFromCamIdx0 = new HTuple();
            HTuple hv_Cam = new HTuple(),
                hv_CamPose = new HTuple();
            HTuple hv_Vx = new HTuple(),
                hv_Vy = new HTuple(),
                hv_Vz = new HTuple();
            HTuple hv_Scale = new HTuple(),
                hv_Angle = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_Regions);
            HOperatorSet.GenEmptyObj(out ho_ImageLabel1);
            HOperatorSet.GenEmptyObj(out ho_ImageLabel);
            try
            {
                //- First, determine for each point of the central slice from which camera it is seen best
                hv_CenterSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_CenterSlice = (hv_MaxZI - hv_MinZI) / 2;
                }
                hv_Indices.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Indices = HTuple.TupleGenSequence(
                        hv_CenterSlice * hv_NumPointsPerSlice,
                        ((hv_CenterSlice * hv_NumPointsPerSlice) + hv_NumPointsPerSlice) - 1,
                        1
                    );
                }
                //Check for negative indices. This can occur
                //if InteractivelyDefineRegion is true.
                hv_Positive.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Positive = hv_Indices.TupleGreaterEqualElem(0);
                }
                if (
                    (int)(
                        new HTuple(
                            ((hv_Positive.TupleSum())).TupleNotEqual(
                                new HTuple(hv_Positive.TupleLength())
                            )
                        )
                    ) != 0
                )
                {
                    throw new HalconException(
                        "Not enough points on silhouette.\nPlease choose a bigger part of the bottle to be unrolled."
                    );
                }
                hv_Slice0X.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Slice0X = hv_CylinderPointsX.TupleSelect(hv_Indices);
                }
                hv_Slice0Y.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Slice0Y = hv_CylinderPointsY.TupleSelect(hv_Indices);
                }
                hv_Slice0Z.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Slice0Z = hv_CylinderPointsZ.TupleSelect(hv_Indices);
                }
                hv_CamAngle.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_CamAngle = HTuple.TupleGenConst(new HTuple(hv_Slice0X.TupleLength()), -1);
                }
                hv_BestFromCamIdx0.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_BestFromCamIdx0 = HTuple.TupleGenConst(
                        new HTuple(hv_Slice0X.TupleLength()),
                        -1
                    );
                }
                HTuple end_val14 = hv_NumCameras - 1;
                HTuple step_val14 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val14, step_val14);
                    hv_Cam = hv_Cam.TupleAdd(step_val14)
                )
                {
                    hv_CamPose.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDistInCylinderOrigin,
                        hv_Cam,
                        "pose",
                        out hv_CamPose
                    );
                    hv_Vx.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Vx = (hv_CamPose.TupleSelect(0)) - hv_Slice0X;
                    }
                    hv_Vy.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Vy = (hv_CamPose.TupleSelect(1)) - hv_Slice0Y;
                    }
                    hv_Vz.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Vz = (hv_CamPose.TupleSelect(2)) - hv_Slice0Z;
                    }
                    hv_Scale.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Scale =
                            1.0
                            / (
                                (
                                    (((hv_Vx * hv_Vx) + (hv_Vy * hv_Vy)) + (hv_Vz * hv_Vz))
                                ).TupleSqrt()
                            );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Vx = hv_Vx * hv_Scale;
                            hv_Vx.Dispose();
                            hv_Vx = ExpTmpLocalVar_Vx;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Vy = hv_Vy * hv_Scale;
                            hv_Vy.Dispose();
                            hv_Vy = ExpTmpLocalVar_Vy;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Vz = hv_Vz * hv_Scale;
                            hv_Vz.Dispose();
                            hv_Vz = ExpTmpLocalVar_Vz;
                        }
                    }

                    hv_Angle.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Angle =
                            ((hv_Slice0X * hv_Vx) + (hv_Slice0Y * hv_Vy)) + (hv_Slice0Z * hv_Vz);
                    }

                    hv_Indices.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Indices = ((hv_Angle.TupleGreaterElem(hv_CamAngle))).TupleFind(1);
                    }
                    if ((int)(new HTuple(hv_Indices.TupleNotEqual(-1))) != 0)
                    {
                        if (hv_BestFromCamIdx0 == null)
                            hv_BestFromCamIdx0 = new HTuple();
                        hv_BestFromCamIdx0[hv_Indices] = HTuple.TupleGenConst(
                            new HTuple(hv_Indices.TupleLength()),
                            hv_Cam
                        );
                        if (hv_CamAngle == null)
                            hv_CamAngle = new HTuple();
                        hv_CamAngle[hv_Indices] = hv_Angle.TupleSelect(hv_Indices);
                    }
                }
                //- Then, determine the regions in the mosaic image that will be determined from
                //a particular camera image
                ho_ImageLabel1.Dispose();
                HOperatorSet.GenImageConst(out ho_ImageLabel1, "byte", hv_MosaicWidth, 1);
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    HOperatorSet.SetGrayval(
                        ho_ImageLabel1,
                        HTuple.TupleGenConst(hv_MosaicWidth, 0),
                        HTuple.TupleGenSequence(0, hv_MosaicWidth - 1, 1),
                        hv_BestFromCamIdx0
                    );
                }
                ho_ImageLabel.Dispose();
                HOperatorSet.ZoomImageSize(
                    ho_ImageLabel1,
                    out ho_ImageLabel,
                    hv_MosaicWidth,
                    hv_MosaicHeight,
                    "nearest_neighbor"
                );
                ho_Regions.Dispose();
                HOperatorSet.LabelToRegion(ho_ImageLabel, out ho_Regions);
                ho_ImageLabel1.Dispose();
                ho_ImageLabel.Dispose();

                hv_CenterSlice.Dispose();
                hv_Indices.Dispose();
                hv_Positive.Dispose();
                hv_Slice0X.Dispose();
                hv_Slice0Y.Dispose();
                hv_Slice0Z.Dispose();
                hv_CamAngle.Dispose();
                hv_BestFromCamIdx0.Dispose();
                hv_Cam.Dispose();
                hv_CamPose.Dispose();
                hv_Vx.Dispose();
                hv_Vy.Dispose();
                hv_Vz.Dispose();
                hv_Scale.Dispose();
                hv_Angle.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_ImageLabel1.Dispose();
                ho_ImageLabel.Dispose();

                hv_CenterSlice.Dispose();
                hv_Indices.Dispose();
                hv_Positive.Dispose();
                hv_Slice0X.Dispose();
                hv_Slice0Y.Dispose();
                hv_Slice0Z.Dispose();
                hv_CamAngle.Dispose();
                hv_BestFromCamIdx0.Dispose();
                hv_Cam.Dispose();
                hv_CamPose.Dispose();
                hv_Vx.Dispose();
                hv_Vy.Dispose();
                hv_Vz.Dispose();
                hv_Scale.Dispose();
                hv_Angle.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void distance_skew_lines(
            HTuple hv_A1x,
            HTuple hv_A1y,
            HTuple hv_A1z,
            HTuple hv_B1x,
            HTuple hv_B1y,
            HTuple hv_B1z,
            HTuple hv_A2x,
            HTuple hv_A2y,
            HTuple hv_A2z,
            HTuple hv_B2x,
            HTuple hv_B2y,
            HTuple hv_B2z,
            out HTuple hv_Dist
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_DAx = new HTuple(),
                hv_DAy = new HTuple();
            HTuple hv_DAz = new HTuple(),
                hv_BCBx = new HTuple(),
                hv_BCBy = new HTuple();
            HTuple hv_BCBz = new HTuple();
            // Initialize local and output iconic variables
            hv_Dist = new HTuple();
            try
            {
                hv_DAx.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DAx = hv_A1x - hv_A2x;
                }
                hv_DAy.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DAy = hv_A1y - hv_A2y;
                }
                hv_DAz.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DAz = hv_A1z - hv_A2z;
                }
                hv_BCBx.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_BCBx = (hv_B1y * hv_B2z) - (hv_B1z * hv_B2y);
                }
                hv_BCBy.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_BCBy = (hv_B1z * hv_B2x) - (hv_B1x * hv_B2z);
                }
                hv_BCBz.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_BCBz = (hv_B1x * hv_B2y) - (hv_B1y * hv_B2x);
                }
                hv_Dist.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Dist =
                        (
                            (
                                (((hv_DAx * hv_BCBx) + (hv_DAy * hv_BCBy)) + (hv_DAz * hv_BCBz))
                            ).TupleFabs()
                        )
                        / (
                            (
                                (((hv_BCBx * hv_BCBx) + (hv_BCBy * hv_BCBy)) + (hv_BCBz * hv_BCBz))
                            ).TupleSqrt()
                        );
                }

                hv_DAx.Dispose();
                hv_DAy.Dispose();
                hv_DAz.Dispose();
                hv_BCBx.Dispose();
                hv_BCBy.Dispose();
                hv_BCBz.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                hv_DAx.Dispose();
                hv_DAy.Dispose();
                hv_DAz.Dispose();
                hv_BCBx.Dispose();
                hv_BCBy.Dispose();
                hv_BCBz.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void eliminate_radial_distortions(
            HObject ho_Images,
            HObject ho_RectificationMaps,
            out HObject ho_ImagesRectified,
            out HObject ho_ImagesGrayRectified,
            HTuple hv_NumCameras,
            HTuple hv_Channels
        )
        {
            // Stack for temporary objects
            HObject[] OTemp = new HObject[20];

            // Local iconic variables

            HObject ho_Map = null,
                ho_ImagesGrayRectifiedOut = null;
            HObject ho_ImagesRectifiedOut = null,
                ho_Image = null,
                ho_ImageRectified = null;
            HObject ho_GrayImage = null;

            // Local control variables

            HTuple hv_Cam = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_ImagesRectified);
            HOperatorSet.GenEmptyObj(out ho_ImagesGrayRectified);
            HOperatorSet.GenEmptyObj(out ho_Map);
            HOperatorSet.GenEmptyObj(out ho_ImagesGrayRectifiedOut);
            HOperatorSet.GenEmptyObj(out ho_ImagesRectifiedOut);
            HOperatorSet.GenEmptyObj(out ho_Image);
            HOperatorSet.GenEmptyObj(out ho_ImageRectified);
            HOperatorSet.GenEmptyObj(out ho_GrayImage);
            try
            {
                ho_ImagesRectified.Dispose();
                HOperatorSet.GenEmptyObj(out ho_ImagesRectified);
                ho_ImagesGrayRectified.Dispose();
                HOperatorSet.GenEmptyObj(out ho_ImagesGrayRectified);
                //*使用多线程
                //par_start<ThreadID0> : eliminateSub (Images, RectificationMaps, Map, GrayImage1, ImageRectified1, 0, Channels)
                //par_start<ThreadID1> : eliminateSub (Images, RectificationMaps, Map, GrayImage2, ImageRectified2, 1, Channels)
                //par_start<ThreadID2> : eliminateSub (Images, RectificationMaps, Map, GrayImage3, ImageRectified3, 2, Channels)
                //par_start<ThreadID3> : eliminateSub (Images, RectificationMaps, Map, GrayImage4, ImageRectified4, 3, Channels)
                //ThreadIDs := [ThreadID0,ThreadID1,ThreadID2,ThreadID3]
                //par_join (ThreadIDs)

                //concat_obj (ImagesRectified, ImageRectified1, ImagesRectified)
                //concat_obj (ImagesRectified, ImageRectified2, ImagesRectified)
                //concat_obj (ImagesRectified, ImageRectified3, ImagesRectified)
                //concat_obj (ImagesRectified, ImageRectified4, ImagesRectified)
                //concat_obj (ImagesGrayRectified, GrayImage1, ImagesGrayRectified)
                //concat_obj (ImagesGrayRectified, GrayImage2, ImagesGrayRectified)
                //concat_obj (ImagesGrayRectified, GrayImage3, ImagesGrayRectified)
                //concat_obj (ImagesGrayRectified, GrayImage4, ImagesGrayRectified)

                //**不用多线程
                //gen_empty_obj (ImagesRectified)
                //gen_empty_obj (ImagesGrayRectified)
                ho_ImagesGrayRectifiedOut.Dispose();
                ho_ImagesGrayRectifiedOut = new HObject(ho_ImagesGrayRectified);
                ho_ImagesRectifiedOut.Dispose();
                ho_ImagesRectifiedOut = new HObject(ho_ImagesRectified);
                HTuple end_val24 = hv_NumCameras - 1;
                HTuple step_val24 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val24, step_val24);
                    hv_Cam = hv_Cam.TupleAdd(step_val24)
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_Image.Dispose();
                        HOperatorSet.SelectObj(ho_Images, out ho_Image, hv_Cam + 1);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_Map.Dispose();
                        HOperatorSet.SelectObj(ho_RectificationMaps, out ho_Map, hv_Cam + 1);
                    }
                    ho_ImageRectified.Dispose();
                    HOperatorSet.MapImage(ho_Image, ho_Map, out ho_ImageRectified);
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConcatObj(
                            ho_ImagesRectified,
                            ho_ImageRectified,
                            out ExpTmpOutVar_0
                        );
                        ho_ImagesRectified.Dispose();
                        ho_ImagesRectified = ExpTmpOutVar_0;
                    }
                    if ((int)(new HTuple(hv_Channels.TupleEqual(3))) != 0)
                    {
                        ho_GrayImage.Dispose();
                        HOperatorSet.Rgb1ToGray(ho_ImageRectified, out ho_GrayImage);
                        {
                            HObject ExpTmpOutVar_0;
                            HOperatorSet.ConcatObj(
                                ho_ImagesGrayRectified,
                                ho_GrayImage,
                                out ExpTmpOutVar_0
                            );
                            ho_ImagesGrayRectified.Dispose();
                            ho_ImagesGrayRectified = ExpTmpOutVar_0;
                        }
                    }
                    else
                    {
                        {
                            HObject ExpTmpOutVar_0;
                            HOperatorSet.ConcatObj(
                                ho_ImagesGrayRectified,
                                ho_ImageRectified,
                                out ExpTmpOutVar_0
                            );
                            ho_ImagesGrayRectified.Dispose();
                            ho_ImagesGrayRectified = ExpTmpOutVar_0;
                        }
                    }
                }

                ho_Map.Dispose();
                ho_ImagesGrayRectifiedOut.Dispose();
                ho_ImagesRectifiedOut.Dispose();
                ho_Image.Dispose();
                ho_ImageRectified.Dispose();
                ho_GrayImage.Dispose();

                hv_Cam.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_Map.Dispose();
                ho_ImagesGrayRectifiedOut.Dispose();
                ho_ImagesRectifiedOut.Dispose();
                ho_Image.Dispose();
                ho_ImageRectified.Dispose();
                ho_GrayImage.Dispose();

                hv_Cam.Dispose();

                throw HDevExpDefaultException;
            }
        }

