        public void eliminateSub(
            HObject ho_Images,
            HObject ho_RectificationMaps,
            out HObject ho_Map,
            out HObject ho_GrayImage,
            out HObject ho_ImageRectified,
            HTuple hv_Cam,
            HTuple hv_Channels
        )
        {
            // Local iconic variables

            HObject ho_Image;
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_Map);
            HOperatorSet.GenEmptyObj(out ho_GrayImage);
            HOperatorSet.GenEmptyObj(out ho_ImageRectified);
            HOperatorSet.GenEmptyObj(out ho_Image);
            try
            {
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_Image.Dispose();
                    HOperatorSet.SelectObj(ho_Images, out ho_Image, hv_Cam + 1);
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_Map.Dispose();
                    HOperatorSet.SelectObj(ho_RectificationMaps, out ho_Map, hv_Cam + 1);
                }
                ho_ImageRectified.Dispose();
                HOperatorSet.MapImage(ho_Image, ho_Map, out ho_ImageRectified);
                if ((int)(new HTuple(hv_Channels.TupleEqual(3))) != 0)
                {
                    ho_GrayImage.Dispose();
                    HOperatorSet.Rgb1ToGray(ho_ImageRectified, out ho_GrayImage);
                }
                else
                {
                    ho_GrayImage.Dispose();
                    ho_GrayImage = new HObject(ho_ImageRectified);
                }
                ho_Image.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_Image.Dispose();

                throw HDevExpDefaultException;
            }
        }

        // Chapter: Math / Fitting
        // Short Description: Fit a plane to the given 3D points
        public void fit_plane(
            HTuple hv_X,
            HTuple hv_Y,
            HTuple hv_Z,
            out HTuple hv_NX,
            out HTuple hv_NY,
            out HTuple hv_NZ,
            out HTuple hv_C
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_Num = new HTuple(),
                hv_XM = new HTuple();
            HTuple hv_YM = new HTuple(),
                hv_ZM = new HTuple(),
                hv_DX = new HTuple();
            HTuple hv_DY = new HTuple(),
                hv_DZ = new HTuple(),
                hv_MA11 = new HTuple();
            HTuple hv_MA22 = new HTuple(),
                hv_MA33 = new HTuple();
            HTuple hv_MA12 = new HTuple(),
                hv_MA13 = new HTuple();
            HTuple hv_MA23 = new HTuple(),
                hv_MatrixID = new HTuple();
            HTuple hv_EigenvaluesID = new HTuple(),
                hv_EigenvectorsID = new HTuple();
            // Initialize local and output iconic variables
            hv_NX = new HTuple();
            hv_NY = new HTuple();
            hv_NZ = new HTuple();
            hv_C = new HTuple();
            try
            {
                //number of points
                hv_Num.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Num = new HTuple(hv_X.TupleLength());
                }

                //center of gravity of all points
                hv_XM.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_XM = hv_X.TupleMean();
                }
                hv_YM.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_YM = hv_Y.TupleMean();
                }
                hv_ZM.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ZM = hv_Z.TupleMean();
                }

                //symmetric matrix M(A)
                hv_DX.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DX = hv_X - hv_XM;
                }
                hv_DY.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DY = hv_Y - hv_YM;
                }
                hv_DZ.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DZ = hv_Z - hv_ZM;
                }
                hv_MA11.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MA11 = ((hv_DX * hv_DX)).TupleSum();
                }
                hv_MA22.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MA22 = ((hv_DY * hv_DY)).TupleSum();
                }
                hv_MA33.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MA33 = ((hv_DZ * hv_DZ)).TupleSum();
                }
                hv_MA12.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MA12 = ((hv_DX * hv_DY)).TupleSum();
                }
                hv_MA13.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MA13 = ((hv_DX * hv_DZ)).TupleSum();
                }
                hv_MA23.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MA23 = ((hv_DY * hv_DZ)).TupleSum();
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MatrixID.Dispose();
                    HOperatorSet.CreateMatrix(
                        3,
                        3,
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (
                                                    (
                                                        (
                                                            (
                                                                (
                                                                    (
                                                                        (
                                                                            (
                                                                                hv_MA11.TupleConcat(
                                                                                    hv_MA12
                                                                                )
                                                                            )
                                                                        ).TupleConcat(hv_MA13)
                                                                    )
                                                                ).TupleConcat(hv_MA12)
                                                            )
                                                        ).TupleConcat(hv_MA22)
                                                    )
                                                ).TupleConcat(hv_MA23)
                                            )
                                        ).TupleConcat(hv_MA13)
                                    )
                                ).TupleConcat(hv_MA23)
                            )
                        ).TupleConcat(hv_MA33),
                        out hv_MatrixID
                    );
                }

                //the normal vector is the eigenvector that belongs to the smallest
                //eigenvalue auf the matrix MatrixID
                hv_EigenvaluesID.Dispose();
                hv_EigenvectorsID.Dispose();
                HOperatorSet.EigenvaluesSymmetricMatrix(
                    hv_MatrixID,
                    "true",
                    out hv_EigenvaluesID,
                    out hv_EigenvectorsID
                );
                hv_NX.Dispose();
                HOperatorSet.GetValueMatrix(hv_EigenvectorsID, 0, 0, out hv_NX);
                hv_NY.Dispose();
                HOperatorSet.GetValueMatrix(hv_EigenvectorsID, 1, 0, out hv_NY);
                hv_NZ.Dispose();
                HOperatorSet.GetValueMatrix(hv_EigenvectorsID, 2, 0, out hv_NZ);

                //the constant of the normal-constant form of the plane (n*P = c)
                hv_C.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_C = ((hv_NX * hv_XM) + (hv_NY * hv_YM)) + (hv_NZ * hv_ZM);
                }
                if ((int)(new HTuple(hv_C.TupleLess(0.0))) != 0)
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_NX = -hv_NX;
                            hv_NX.Dispose();
                            hv_NX = ExpTmpLocalVar_NX;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_NY = -hv_NY;
                            hv_NY.Dispose();
                            hv_NY = ExpTmpLocalVar_NY;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_NZ = -hv_NZ;
                            hv_NZ.Dispose();
                            hv_NZ = ExpTmpLocalVar_NZ;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_C = -hv_C;
                            hv_C.Dispose();
                            hv_C = ExpTmpLocalVar_C;
                        }
                    }
                }

                hv_Num.Dispose();
                hv_XM.Dispose();
                hv_YM.Dispose();
                hv_ZM.Dispose();
                hv_DX.Dispose();
                hv_DY.Dispose();
                hv_DZ.Dispose();
                hv_MA11.Dispose();
                hv_MA22.Dispose();
                hv_MA33.Dispose();
                hv_MA12.Dispose();
                hv_MA13.Dispose();
                hv_MA23.Dispose();
                hv_MatrixID.Dispose();
                hv_EigenvaluesID.Dispose();
                hv_EigenvectorsID.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                hv_Num.Dispose();
                hv_XM.Dispose();
                hv_YM.Dispose();
                hv_ZM.Dispose();
                hv_DX.Dispose();
                hv_DY.Dispose();
                hv_DZ.Dispose();
                hv_MA11.Dispose();
                hv_MA22.Dispose();
                hv_MA33.Dispose();
                hv_MA12.Dispose();
                hv_MA13.Dispose();
                hv_MA23.Dispose();
                hv_MatrixID.Dispose();
                hv_EigenvaluesID.Dispose();
                hv_EigenvectorsID.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void gen_cylinder_model(
            HTuple hv_PixelSize,
            HTuple hv_CylinderRadius,
            HTuple hv_MinZ,
            HTuple hv_MaxZ,
            out HTuple hv_NumSlices,
            out HTuple hv_NumPointsPerSlice,
            out HTuple hv_MinZI,
            out HTuple hv_MaxZI,
            out HTuple hv_PxSampled,
            out HTuple hv_PySampled,
            out HTuple hv_PzSampled
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_Circumference = new HTuple(),
                hv_ActualPixelSize = new HTuple();
            HTuple hv_AngleStep = new HTuple(),
                hv_FullAngle = new HTuple();
            HTuple hv_Angles = new HTuple(),
                hv_NumNM = new HTuple();
            HTuple hv_TupleOnes = new HTuple(),
                hv_I = new HTuple();
            HTuple hv_Indices = new HTuple();
            // Initialize local and output iconic variables
            hv_NumSlices = new HTuple();
            hv_NumPointsPerSlice = new HTuple();
            hv_MinZI = new HTuple();
            hv_MaxZI = new HTuple();
            hv_PxSampled = new HTuple();
            hv_PySampled = new HTuple();
            hv_PzSampled = new HTuple();
            try
            {
                //global tuple DisplayIntermediateResults

                //Determine the number of points per slice
                hv_Circumference.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Circumference = (2.0 * hv_CylinderRadius) * 3.1415926;
                }
                hv_NumPointsPerSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_NumPointsPerSlice = (((hv_Circumference / hv_PixelSize)).TupleInt()) + 1;
                }
                hv_ActualPixelSize.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ActualPixelSize = hv_Circumference / hv_NumPointsPerSlice;
                }
                hv_AngleStep.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_AngleStep = hv_ActualPixelSize / hv_CylinderRadius;
                }
                hv_FullAngle.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_FullAngle = hv_AngleStep * (hv_NumPointsPerSlice - 1);
                }
                hv_Angles.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Angles =
                        ((-0.5 * hv_FullAngle) - hv_AngleStep)
                        + ((HTuple.TupleGenConst(hv_NumPointsPerSlice, hv_AngleStep)).TupleCumul());
                }

                //Determine the number of slices
                hv_MinZI.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MinZI =
                        (((((hv_MinZ.TupleFabs()) / hv_ActualPixelSize)).TupleInt()) + 1)
                        * (hv_MinZ.TupleSgn());
                }
                hv_MaxZI.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MaxZI =
                        (((((hv_MaxZ.TupleFabs()) / hv_ActualPixelSize)).TupleInt()) + 1)
                        * (hv_MaxZ.TupleSgn());
                }
                hv_NumSlices.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_NumSlices = ((hv_MinZI.TupleAbs()) + (hv_MaxZI.TupleAbs())) + 1;
                }

                hv_NumNM.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_NumNM = hv_NumSlices * hv_NumPointsPerSlice;
                }
                hv_PxSampled.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_PxSampled = HTuple.TupleGenConst(hv_NumNM, 0);
                }
                hv_PySampled.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_PySampled = HTuple.TupleGenConst(hv_NumNM, 0);
                }
                hv_PzSampled.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_PzSampled = HTuple.TupleGenConst(hv_NumNM, 0);
                }
                hv_TupleOnes.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_TupleOnes = HTuple.TupleGenConst(new HTuple(hv_Angles.TupleLength()), 1);
                }
                HTuple end_val20 = hv_NumSlices - 1;
                HTuple step_val20 = 1;
                for (
                    hv_I = 0;
                    hv_I.Continue(end_val20, step_val20);
                    hv_I = hv_I.TupleAdd(step_val20)
                )
                {
                    hv_Indices.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Indices = HTuple.TupleGenSequence(
                            hv_I * hv_NumPointsPerSlice,
                            ((hv_I + 1) * hv_NumPointsPerSlice) - 1,
                            1
                        );
                    }
                    if (hv_PxSampled == null)
                        hv_PxSampled = new HTuple();
                    hv_PxSampled[hv_Indices] = (hv_Angles.TupleCos()) * hv_CylinderRadius;
                    if (hv_PySampled == null)
                        hv_PySampled = new HTuple();
                    hv_PySampled[hv_Indices] = (hv_Angles.TupleSin()) * hv_CylinderRadius;
                    if (hv_PzSampled == null)
                        hv_PzSampled = new HTuple();
                    hv_PzSampled[hv_Indices] =
                        ((hv_MaxZI - hv_I) * hv_ActualPixelSize) * hv_TupleOnes;
                }

                hv_Circumference.Dispose();
                hv_ActualPixelSize.Dispose();
                hv_AngleStep.Dispose();
                hv_FullAngle.Dispose();
                hv_Angles.Dispose();
                hv_NumNM.Dispose();
                hv_TupleOnes.Dispose();
                hv_I.Dispose();
                hv_Indices.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                hv_Circumference.Dispose();
                hv_ActualPixelSize.Dispose();
                hv_AngleStep.Dispose();
                hv_FullAngle.Dispose();
                hv_Angles.Dispose();
                hv_NumNM.Dispose();
                hv_TupleOnes.Dispose();
                hv_I.Dispose();
                hv_Indices.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void GetData(
            HObject ho_ImagesRectified,
            HObject ho_ImagesGrayRectified,
            out HObject ho_ImageRectified,
            out HObject ho_GrayImage,
            out HObject ho_Cross,
            HTuple hv_Cam,
            HTuple hv_CameraSetupModelZeroDistCylApprox,
            HTuple hv_MinPairDist,
            HTuple hv_MaxPairDist,
            HTuple hv_SilhouetteMaxTilt,
            HTuple hv_MeasureHandles,
            HTuple hv_SilhouetteMeasureSigma,
            HTuple hv_SilhouetteMeasureThreshold,
            HTuple hv_BackgroundMayContainTexture,
            HTuple hv_SilhRow,
            HTuple hv_SilhCol,
            HTuple hv_SilhCam,
            HTuple hv_A2x,
            HTuple hv_A2y,
            HTuple hv_A2z,
            HTuple hv_B2x,
            HTuple hv_B2y,
            HTuple hv_B2z,
            out HTuple hv_CamParam,
            out HTuple hv_CamPose,
            out HTuple hv_Row,
            out HTuple hv_Column,
            out HTuple hv_FuzzyFunction,
            out HTuple hv_I,
            out HTuple hv_RowEdgeFirst,
            out HTuple hv_ColumnEdgeFirst,
            out HTuple hv_AmplitudeFirst,
            out HTuple hv_RowEdgeSecond,
            out HTuple hv_ColumnEdgeSecond,
            out HTuple hv_AmplitudeSecond,
            out HTuple hv_RowPairCenter,
            out HTuple hv_ColumnPairCenter,
            out HTuple hv_FuzzyScore,
            out HTuple hv_IntraDistance,
            out HTuple hv_SIF,
            out HTuple hv_SIS,
            out HTuple hv_WindowHandle,
            out HTuple hv_Border,
            out HTuple hv_ImgWidth,
            out HTuple hv_ImgHeight,
            out HTuple hv_Message,
            out HTuple hv_MessageWrapped,
            out HTuple hv_SilhRowOut,
            out HTuple hv_SilhColOut,
            out HTuple hv_SilhCamOut,
            out HTuple hv_PX,
            out HTuple hv_PY,
            out HTuple hv_PZ,
            out HTuple hv_QX,
            out HTuple hv_QY,
            out HTuple hv_QZ,
            out HTuple hv_HomMat3D,
            out HTuple hv_PX0,
            out HTuple hv_PY0,
            out HTuple hv_PZ0,
            out HTuple hv_QX0,
            out HTuple hv_QY0,
            out HTuple hv_QZ0,
            out HTuple hv_A2xOut,
            out HTuple hv_A2yOut,
            out HTuple hv_A2zOut,
            out HTuple hv_B2xOut,
            out HTuple hv_B2yOut,
            out HTuple hv_B2zOut
        )
        {
            // Local iconic variables
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_ImageRectified);
            HOperatorSet.GenEmptyObj(out ho_GrayImage);
            HOperatorSet.GenEmptyObj(out ho_Cross);
            hv_CamParam = new HTuple();
            hv_CamPose = new HTuple();
            hv_Row = new HTuple();
            hv_Column = new HTuple();
            hv_FuzzyFunction = new HTuple();
            hv_I = new HTuple();
            hv_RowEdgeFirst = new HTuple();
            hv_ColumnEdgeFirst = new HTuple();
            hv_AmplitudeFirst = new HTuple();
            hv_RowEdgeSecond = new HTuple();
            hv_ColumnEdgeSecond = new HTuple();
            hv_AmplitudeSecond = new HTuple();
            hv_RowPairCenter = new HTuple();
            hv_ColumnPairCenter = new HTuple();
            hv_FuzzyScore = new HTuple();
            hv_IntraDistance = new HTuple();
            hv_SIF = new HTuple();
            hv_SIS = new HTuple();
            hv_WindowHandle = new HTuple();
            hv_Border = new HTuple();
            hv_ImgWidth = new HTuple();
            hv_ImgHeight = new HTuple();
            hv_Message = new HTuple();
            hv_MessageWrapped = new HTuple();
            hv_SilhRowOut = new HTuple();
            hv_SilhColOut = new HTuple();
            hv_SilhCamOut = new HTuple();
            hv_PX = new HTuple();
            hv_PY = new HTuple();
            hv_PZ = new HTuple();
            hv_QX = new HTuple();
            hv_QY = new HTuple();
            hv_QZ = new HTuple();
            hv_HomMat3D = new HTuple();
            hv_PX0 = new HTuple();
            hv_PY0 = new HTuple();
            hv_PZ0 = new HTuple();
            hv_QX0 = new HTuple();
            hv_QY0 = new HTuple();
            hv_QZ0 = new HTuple();
            hv_A2xOut = new HTuple();
            hv_A2yOut = new HTuple();
            hv_A2zOut = new HTuple();
            hv_B2xOut = new HTuple();
            hv_B2yOut = new HTuple();
            hv_B2zOut = new HTuple();
            //global tuple DisplayIntermediateResults
            //global tuple WindowWidthLimit
            //global tuple WindowHeightLimit
            hv_A2xOut.Dispose();
            hv_A2xOut = new HTuple(hv_A2x);
            hv_A2yOut.Dispose();
            hv_A2yOut = new HTuple(hv_A2y);
            hv_A2zOut.Dispose();
            hv_A2zOut = new HTuple(hv_A2z);
            hv_B2xOut.Dispose();
            hv_B2xOut = new HTuple(hv_B2x);
            hv_B2yOut.Dispose();
            hv_B2yOut = new HTuple(hv_B2y);
            hv_B2zOut.Dispose();
            hv_B2zOut = new HTuple(hv_B2z);
            hv_SilhCamOut.Dispose();
            hv_SilhCamOut = new HTuple(hv_SilhCam);
            hv_SilhColOut.Dispose();
            hv_SilhColOut = new HTuple(hv_SilhCol);
            hv_SilhRowOut.Dispose();
            hv_SilhRowOut = new HTuple(hv_SilhRow);
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                ho_ImageRectified.Dispose();
                HOperatorSet.SelectObj(ho_ImagesRectified, out ho_ImageRectified, hv_Cam + 1);
            }
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                ho_GrayImage.Dispose();
                HOperatorSet.SelectObj(ho_ImagesGrayRectified, out ho_GrayImage, hv_Cam + 1);
            }
            hv_CamParam.Dispose();
            HOperatorSet.GetCameraSetupParam(
                hv_CameraSetupModelZeroDistCylApprox,
                hv_Cam,
                "params",
                out hv_CamParam
            );
            hv_CamPose.Dispose();
            HOperatorSet.GetCameraSetupParam(
                hv_CameraSetupModelZeroDistCylApprox,
                hv_Cam,
                "pose",
                out hv_CamPose
            );

            hv_Row.Dispose();
            hv_Row = new HTuple();
            hv_Column.Dispose();
            hv_Column = new HTuple();
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                hv_FuzzyFunction.Dispose();
                HOperatorSet.CreateFunct1dPairs(
                    (
                        (
                            (
                                (
                                    (((hv_MinPairDist.TupleSelect(hv_Cam)) - 10)).TupleConcat(
                                        hv_MinPairDist.TupleSelect(hv_Cam)
                                    )
                                )
                            ).TupleConcat(
                                (hv_MaxPairDist.TupleSelect(hv_Cam))
                                    / (hv_SilhouetteMaxTilt.TupleCos())
                            )
                        )
                    ).TupleConcat(
                        ((hv_MaxPairDist.TupleSelect(hv_Cam)) / (hv_SilhouetteMaxTilt.TupleCos()))
                            + 10
                    ),
                    (((new HTuple(0)).TupleConcat(1)).TupleConcat(1)).TupleConcat(0),
                    out hv_FuzzyFunction
                );
            }
            for (
                hv_I = 0;
                (int)hv_I <= (int)((new HTuple(hv_MeasureHandles.TupleLength())) - 1);
                hv_I = (int)hv_I + 1
            )
            {
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    HOperatorSet.SetFuzzyMeasure(
                        hv_MeasureHandles.TupleSelect(hv_I),
                        "size",
                        hv_FuzzyFunction
                    );
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_RowEdgeFirst.Dispose();
                    hv_ColumnEdgeFirst.Dispose();
                    hv_AmplitudeFirst.Dispose();
                    hv_RowEdgeSecond.Dispose();
                    hv_ColumnEdgeSecond.Dispose();
                    hv_AmplitudeSecond.Dispose();
                    hv_RowPairCenter.Dispose();
                    hv_ColumnPairCenter.Dispose();
                    hv_FuzzyScore.Dispose();
                    hv_IntraDistance.Dispose();
                    HOperatorSet.FuzzyMeasurePairing(
                        ho_GrayImage,
                        hv_MeasureHandles.TupleSelect(hv_I),
                        hv_SilhouetteMeasureSigma,
                        hv_SilhouetteMeasureThreshold,
                        0.5,
                        "all",
                        "no_restriction",
                        0,
                        out hv_RowEdgeFirst,
                        out hv_ColumnEdgeFirst,
                        out hv_AmplitudeFirst,
                        out hv_RowEdgeSecond,
                        out hv_ColumnEdgeSecond,
                        out hv_AmplitudeSecond,
                        out hv_RowPairCenter,
                        out hv_ColumnPairCenter,
                        out hv_FuzzyScore,
                        out hv_IntraDistance
                    );
                }
                if ((int)(hv_BackgroundMayContainTexture) != 0)
                {
                    //Use all extracted edges
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Row = (
                                (hv_Row.TupleConcat(hv_RowEdgeFirst))
                            ).TupleConcat(hv_RowEdgeSecond);
                            hv_Row.Dispose();
                            hv_Row = ExpTmpLocalVar_Row;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_Column = (
                                (hv_Column.TupleConcat(hv_ColumnEdgeFirst))
                            ).TupleConcat(hv_ColumnEdgeSecond);
                            hv_Column.Dispose();
                            hv_Column = ExpTmpLocalVar_Column;
                        }
                    }
                }
                else
                {
                    //Select only first and last edge if the background can be assumed
                    //to be textureless
                    if (
                        (int)(
                            new HTuple((new HTuple(hv_RowEdgeFirst.TupleLength())).TupleGreater(0))
                        ) != 0
                    )
                    {
                        hv_SIF.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_SIF = (
                                new HTuple(((-hv_RowEdgeFirst)).TupleSortIndex())
                            ).TupleSelect(0);
                        }
                        hv_SIS.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_SIS = (new HTuple(hv_RowEdgeSecond.TupleSortIndex())).TupleSelect(0);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            {
                                HTuple ExpTmpLocalVar_Row = (
                                    (hv_Row.TupleConcat(hv_RowEdgeFirst.TupleSelect(hv_SIF)))
                                ).TupleConcat(hv_RowEdgeSecond.TupleSelect(hv_SIS));
                                hv_Row.Dispose();
                                hv_Row = ExpTmpLocalVar_Row;
                            }
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            {
                                HTuple ExpTmpLocalVar_Column = (
                                    (hv_Column.TupleConcat(hv_ColumnEdgeFirst.TupleSelect(hv_SIF)))
                                ).TupleConcat(hv_ColumnEdgeSecond.TupleSelect(hv_SIS));
                                hv_Column.Dispose();
                                hv_Column = ExpTmpLocalVar_Column;
                            }
                        }
                    }
                }
            }
            //if (DisplayIntermediateResults)
            if (HDevWindowStack.IsOpen())
            {
                //dev_get_window (WindowHandle)
            }
            //Border := 300
            //get_image_size (GrayImage, ImgWidth, ImgHeight)
            //dev_resize_window_fit_size (0, 0, ImgWidth, ImgHeight + Border, WindowWidthLimit, WindowHeightLimit)
            if (HDevWindowStack.IsOpen())
            {
                //dev_set_part (-Border, 0, ImgHeight, ImgWidth)
            }
            //gen_cross_contour_xld (Cross, Row, Column, 6, 0.785398)
            if (HDevWindowStack.IsOpen())
            {
                //dev_clear_window ()
            }
            if (HDevWindowStack.IsOpen())
            {
                //dev_display (GrayImage)
            }
            if (HDevWindowStack.IsOpen())
            {
                //dev_display (Cross)
            }
            //Message := 'Points used for the estimation of the bottle\'s pose. Note that enough points must lie on the silhouette of the bottle.'
            //MessageWrapped := regexp_replace(Message + ' ',['(.{0,45})\\s','replace_all'],'$1\n')
            //disp_message (WindowHandle, ['Camera ' + (Cam + 1) + ':',MessageWrapped], 'window', 12, 12, 'black', 'true')
            //stop ()
            //endif

            //Only for visualization of selected points
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_SilhRowOut = hv_SilhRowOut.TupleConcat(hv_Row);
                    hv_SilhRowOut.Dispose();
                    hv_SilhRowOut = ExpTmpLocalVar_SilhRowOut;
                }
            }
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_SilhColOut = hv_SilhColOut.TupleConcat(hv_Column);
                    hv_SilhColOut.Dispose();
                    hv_SilhColOut = ExpTmpLocalVar_SilhColOut;
                }
            }

            //For visualization and check of the distribution of the remaining points
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_SilhCamOut = hv_SilhCamOut.TupleConcat(
                        HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_Cam)
                    );
                    hv_SilhCamOut.Dispose();
                    hv_SilhCamOut = ExpTmpLocalVar_SilhCamOut;
                }
            }

            hv_PX.Dispose();
            hv_PY.Dispose();
            hv_PZ.Dispose();
            hv_QX.Dispose();
            hv_QY.Dispose();
            hv_QZ.Dispose();
            HOperatorSet.GetLineOfSight(
                hv_Row,
                hv_Column,
                hv_CamParam,
                out hv_PX,
                out hv_PY,
                out hv_PZ,
                out hv_QX,
                out hv_QY,
                out hv_QZ
            );
            hv_HomMat3D.Dispose();
            HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
            hv_PX0.Dispose();
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                hv_PX0 = hv_HomMat3D.TupleSelect(3);
            }
            hv_PY0.Dispose();
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                hv_PY0 = hv_HomMat3D.TupleSelect(7);
            }
            hv_PZ0.Dispose();
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                hv_PZ0 = hv_HomMat3D.TupleSelect(11);
            }
            hv_QX0.Dispose();
            hv_QY0.Dispose();
            hv_QZ0.Dispose();
            HOperatorSet.AffineTransPoint3d(
                hv_HomMat3D,
                hv_QX,
                hv_QY,
                hv_QZ,
                out hv_QX0,
                out hv_QY0,
                out hv_QZ0
            );
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_A2xOut = hv_A2xOut.TupleConcat(
                        HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PX0)
                    );
                    hv_A2xOut.Dispose();
                    hv_A2xOut = ExpTmpLocalVar_A2xOut;
                }
            }
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_A2yOut = hv_A2yOut.TupleConcat(
                        HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PY0)
                    );
                    hv_A2yOut.Dispose();
                    hv_A2yOut = ExpTmpLocalVar_A2yOut;
                }
            }
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_A2zOut = hv_A2zOut.TupleConcat(
                        HTuple.TupleGenConst(new HTuple(hv_Row.TupleLength()), hv_PZ0)
                    );
                    hv_A2zOut.Dispose();
                    hv_A2zOut = ExpTmpLocalVar_A2zOut;
                }
            }
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_B2xOut = hv_B2xOut.TupleConcat(hv_QX0 - hv_PX0);
                    hv_B2xOut.Dispose();
                    hv_B2xOut = ExpTmpLocalVar_B2xOut;
                }
            }
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_B2yOut = hv_B2yOut.TupleConcat(hv_QY0 - hv_PY0);
                    hv_B2yOut.Dispose();
                    hv_B2yOut = ExpTmpLocalVar_B2yOut;
                }
            }
            using (HDevDisposeHelper dh = new HDevDisposeHelper())
            {
                {
                    HTuple ExpTmpLocalVar_B2zOut = hv_B2zOut.TupleConcat(hv_QZ0 - hv_PZ0);
                    hv_B2zOut.Dispose();
                    hv_B2zOut = ExpTmpLocalVar_B2zOut;
                }
            }

            return;
        }

        public void GetMark(
            HObject ho_Regions,
            HObject ho_ImagesRectified,
            HObject ho_ImageMosaicR,
            HObject ho_ImageMosaicG,
            HObject ho_ImageMosaicB,
            HObject ho_ImageMosaic,
            HObject ho_ImagesGrayRectified,
            out HObject ho_Region,
            out HObject ho_ObjectSelected,
            out HObject ho_ImageR,
            out HObject ho_ImageG,
            out HObject ho_ImageB,
            out HObject ho_ImageGray,
            HTuple hv_CameraSetupModelZeroDistInCylinderOrigin,
            HTuple hv_Cam,
            HTuple hv_NumPointsPerSlice,
            HTuple hv_CylinderPointsX,
            HTuple hv_CylinderPointsY,
            HTuple hv_CylinderPointsZ,
            HTuple hv_ColorMosaic,
            HTuple hv_HighImageQuality,
            out HTuple hv_Grayval1,
            out HTuple hv_selectmarkR,
            out HTuple hv_selectmarkC
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_CamParam = new HTuple(),
                hv_ImageWidth = new HTuple();
            HTuple hv_ImageHeight = new HTuple(),
                hv_CamPose = new HTuple();
            HTuple hv_HomMat3D = new HTuple(),
                hv_HomMat3DInvert = new HTuple();
            HTuple hv_Rows = new HTuple(),
                hv_Columns = new HTuple();
            HTuple hv_LinCoord = new HTuple(),
                hv_Qx = new HTuple();
            HTuple hv_Qy = new HTuple(),
                hv_Qz = new HTuple(),
                hv_ImageRow = new HTuple();
            HTuple hv_ImageColumn = new HTuple(),
                hv_Mask = new HTuple();
            HTuple hv_ImageRowSub = new HTuple(),
                hv_ImageColumnSub = new HTuple();
            HTuple hv_BicubicInterpolation = new HTuple(),
                hv_Grayval = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_Region);
            HOperatorSet.GenEmptyObj(out ho_ObjectSelected);
            HOperatorSet.GenEmptyObj(out ho_ImageR);
            HOperatorSet.GenEmptyObj(out ho_ImageG);
            HOperatorSet.GenEmptyObj(out ho_ImageB);
            HOperatorSet.GenEmptyObj(out ho_ImageGray);
            hv_Grayval1 = new HTuple();
            hv_selectmarkR = new HTuple();
            hv_selectmarkC = new HTuple();
            try
            {
                hv_CamParam.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    hv_Cam,
                    "params",
                    out hv_CamParam
                );
                hv_ImageWidth.Dispose();
                get_cam_par_data(hv_CamParam, "image_width", out hv_ImageWidth);
                hv_ImageHeight.Dispose();
                get_cam_par_data(hv_CamParam, "image_height", out hv_ImageHeight);
                hv_CamPose.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    hv_Cam,
                    "pose",
                    out hv_CamPose
                );
                hv_HomMat3D.Dispose();
                HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                hv_HomMat3DInvert.Dispose();
                HOperatorSet.HomMat3dInvert(hv_HomMat3D, out hv_HomMat3DInvert);
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_Region.Dispose();
                    HOperatorSet.SelectObj(ho_Regions, out ho_Region, hv_Cam + 1);
                }
                hv_Rows.Dispose();
                hv_Columns.Dispose();
                HOperatorSet.GetRegionPoints(ho_Region, out hv_Rows, out hv_Columns);
                hv_LinCoord.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_LinCoord = (hv_Rows * hv_NumPointsPerSlice) + hv_Columns;
                }
                //
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Qx.Dispose();
