            HTuple hv_CameraType = new HTuple(),
                hv_IsPolynomial = new HTuple();
            HTuple hv_CamParOut = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_RectificationMaps);
            HOperatorSet.GenEmptyObj(out ho_Map);
            hv_CameraSetupModelZeroDist = new HTuple();
            hv_NumCameras = new HTuple();
            try
            {
                hv_SerializedItemHandle.Dispose();
                HOperatorSet.SerializeCameraSetupModel(
                    hv_CameraSetupModel,
                    out hv_SerializedItemHandle
                );
                hv_CameraSetupModelZeroDist.Dispose();
                HOperatorSet.DeserializeCameraSetupModel(
                    hv_SerializedItemHandle,
                    out hv_CameraSetupModelZeroDist
                );
                //Create maps to remove the radial distortions from the images efficently
                hv_NumCameras.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDist,
                    "general",
                    "num_cameras",
                    out hv_NumCameras
                );
                ho_RectificationMaps.Dispose();
                HOperatorSet.GenEmptyObj(out ho_RectificationMaps);
                HTuple end_val5 = hv_NumCameras - 1;
                HTuple step_val5 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val5, step_val5);
                    hv_Cam = hv_Cam.TupleAdd(step_val5)
                )
                {
                    hv_CamParIn.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDist,
                        hv_Cam,
                        "params",
                        out hv_CamParIn
                    );
                    //Calculate camera parameters for the distortion-free images
                    hv_CameraType.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDist,
                        hv_Cam,
                        "type",
                        out hv_CameraType
                    );
                    hv_IsPolynomial.Dispose();
                    HOperatorSet.TupleRegexpTest(
                        hv_CameraType,
                        "_polynomial$",
                        out hv_IsPolynomial
                    );
                    if ((int)(hv_IsPolynomial) != 0)
                    {
                        hv_CamParOut.Dispose();
                        HOperatorSet.ChangeRadialDistortionCamPar(
                            "fixed",
                            hv_CamParIn,
                            (
                                (((new HTuple(0.0)).TupleConcat(0.0)).TupleConcat(0.0)).TupleConcat(
                                    0.0
                                )
                            ).TupleConcat(0.0),
                            out hv_CamParOut
                        );
                    }
                    else
                    {
                        hv_CamParOut.Dispose();
                        HOperatorSet.ChangeRadialDistortionCamPar(
                            "fixed",
                            hv_CamParIn,
                            0.0,
                            out hv_CamParOut
                        );
                    }
                    //Set these new parameter in the setup
                    HOperatorSet.SetCameraSetupParam(
                        hv_CameraSetupModelZeroDist,
                        hv_Cam,
                        "params",
                        hv_CamParOut
                    );
                    //Prepare the rectification maps
                    ho_Map.Dispose();
                    HOperatorSet.GenRadialDistortionMap(
                        out ho_Map,
                        hv_CamParIn,
                        hv_CamParOut,
                        "bilinear"
                    );
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConcatObj(ho_RectificationMaps, ho_Map, out ExpTmpOutVar_0);
                        ho_RectificationMaps.Dispose();
                        ho_RectificationMaps = ExpTmpOutVar_0;
                    }
                }
                ho_Map.Dispose();

                hv_SerializedItemHandle.Dispose();
                hv_Cam.Dispose();
                hv_CamParIn.Dispose();
                hv_CameraType.Dispose();
                hv_IsPolynomial.Dispose();
                hv_CamParOut.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_Map.Dispose();

                hv_SerializedItemHandle.Dispose();
                hv_Cam.Dispose();
                hv_CamParIn.Dispose();
                hv_CameraType.Dispose();
                hv_IsPolynomial.Dispose();
                hv_CamParOut.Dispose();

                throw HDevExpDefaultException;
            }
        }

        // Chapter: Math / Geometry
        // Short Description: Calculate the foot point of the perpendicular from one skew line to another skew line.
        public void skew_lines_perpendicular_foot(
            HTuple hv_L1a,
            HTuple hv_L1b,
            HTuple hv_L2a,
            HTuple hv_L2b,
            HTuple hv_FootOnLine,
            out HTuple hv_P
        )
        {
            // Local iconic variables

            // Local control variables

            HTuple hv_a1 = new HTuple(),
                hv_b1 = new HTuple();
            HTuple hv_a2 = new HTuple(),
                hv_b2 = new HTuple(),
                hv_da = new HTuple();
            HTuple hv_b1cb2 = new HTuple(),
                hv_b1cb2cb2 = new HTuple();
            HTuple hv_nom = new HTuple(),
                hv_den = new HTuple(),
                hv_t = new HTuple();
            // Initialize local and output iconic variables
            hv_P = new HTuple();
            try
            {
                switch (hv_FootOnLine.I)
                {
                    case 1:
                        hv_a1.Dispose();
                        hv_a1 = new HTuple(hv_L1a);
                        hv_b1.Dispose();
                        hv_b1 = new HTuple(hv_L1b);
                        hv_a2.Dispose();
                        hv_a2 = new HTuple(hv_L2a);
                        hv_b2.Dispose();
                        hv_b2 = new HTuple(hv_L2b);
                        break;
                    case 2:
                        hv_a1.Dispose();
                        hv_a1 = new HTuple(hv_L2a);
                        hv_b1.Dispose();
                        hv_b1 = new HTuple(hv_L2b);
                        hv_a2.Dispose();
                        hv_a2 = new HTuple(hv_L1a);
                        hv_b2.Dispose();
                        hv_b2 = new HTuple(hv_L1b);
                        break;
                    default:
                        throw new HalconException("Wrong value of FootOnLine: " + hv_FootOnLine);
                        break;
                }

                hv_da.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_da = hv_a1 - hv_a2;
                }
                hv_b1cb2.Dispose();
                cross_product(hv_b1, hv_b2, out hv_b1cb2);
                hv_b1cb2cb2.Dispose();
                cross_product(hv_b1cb2, hv_b2, out hv_b1cb2cb2);
                hv_nom.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_nom = ((hv_da * hv_b1cb2cb2)).TupleSum();
                }
                hv_den.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_den = ((hv_b1 * hv_b1cb2cb2)).TupleSum();
                }
                if ((int)(new HTuple(((hv_den.TupleFabs())).TupleLess(1e-20))) != 0)
                {
                    //Lines are parallel
                    hv_P.Dispose();
                    hv_P = new HTuple(hv_a1);
                }
                else
                {
                    //Foot point exists
                    hv_t.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_t = (-hv_nom) / hv_den;
                    }
                    hv_P.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_P = hv_a1 + (hv_t * hv_b1);
                    }
                }

                hv_a1.Dispose();
                hv_b1.Dispose();
                hv_a2.Dispose();
                hv_b2.Dispose();
                hv_da.Dispose();
                hv_b1cb2.Dispose();
                hv_b1cb2cb2.Dispose();
                hv_nom.Dispose();
                hv_den.Dispose();
                hv_t.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                hv_a1.Dispose();
                hv_b1.Dispose();
                hv_a2.Dispose();
                hv_b2.Dispose();
                hv_da.Dispose();
                hv_b1cb2.Dispose();
                hv_b1cb2cb2.Dispose();
                hv_nom.Dispose();
                hv_den.Dispose();
                hv_t.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void sti_imagesub(
            HObject ho_RegionsDilation,
            HObject ho_ImagesRectified,
            HObject ho_UnrolledImages,
            HObject ho_ImagesGrayRectified,
            out HObject ho_UnrolledImagesOut,
            out HObject ho_UnrolledOut,
            out HObject ho_RegionMaskOut,
            out HObject ho_DomainUnrolledOut,
            HTuple hv_ColorMosaic,
            HTuple hv_MosaicWidth,
            HTuple hv_MosaicHeight,
            HTuple hv_CameraSetupModelZeroDistInCylinderOrigin,
            HTuple hv_Cam,
            HTuple hv_NumPointsPerSlice,
            HTuple hv_CylinderPointsX,
            HTuple hv_CylinderPointsY,
            HTuple hv_CylinderPointsZ,
            HTuple hv_HighImageQuality
        )
        {
            // Stack for temporary objects
            HObject[] OTemp = new HObject[20];

            // Local iconic variables

            HObject ho_ImageUnrolledR = null,
                ho_ImageUnrolledG = null;
            HObject ho_ImageUnrolledB = null,
                ho_ImageUnrolled = null,
                ho_Region;
            HObject ho_RegionTrans = null,
                ho_ConnectedRegions = null,
                ho_Image = null;
            HObject ho_ImagePart = null,
                ho_ImageReduced = null,
                ho_ImageScaled = null;
            HObject ho_ImageDisp = null,
                ho_ImageRotate = null,
                ho_ObjectSelected = null;
            HObject ho_ImageR = null,
                ho_ImageG = null,
                ho_ImageB = null;
            HObject ho_MultiChannelImage = null,
                ho_ImageGray = null,
                ho_RegionDifference = null;

            // Local control variables

            HTuple hv_CamParam = new HTuple(),
                hv_ImageWidth = new HTuple();
            HTuple hv_ImageHeight = new HTuple(),
                hv_CamPose = new HTuple();
            HTuple hv_HomMat3D = new HTuple(),
                hv_HomMat3DInvert = new HTuple();
            HTuple hv_Rows = new HTuple(),
                hv_Columns = new HTuple();
            HTuple hv_LinCoord = new HTuple(),
                hv_Qx = new HTuple();
            HTuple hv_Qy = new HTuple(),
                hv_Qz = new HTuple(),
                hv_ImageRow = new HTuple();
            HTuple hv_ImageColumn = new HTuple(),
                hv_Mask = new HTuple();
            HTuple hv_ImageRowSub = new HTuple(),
                hv_ImageColumnSub = new HTuple();
            HTuple hv_ClosingRad = new HTuple(),
                hv_Number = new HTuple();
            HTuple hv_WindowHandle = new HTuple(),
                hv_Message = new HTuple();
            HTuple hv_MessageWrapped = new HTuple(),
                hv_Grayval = new HTuple();
            HTuple hv_Grayval1 = new HTuple(),
                hv_NumberUnrolled = new HTuple();
            HTuple hv_FillColor = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_UnrolledImagesOut);
            HOperatorSet.GenEmptyObj(out ho_UnrolledOut);
            HOperatorSet.GenEmptyObj(out ho_RegionMaskOut);
            HOperatorSet.GenEmptyObj(out ho_DomainUnrolledOut);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolledR);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolledG);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolledB);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolled);
            HOperatorSet.GenEmptyObj(out ho_Region);
            HOperatorSet.GenEmptyObj(out ho_RegionTrans);
            HOperatorSet.GenEmptyObj(out ho_ConnectedRegions);
            HOperatorSet.GenEmptyObj(out ho_Image);
            HOperatorSet.GenEmptyObj(out ho_ImagePart);
            HOperatorSet.GenEmptyObj(out ho_ImageReduced);
            HOperatorSet.GenEmptyObj(out ho_ImageScaled);
            HOperatorSet.GenEmptyObj(out ho_ImageDisp);
            HOperatorSet.GenEmptyObj(out ho_ImageRotate);
            HOperatorSet.GenEmptyObj(out ho_ObjectSelected);
            HOperatorSet.GenEmptyObj(out ho_ImageR);
            HOperatorSet.GenEmptyObj(out ho_ImageG);
            HOperatorSet.GenEmptyObj(out ho_ImageB);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImage);
            HOperatorSet.GenEmptyObj(out ho_ImageGray);
            HOperatorSet.GenEmptyObj(out ho_RegionDifference);
            try
            {
                //global tuple DisplayIntermediateResults
                //global tuple WindowWidthLimit
                //global tuple WindowHeightLimit
                ho_UnrolledImagesOut.Dispose();
                ho_UnrolledImagesOut = new HObject(ho_UnrolledImages);
                if ((int)(hv_ColorMosaic) != 0)
                {
                    ho_ImageUnrolledR.Dispose();
                    HOperatorSet.GenImageConst(
                        out ho_ImageUnrolledR,
                        "byte",
                        hv_MosaicWidth,
                        hv_MosaicHeight
                    );
                    ho_ImageUnrolledG.Dispose();
                    HOperatorSet.GenImageConst(
                        out ho_ImageUnrolledG,
                        "byte",
                        hv_MosaicWidth,
                        hv_MosaicHeight
                    );
                    ho_ImageUnrolledB.Dispose();
                    HOperatorSet.GenImageConst(
                        out ho_ImageUnrolledB,
                        "byte",
                        hv_MosaicWidth,
                        hv_MosaicHeight
                    );
                }
                else
                {
                    ho_ImageUnrolled.Dispose();
                    HOperatorSet.GenImageConst(
                        out ho_ImageUnrolled,
                        "byte",
                        hv_MosaicWidth,
                        hv_MosaicHeight
                    );
                }
                //
                hv_CamParam.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    hv_Cam,
                    "params",
                    out hv_CamParam
                );
                hv_ImageWidth.Dispose();
                get_cam_par_data(hv_CamParam, "image_width", out hv_ImageWidth);
                hv_ImageHeight.Dispose();
                get_cam_par_data(hv_CamParam, "image_height", out hv_ImageHeight);
                hv_CamPose.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    hv_Cam,
                    "pose",
                    out hv_CamPose
                );
                hv_HomMat3D.Dispose();
                HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                hv_HomMat3DInvert.Dispose();
                HOperatorSet.HomMat3dInvert(hv_HomMat3D, out hv_HomMat3DInvert);
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_Region.Dispose();
                    HOperatorSet.SelectObj(ho_RegionsDilation, out ho_Region, hv_Cam + 1);
                }
                hv_Rows.Dispose();
                hv_Columns.Dispose();
                HOperatorSet.GetRegionPoints(ho_Region, out hv_Rows, out hv_Columns);
                hv_LinCoord.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_LinCoord = (hv_Rows * hv_NumPointsPerSlice) + hv_Columns;
                }
                //
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Qx.Dispose();
                    hv_Qy.Dispose();
                    hv_Qz.Dispose();
                    HOperatorSet.AffineTransPoint3d(
                        hv_HomMat3DInvert,
                        hv_CylinderPointsX.TupleSelect(hv_LinCoord),
                        hv_CylinderPointsY.TupleSelect(hv_LinCoord),
                        hv_CylinderPointsZ.TupleSelect(hv_LinCoord),
                        out hv_Qx,
                        out hv_Qy,
                        out hv_Qz
                    );
                }
                hv_ImageRow.Dispose();
                hv_ImageColumn.Dispose();
                HOperatorSet.Project3dPoint(
                    hv_Qx,
                    hv_Qy,
                    hv_Qz,
                    hv_CamParam,
                    out hv_ImageRow,
                    out hv_ImageColumn
                );
                //
                hv_Mask.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Mask = (
                        new HTuple(
                            (
                                new HTuple(
                                    ((hv_ImageRow.TupleGreaterEqualElem(0))).TupleAnd(
                                        hv_ImageRow.TupleLessEqualElem(hv_ImageHeight - 1)
                                    )
                                )
                            ).TupleAnd(hv_ImageColumn.TupleGreaterEqualElem(0))
                        )
                    ).TupleAnd(hv_ImageColumn.TupleLessEqualElem(hv_ImageWidth - 1));
                }
                hv_ImageRowSub.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ImageRowSub = hv_ImageRow.TupleSelectMask(hv_Mask);
                }
                hv_ImageColumnSub.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ImageColumnSub = hv_ImageColumn.TupleSelectMask(hv_Mask);
                }
                //
                if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                {
                    ho_Region.Dispose();
                    HOperatorSet.GenRegionPoints(out ho_Region, hv_ImageRowSub, hv_ImageColumnSub);
                    for (
                        hv_ClosingRad = 1.5;
                        (double)hv_ClosingRad <= 15.5;
                        hv_ClosingRad = (double)hv_ClosingRad + 1
                    )
                    {
                        ho_RegionTrans.Dispose();
                        HOperatorSet.ClosingCircle(ho_Region, out ho_RegionTrans, hv_ClosingRad);
                        ho_ConnectedRegions.Dispose();
                        HOperatorSet.Connection(ho_RegionTrans, out ho_ConnectedRegions);
                        hv_Number.Dispose();
                        HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                        if ((int)(new HTuple(hv_Number.TupleEqual(1))) != 0)
                        {
                            break;
                        }
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_Image.Dispose();
                        HOperatorSet.SelectObj(ho_ImagesRectified, out ho_Image, hv_Cam + 1);
                    }
                    ho_ImagePart.Dispose();
                    HOperatorSet.CopyImage(ho_Image, out ho_ImagePart);
                    ho_ImageReduced.Dispose();
                    HOperatorSet.ReduceDomain(ho_ImagePart, ho_RegionTrans, out ho_ImageReduced);
                    ho_ImageScaled.Dispose();
                    HOperatorSet.ScaleImage(ho_ImageReduced, out ho_ImageScaled, 0.25, 150);
                    ho_ImageDisp.Dispose();
                    HOperatorSet.CopyImage(ho_Image, out ho_ImageDisp);
                    HOperatorSet.OverpaintGray(ho_ImageDisp, ho_ImageScaled);
                    ho_ImageRotate.Dispose();
                    HOperatorSet.RotateImage(ho_ImageDisp, out ho_ImageRotate, -90, "constant");
                    if (HDevWindowStack.IsOpen())
                    {
                        hv_WindowHandle = HDevWindowStack.GetActive();
                    }
                    dev_resize_window_fit_image(
                        ho_ImageRotate,
                        0,
                        0,
                        ExpGetGlobalVar_WindowWidthLimit(),
                        ExpGetGlobalVar_WindowHeightLimit()
                    );
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.DispObj(ho_ImageRotate, HDevWindowStack.GetActive());
                    }
                    hv_Message.Dispose();
                    hv_Message = "Image part that will be unrolled";
                    hv_MessageWrapped.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MessageWrapped = ((hv_Message + " ")).TupleRegexpReplace(
                            (new HTuple("(.{0,40})\\s")).TupleConcat("replace_all"),
                            "$1\n"
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        disp_message(
                            hv_WindowHandle,
                            ((("Camera " + (hv_Cam + 1)) + ":")).TupleConcat(hv_MessageWrapped),
                            "window",
                            12,
                            12,
                            "black",
                            "true"
                        );
                    }
                    // stop(...); only in hdevelop
                }
                //
                if ((int)(hv_ColorMosaic) != 0)
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ObjectSelected.Dispose();
                        HOperatorSet.SelectObj(
                            ho_ImagesRectified,
                            out ho_ObjectSelected,
                            hv_Cam + 1
                        );
                    }
                    ho_ImageR.Dispose();
                    ho_ImageG.Dispose();
                    ho_ImageB.Dispose();
                    HOperatorSet.Decompose3(
                        ho_ObjectSelected,
                        out ho_ImageR,
                        out ho_ImageG,
                        out ho_ImageB
                    );
                    //
                    if ((int)(hv_HighImageQuality) != 0)
                    {
                        hv_Grayval.Dispose();
                        HOperatorSet.GetGrayvalInterpolated(
                            ho_ImageR,
                            hv_ImageRowSub,
                            hv_ImageColumnSub,
                            "bilinear",
                            out hv_Grayval
                        );
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetGrayval(
                                ho_ImageUnrolledR,
                                hv_Rows.TupleSelectMask(hv_Mask),
                                hv_Columns.TupleSelectMask(hv_Mask),
                                hv_Grayval
                            );
                        }
                        hv_Grayval.Dispose();
                        HOperatorSet.GetGrayvalInterpolated(
                            ho_ImageG,
                            hv_ImageRowSub,
                            hv_ImageColumnSub,
                            "bilinear",
                            out hv_Grayval
                        );
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetGrayval(
                                ho_ImageUnrolledG,
                                hv_Rows.TupleSelectMask(hv_Mask),
                                hv_Columns.TupleSelectMask(hv_Mask),
                                hv_Grayval
                            );
                        }
                        hv_Grayval.Dispose();
                        HOperatorSet.GetGrayvalInterpolated(
                            ho_ImageB,
                            hv_ImageRowSub,
                            hv_ImageColumnSub,
                            "bilinear",
                            out hv_Grayval
                        );
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetGrayval(
                                ho_ImageUnrolledB,
                                hv_Rows.TupleSelectMask(hv_Mask),
                                hv_Columns.TupleSelectMask(hv_Mask),
                                hv_Grayval
                            );
                        }
                        ho_MultiChannelImage.Dispose();
                        HOperatorSet.Compose3(
                            ho_ImageUnrolledR,
                            ho_ImageUnrolledG,
                            ho_ImageUnrolledB,
                            out ho_MultiChannelImage
                        );
                    }
                    else
                    {
                        hv_Grayval1.Dispose();
                        HOperatorSet.GetGrayval(
                            ho_ObjectSelected,
                            hv_ImageRowSub,
                            hv_ImageColumnSub,
                            out hv_Grayval1
                        );
                        ho_MultiChannelImage.Dispose();
                        HOperatorSet.Compose3(
                            ho_ImageUnrolledR,
                            ho_ImageUnrolledG,
                            ho_ImageUnrolledB,
                            out ho_MultiChannelImage
                        );
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetGrayval(
                                ho_MultiChannelImage,
                                hv_Rows.TupleSelectMask(hv_Mask),
                                hv_Columns.TupleSelectMask(hv_Mask),
                                hv_Grayval1
                            );
                        }
                    }
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConcatObj(
                            ho_UnrolledImagesOut,
                            ho_MultiChannelImage,
                            out ExpTmpOutVar_0
                        );
                        ho_UnrolledImagesOut.Dispose();
                        ho_UnrolledImagesOut = ExpTmpOutVar_0;
                    }
                }
                else
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageGray.Dispose();
                        HOperatorSet.SelectObj(
                            ho_ImagesGrayRectified,
                            out ho_ImageGray,
                            hv_Cam + 1
                        );
                    }
                    //
                    if ((int)(hv_HighImageQuality) != 0)
                    {
                        hv_Grayval.Dispose();
                        HOperatorSet.GetGrayvalInterpolated(
                            ho_ImageGray,
                            hv_ImageRowSub,
                            hv_ImageColumnSub,
                            "bilinear",
                            out hv_Grayval
                        );
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetGrayval(
                                ho_ImageUnrolled,
                                hv_Rows.TupleSelectMask(hv_Mask),
                                hv_Columns.TupleSelectMask(hv_Mask),
                                hv_Grayval
                            );
                        }
                    }
                    else
                    {
                        hv_Grayval1.Dispose();
                        HOperatorSet.GetGrayval(
                            ho_ImageGray,
                            hv_ImageRowSub,
                            hv_ImageColumnSub,
                            out hv_Grayval1
                        );
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            HOperatorSet.SetGrayval(
                                ho_ImageUnrolled,
                                hv_Rows.TupleSelectMask(hv_Mask),
                                hv_Columns.TupleSelectMask(hv_Mask),
                                hv_Grayval1
                            );
                        }
                    }
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConcatObj(
                            ho_UnrolledImagesOut,
                            ho_ImageUnrolled,
                            out ExpTmpOutVar_0
                        );
                        ho_UnrolledImagesOut.Dispose();
                        ho_UnrolledImagesOut = ExpTmpOutVar_0;
                    }
                }
                //
                if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                {
                    hv_NumberUnrolled.Dispose();
                    HOperatorSet.CountObj(ho_UnrolledImagesOut, out hv_NumberUnrolled);
                    ho_UnrolledOut.Dispose();
                    HOperatorSet.SelectObj(
                        ho_UnrolledImagesOut,
                        out ho_UnrolledOut,
                        hv_NumberUnrolled
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_RegionMaskOut.Dispose();
                        HOperatorSet.GenRegionPoints(
                            out ho_RegionMaskOut,
                            hv_Rows.TupleSelectMask(hv_Mask),
                            hv_Columns.TupleSelectMask(hv_Mask)
                        );
                    }
                    ho_DomainUnrolledOut.Dispose();
                    HOperatorSet.GetDomain(ho_UnrolledOut, out ho_DomainUnrolledOut);
                    ho_RegionDifference.Dispose();
                    HOperatorSet.Difference(
                        ho_DomainUnrolledOut,
                        ho_RegionMaskOut,
                        out ho_RegionDifference
                    );
                    if ((int)(hv_ColorMosaic) != 0)
                    {
                        hv_FillColor.Dispose();
                        hv_FillColor = new HTuple();
                        hv_FillColor[0] = 255;
                        hv_FillColor[1] = 255;
                        hv_FillColor[2] = 255;
                    }
                    else
                    {
                        hv_FillColor.Dispose();
                        hv_FillColor = 255;
                    }
                    HOperatorSet.OverpaintRegion(
                        ho_UnrolledOut,
                        ho_RegionDifference,
                        hv_FillColor,
                        "fill"
                    );
                    dev_resize_window_fit_image(
                        ho_UnrolledOut,
                        0,
                        0,
                        ExpGetGlobalVar_WindowWidthLimit(),
                        ExpGetGlobalVar_WindowHeightLimit()
                    );
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.DispObj(ho_UnrolledOut, HDevWindowStack.GetActive());
                    }
                    hv_Message.Dispose();
                    hv_Message = "Unrolled image";
                    hv_MessageWrapped.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MessageWrapped = ((hv_Message + " ")).TupleRegexpReplace(
                            (new HTuple("(.{0,40})\\s")).TupleConcat("replace_all"),
                            "$1\n"
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        disp_message(
                            hv_WindowHandle,
                            ((("Camera " + (hv_Cam + 1)) + ":")).TupleConcat(hv_MessageWrapped),
                            "window",
                            12,
                            12,
                            "black",
                            "true"
                        );
                    }
                    // stop(...); only in hdevelop
                }
                ho_ImageUnrolledR.Dispose();
                ho_ImageUnrolledG.Dispose();
                ho_ImageUnrolledB.Dispose();
                ho_ImageUnrolled.Dispose();
                ho_Region.Dispose();
                ho_RegionTrans.Dispose();
                ho_ConnectedRegions.Dispose();
                ho_Image.Dispose();
                ho_ImagePart.Dispose();
                ho_ImageReduced.Dispose();
                ho_ImageScaled.Dispose();
                ho_ImageDisp.Dispose();
                ho_ImageRotate.Dispose();
                ho_ObjectSelected.Dispose();
                ho_ImageR.Dispose();
                ho_ImageG.Dispose();
                ho_ImageB.Dispose();
                ho_MultiChannelImage.Dispose();
                ho_ImageGray.Dispose();
                ho_RegionDifference.Dispose();

                hv_CamParam.Dispose();
                hv_ImageWidth.Dispose();
                hv_ImageHeight.Dispose();
                hv_CamPose.Dispose();
                hv_HomMat3D.Dispose();
                hv_HomMat3DInvert.Dispose();
                hv_Rows.Dispose();
                hv_Columns.Dispose();
                hv_LinCoord.Dispose();
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                hv_ImageRow.Dispose();
                hv_ImageColumn.Dispose();
                hv_Mask.Dispose();
                hv_ImageRowSub.Dispose();
                hv_ImageColumnSub.Dispose();
                hv_ClosingRad.Dispose();
                hv_Number.Dispose();
                hv_WindowHandle.Dispose();
                hv_Message.Dispose();
                hv_MessageWrapped.Dispose();
                hv_Grayval.Dispose();
                hv_Grayval1.Dispose();
                hv_NumberUnrolled.Dispose();
                hv_FillColor.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_ImageUnrolledR.Dispose();
                ho_ImageUnrolledG.Dispose();
                ho_ImageUnrolledB.Dispose();
                ho_ImageUnrolled.Dispose();
                ho_Region.Dispose();
                ho_RegionTrans.Dispose();
                ho_ConnectedRegions.Dispose();
                ho_Image.Dispose();
                ho_ImagePart.Dispose();
                ho_ImageReduced.Dispose();
                ho_ImageScaled.Dispose();
                ho_ImageDisp.Dispose();
                ho_ImageRotate.Dispose();
                ho_ObjectSelected.Dispose();
                ho_ImageR.Dispose();
                ho_ImageG.Dispose();
                ho_ImageB.Dispose();
                ho_MultiChannelImage.Dispose();
                ho_ImageGray.Dispose();
                ho_RegionDifference.Dispose();

                hv_CamParam.Dispose();
                hv_ImageWidth.Dispose();
                hv_ImageHeight.Dispose();
                hv_CamPose.Dispose();
                hv_HomMat3D.Dispose();
                hv_HomMat3DInvert.Dispose();
                hv_Rows.Dispose();
                hv_Columns.Dispose();
                hv_LinCoord.Dispose();
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                hv_ImageRow.Dispose();
                hv_ImageColumn.Dispose();
                hv_Mask.Dispose();
                hv_ImageRowSub.Dispose();
                hv_ImageColumnSub.Dispose();
                hv_ClosingRad.Dispose();
                hv_Number.Dispose();
                hv_WindowHandle.Dispose();
                hv_Message.Dispose();
                hv_MessageWrapped.Dispose();
                hv_Grayval.Dispose();
                hv_Grayval1.Dispose();
                hv_NumberUnrolled.Dispose();
                hv_FillColor.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void sti_imagesub2(
            HObject ho_RegionsDilation,
            HObject ho_UnrolledImages,
            HObject ho_Regions,
            HObject ho_UnrolledImagesShifted,
            HObject ho_OverlappingAreas,
            out HObject ho_UnrolledImagesShiftedOut,
            out HObject ho_OverlappingAreasOut,
            HTuple hv_From,
            HTuple hv_FT,
            HTuple hv_To,
            HTuple hv_Channels,
            HTuple hv_FineAdjustmentMatchingWidth,
            HTuple hv_MosaicHeight,
            HTuple hv_FineAdjustmentMaxShift,
            HTuple hv_ShiftAccumulated,
            HTuple hv_MosaicWidth,
            HTuple hv_HomMat2DAccumulated,
            out HTuple hv_ShiftAccumulatedOut,
            out HTuple hv_HomMat2DAccumulatedOut,
            out HTuple hv_MosaicWidthExt,
            out HTuple hv_MosaicHeightExt
        )
        {
            // Stack for temporary objects
            HObject[] OTemp = new HObject[20];

            // Local iconic variables

            HObject ho_RegionFrom,
                ho_RegionTo,
                ho_ImageFrom;
            HObject ho_ImageTo,
                ho_ConnectedRegions = null,
                ho_SortedRegions = null;
            HObject ho_Domain = null,
                ho_RegionBlack = null,
                ho_ImageF1 = null;
            HObject ho_ImageF2 = null,
                ho_ImageF3 = null,
                ho_ImageT1 = null;
            HObject ho_ImageT2 = null,
                ho_ImageT3 = null,
                ho_GrayFrom = null;
            HObject ho_GrayTo = null,
                ho_RegionIntersection,
                ho_Rectangle;
            HObject ho_ImageFromB,
                ho_ImageModel,
                ho_RoiSearch,
                ho_ImageToB;
            HObject ho_ImageSearch,
                ho_MultiChannelImageLocal = null;
            HObject ho_ImageWR,
                ho_ImageWC,
                ho_VectorField,
                ho_ImagePart;
            HObject ho_Image1 = null,
                ho_Image2 = null,
                ho_Image3 = null;
            HObject ho_ImageUnwarped1 = null,
                ho_ImageUnwarped2 = null;
            HObject ho_ImageUnwarped3 = null,
                ho_MultiChannelImage = null;
            HObject ho_ObjectsConcat = null,
                ho_MorphedImage = null,
                ho_ImageUnwarped = null;
            HObject ho_ImageToBShiftLocal = null,
                ho_ImageToShift = null;
            HObject ho_RegionToShift = null,
                ho_ImageToShiftReduced,
                ho_RegionIntersection1;
            HObject ho_ImageLeft = null,
                ho_ImageRight = null,
                ho_GrayImageLeft = null;
            HObject ho_GrayImageRight = null,
                ho_GrayImageLeftB = null;
            HObject ho_GrayImageRightB = null,
                ho_MultiChannelImage1 = null;

            // Local control variables

            HTuple hv_F = new HTuple(),
                hv_T = new HTuple();
            HTuple hv_Number = new HTuple(),
                hv_RowInters1 = new HTuple();
            HTuple hv_ColumnInters1 = new HTuple(),
                hv_RowInters2 = new HTuple();
            HTuple hv_ColumnInters2 = new HTuple(),
                hv_ColumnCut = new HTuple();
            HTuple hv_VisualizeMorphing = new HTuple(),
                hv_Angles = new HTuple();
            HTuple hv_PaddingTopBottom = new HTuple(),
                hv_ModelID = new HTuple();
            HTuple hv_Values = new HTuple(),
                hv_Row = new HTuple();
            HTuple hv_Column = new HTuple(),
                hv_Angle = new HTuple();
            HTuple hv_Score = new HTuple(),
                hv_HomMat2DI = new HTuple();
            HTuple hv_HomMat2DITrans = new HTuple(),
                hv_HomMat2DITransInvert = new HTuple();
            HTuple hv_HomMat2DRemainder = new HTuple(),
                hv_RowOrig = new HTuple();
            HTuple hv_ColOrig = new HTuple(),
                hv_RowTrans = new HTuple();
            HTuple hv_ColTrans = new HTuple(),
                hv_DRow = new HTuple();
            HTuple hv_DCol = new HTuple(),
                hv_RegionWidth = new HTuple();
            HTuple hv_MorphingWidth = new HTuple(),
                hv_MorphingExtLeft = new HTuple();
            HTuple hv_MorphingWidth2 = new HTuple(),
                hv_MorphingWidth2ExtLeft = new HTuple();
            HTuple hv_RowsWI = new HTuple(),
                hv_ColumnsWI = new HTuple();
            HTuple hv_Ramp = new HTuple(),
                hv_MorphR = new HTuple();
            HTuple hv_MorphC = new HTuple(),
                hv_RW = new HTuple();
            HTuple hv_NumberUI = new HTuple();
            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_UnrolledImagesShiftedOut);
            HOperatorSet.GenEmptyObj(out ho_OverlappingAreasOut);
            HOperatorSet.GenEmptyObj(out ho_RegionFrom);
            HOperatorSet.GenEmptyObj(out ho_RegionTo);
            HOperatorSet.GenEmptyObj(out ho_ImageFrom);
            HOperatorSet.GenEmptyObj(out ho_ImageTo);
            HOperatorSet.GenEmptyObj(out ho_ConnectedRegions);
            HOperatorSet.GenEmptyObj(out ho_SortedRegions);
            HOperatorSet.GenEmptyObj(out ho_Domain);
            HOperatorSet.GenEmptyObj(out ho_RegionBlack);
            HOperatorSet.GenEmptyObj(out ho_ImageF1);
            HOperatorSet.GenEmptyObj(out ho_ImageF2);
            HOperatorSet.GenEmptyObj(out ho_ImageF3);
            HOperatorSet.GenEmptyObj(out ho_ImageT1);
            HOperatorSet.GenEmptyObj(out ho_ImageT2);
            HOperatorSet.GenEmptyObj(out ho_ImageT3);
            HOperatorSet.GenEmptyObj(out ho_GrayFrom);
            HOperatorSet.GenEmptyObj(out ho_GrayTo);
            HOperatorSet.GenEmptyObj(out ho_RegionIntersection);
            HOperatorSet.GenEmptyObj(out ho_Rectangle);
            HOperatorSet.GenEmptyObj(out ho_ImageFromB);
            HOperatorSet.GenEmptyObj(out ho_ImageModel);
            HOperatorSet.GenEmptyObj(out ho_RoiSearch);
            HOperatorSet.GenEmptyObj(out ho_ImageToB);
            HOperatorSet.GenEmptyObj(out ho_ImageSearch);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImageLocal);
            HOperatorSet.GenEmptyObj(out ho_ImageWR);
            HOperatorSet.GenEmptyObj(out ho_ImageWC);
            HOperatorSet.GenEmptyObj(out ho_VectorField);
            HOperatorSet.GenEmptyObj(out ho_ImagePart);
            HOperatorSet.GenEmptyObj(out ho_Image1);
            HOperatorSet.GenEmptyObj(out ho_Image2);
            HOperatorSet.GenEmptyObj(out ho_Image3);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped1);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped2);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped3);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImage);
            HOperatorSet.GenEmptyObj(out ho_ObjectsConcat);
            HOperatorSet.GenEmptyObj(out ho_MorphedImage);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped);
            HOperatorSet.GenEmptyObj(out ho_ImageToBShiftLocal);
            HOperatorSet.GenEmptyObj(out ho_ImageToShift);
            HOperatorSet.GenEmptyObj(out ho_RegionToShift);
            HOperatorSet.GenEmptyObj(out ho_ImageToShiftReduced);
            HOperatorSet.GenEmptyObj(out ho_RegionIntersection1);
            HOperatorSet.GenEmptyObj(out ho_ImageLeft);
            HOperatorSet.GenEmptyObj(out ho_ImageRight);
            HOperatorSet.GenEmptyObj(out ho_GrayImageLeft);
            HOperatorSet.GenEmptyObj(out ho_GrayImageRight);
            HOperatorSet.GenEmptyObj(out ho_GrayImageLeftB);
            HOperatorSet.GenEmptyObj(out ho_GrayImageRightB);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImage1);
            hv_ShiftAccumulatedOut = new HTuple();
            hv_HomMat2DAccumulatedOut = new HTuple();
            hv_MosaicWidthExt = new HTuple();
            hv_MosaicHeightExt = new HTuple();
            try
            {
                ho_OverlappingAreasOut.Dispose();
                ho_OverlappingAreasOut = new HObject(ho_OverlappingAreas);
                ho_UnrolledImagesShiftedOut.Dispose();
                ho_UnrolledImagesShiftedOut = new HObject(ho_UnrolledImagesShifted);
                hv_HomMat2DAccumulatedOut.Dispose();
                hv_HomMat2DAccumulatedOut = new HTuple(hv_HomMat2DAccumulated);
                hv_ShiftAccumulatedOut.Dispose();
                hv_ShiftAccumulatedOut = new HTuple(hv_ShiftAccumulated);
                hv_F.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_F = hv_From.TupleSelect(hv_FT);
                }
                hv_T.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_T = hv_To.TupleSelect(hv_FT);
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_RegionFrom.Dispose();
                    HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionFrom, hv_F + 1);
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_RegionTo.Dispose();
                    HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionTo, hv_T + 1);
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_ImageFrom.Dispose();
                    HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageFrom, hv_F + 1);
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_ImageTo.Dispose();
                    HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageTo, hv_T + 1);
                }
                if (
                    (int)(new HTuple(hv_FT.TupleEqual((new HTuple(hv_From.TupleLength())) - 1)))
                    != 0
                )
                {
                    //Add only right part of last image
                    ho_ConnectedRegions.Dispose();
                    HOperatorSet.Connection(ho_RegionTo, out ho_ConnectedRegions);
                    hv_Number.Dispose();
                    HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                    if ((int)(new HTuple(hv_Number.TupleGreater(1))) != 0)
                    {
                        ho_SortedRegions.Dispose();
                        HOperatorSet.SortRegion(
                            ho_ConnectedRegions,
                            out ho_SortedRegions,
                            "character",
                            "true",
                            "column"
                        );
                        ho_RegionTo.Dispose();
                        HOperatorSet.SelectObj(ho_SortedRegions, out ho_RegionTo, 2);
                        ho_Domain.Dispose();
                        HOperatorSet.GetDomain(ho_ImageTo, out ho_Domain);
                        ho_RegionBlack.Dispose();
                        HOperatorSet.Difference(ho_Domain, ho_RegionTo, out ho_RegionBlack);
                        HOperatorSet.OverpaintRegion(
                            ho_ImageTo,
                            ho_RegionBlack,
                            ((new HTuple(0)).TupleConcat(0)).TupleConcat(0),
                            "fill"
                        );
                    }
                }
                //Select the kind of image used for matching
                if ((int)(new HTuple(hv_Channels.TupleEqual(3))) != 0)
                {
                    switch (2)
                    {
                        case 1:
                            ho_ImageF1.Dispose();
                            ho_ImageF2.Dispose();
                            ho_ImageF3.Dispose();
                            HOperatorSet.Decompose3(
                                ho_ImageFrom,
                                out ho_ImageF1,
                                out ho_ImageF2,
                                out ho_ImageF3
                            );
                            ho_ImageT1.Dispose();
                            ho_ImageT2.Dispose();
                            ho_ImageT3.Dispose();
                            HOperatorSet.Decompose3(
                                ho_ImageTo,
                                out ho_ImageT1,
                                out ho_ImageT2,
                                out ho_ImageT3
                            );
                            ho_ImageFrom.Dispose();
                            HOperatorSet.ConvertImageType(ho_ImageF1, out ho_ImageFrom, "real");
                            ho_ImageTo.Dispose();
                            HOperatorSet.ConvertImageType(ho_ImageT1, out ho_ImageTo, "real");
                            break;
                        case 2:
                            ho_GrayFrom.Dispose();
                            HOperatorSet.Rgb1ToGray(ho_ImageFrom, out ho_GrayFrom);
                            ho_GrayTo.Dispose();
                            HOperatorSet.Rgb1ToGray(ho_ImageTo, out ho_GrayTo);
                            ho_ImageFrom.Dispose();
                            HOperatorSet.ConvertImageType(ho_GrayFrom, out ho_ImageFrom, "real");
                            ho_ImageTo.Dispose();
                            HOperatorSet.ConvertImageType(ho_GrayTo, out ho_ImageTo, "real");
                            break;
                    }
                }
                else
                {
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConvertImageType(ho_ImageFrom, out ExpTmpOutVar_0, "real");
                        ho_ImageFrom.Dispose();
                        ho_ImageFrom = ExpTmpOutVar_0;
                    }
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConvertImageType(ho_ImageTo, out ExpTmpOutVar_0, "real");
                        ho_ImageTo.Dispose();
                        ho_ImageTo = ExpTmpOutVar_0;
                    }
                }
                ho_RegionIntersection.Dispose();
                HOperatorSet.Intersection(ho_RegionFrom, ho_RegionTo, out ho_RegionIntersection);
                hv_RowInters1.Dispose();
                hv_ColumnInters1.Dispose();
                hv_RowInters2.Dispose();
                hv_ColumnInters2.Dispose();
                HOperatorSet.SmallestRectangle1(
                    ho_RegionIntersection,
                    out hv_RowInters1,
                    out hv_ColumnInters1,
                    out hv_RowInters2,
                    out hv_ColumnInters2
                );
                hv_ColumnCut.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ColumnCut = (hv_ColumnInters1 + hv_ColumnInters2) / 2;
                }
                hv_VisualizeMorphing.Dispose();
                hv_VisualizeMorphing = 0;
                //Create Ncc model
                hv_Angles.Dispose();
                hv_Angles = new HTuple();
                hv_Angles[0] = -3;
                hv_Angles[1] = 3;
                hv_PaddingTopBottom.Dispose();
                hv_PaddingTopBottom = 20;
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_Rectangle.Dispose();
                    HOperatorSet.GenRectangle1(
                        out ho_Rectangle,
                        hv_PaddingTopBottom,
                        hv_ColumnCut - (hv_FineAdjustmentMatchingWidth / 2),
                        (hv_MosaicHeight - 1) - hv_PaddingTopBottom,
                        hv_ColumnCut + (hv_FineAdjustmentMatchingWidth / 2)
                    );
                }
                ho_ImageFromB.Dispose();
                HOperatorSet.ConvertImageType(ho_ImageFrom, out ho_ImageFromB, "byte");
                ho_ImageModel.Dispose();
                HOperatorSet.ReduceDomain(ho_ImageFromB, ho_Rectangle, out ho_ImageModel);
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ModelID.Dispose();
                    HOperatorSet.CreateNccModel(
                        ho_ImageModel,
                        1,
                        ((hv_Angles.TupleSelect(0))).TupleRad(),
                        (((hv_Angles.TupleSelect(1)) - (hv_Angles.TupleSelect(0)))).TupleRad(),
                        "auto",
                        "use_polarity",
                        out hv_ModelID
                    );
                }
                hv_Values.Dispose();
                HOperatorSet.RegionFeatures(
                    ho_ImageModel,
                    ((new HTuple("row")).TupleConcat("column")).TupleConcat("width"),
                    out hv_Values
                );
                //
                //Create the search image
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_RoiSearch.Dispose();
                    HOperatorSet.GenRectangle2(
                        out ho_RoiSearch,
                        hv_Values.TupleSelect(0),
                        hv_Values.TupleSelect(1),
                        0,
                        hv_FineAdjustmentMaxShift,
                        1
                    );
                }
                ho_ImageToB.Dispose();
                HOperatorSet.ConvertImageType(ho_ImageTo, out ho_ImageToB, "byte");
                ho_ImageSearch.Dispose();
                HOperatorSet.ReduceDomain(ho_ImageToB, ho_RoiSearch, out ho_ImageSearch);
                //
                if ((int)(hv_VisualizeMorphing) != 0)
                {
                    ho_MultiChannelImageLocal.Dispose();
                    HOperatorSet.Compose3(
                        ho_ImageFromB,
                        ho_ImageFromB,
                        ho_ImageToB,
                        out ho_MultiChannelImageLocal
                    );
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                    }
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.DispObj(
                            ho_MultiChannelImageLocal,
                            HDevWindowStack.GetActive()
                        );
                    }
                    // stop(...); only in hdevelop
                }
                //
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Row.Dispose();
                    hv_Column.Dispose();
                    hv_Angle.Dispose();
                    hv_Score.Dispose();
                    HOperatorSet.FindNccModel(
                        ho_ImageSearch,
                        hv_ModelID,
                        ((hv_Angles.TupleSelect(0))).TupleRad(),
                        (((hv_Angles.TupleSelect(1)) - (hv_Angles.TupleSelect(0)))).TupleRad(),
                        0.3,
                        1,
                        1.0,
                        "true",
                        0,
                        out hv_Row,
                        out hv_Column,
                        out hv_Angle,
                        out hv_Score
                    );
                }
                if ((int)(new HTuple((new HTuple(hv_Score.TupleLength())).TupleEqual(0))) != 0)
                {
                    hv_Row.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Row = hv_Values.TupleSelect(0);
                    }
                    hv_Column.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Column = hv_Values.TupleSelect(1);
                    }
                    hv_Angle.Dispose();
                    hv_Angle = 0;
                    hv_Score.Dispose();
                    hv_Score = 0;
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_ImageTo.Dispose();
                    HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageTo, hv_T + 1);
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_ShiftAccumulatedOut =
                            hv_ShiftAccumulatedOut + ((hv_Values.TupleSelect(1)) - hv_Column);
                        hv_ShiftAccumulatedOut.Dispose();
                        hv_ShiftAccumulatedOut = ExpTmpLocalVar_ShiftAccumulatedOut;
                    }
                }
                //
                //The transformation to move the search image onto the model image
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_HomMat2DI.Dispose();
                    HOperatorSet.VectorAngleToRigid(
                        hv_Row,
                        hv_Column,
                        hv_Angle,
                        hv_Values.TupleSelect(0),
                        hv_Values.TupleSelect(1),
                        0,
                        out hv_HomMat2DI
                    );
                }
                //
                //Split the transformation into a translation part in column direction
                //and the remainder
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_HomMat2DITrans.Dispose();
                    HOperatorSet.VectorAngleToRigid(
                        0,
                        hv_Column,
                        0,
                        0,
                        hv_Values.TupleSelect(1),
                        0,
                        out hv_HomMat2DITrans
                    );
                }
                hv_HomMat2DITransInvert.Dispose();
                HOperatorSet.HomMat2dInvert(hv_HomMat2DITrans, out hv_HomMat2DITransInvert);
                hv_HomMat2DRemainder.Dispose();
                HOperatorSet.HomMat2dCompose(
                    hv_HomMat2DI,
                    hv_HomMat2DITransInvert,
                    out hv_HomMat2DRemainder
                );
                //
                //Apply the remainder of the transformation in some kind of local morphing
                //such that the right image fits the left image
                hv_RowOrig.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_RowOrig = HTuple.TupleGenSequence(0, hv_MosaicHeight - 1, 1);
                }
                hv_ColOrig.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_ColOrig = HTuple.TupleGenConst(hv_MosaicHeight, hv_ColumnCut);
                }
                hv_RowTrans.Dispose();
                hv_ColTrans.Dispose();
                HOperatorSet.AffineTransPixel(
                    hv_HomMat2DRemainder,
                    hv_RowOrig,
                    hv_ColOrig,
                    out hv_RowTrans,
                    out hv_ColTrans
                );
                hv_DRow.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DRow = hv_RowOrig - hv_RowTrans;
                }
                hv_DCol.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DCol = hv_ColOrig - hv_ColTrans;
                }
                //
                hv_RegionWidth.Dispose();
                HOperatorSet.RegionFeatures(ho_Regions, "width", out hv_RegionWidth);
                hv_MorphingWidth.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MorphingWidth = ((0.2 * (hv_RegionWidth.TupleMin()))).TupleInt();
                }
                hv_MorphingExtLeft.Dispose();
                hv_MorphingExtLeft = 10;
                hv_MorphingWidth2.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MorphingWidth2 = (2 * hv_MorphingWidth) + 1;
                }
                hv_MorphingWidth2ExtLeft.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MorphingWidth2ExtLeft = hv_MorphingWidth2 + hv_MorphingExtLeft;
                }
                ho_ImageWR.Dispose();
                HOperatorSet.GenImageConst(
                    out ho_ImageWR,
                    "real",
                    hv_MorphingWidth2ExtLeft,
                    hv_MosaicHeight
                );
                ho_ImageWC.Dispose();
                HOperatorSet.GenImageConst(
                    out ho_ImageWC,
                    "real",
                    hv_MorphingWidth2ExtLeft,
                    hv_MosaicHeight
                );
                hv_RowsWI.Dispose();
                hv_ColumnsWI.Dispose();
                HOperatorSet.GetRegionPoints(ho_ImageWR, out hv_RowsWI, out hv_ColumnsWI);
                hv_Ramp.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Ramp = new HTuple();
                    hv_Ramp = hv_Ramp.TupleConcat(HTuple.TupleGenConst(hv_MorphingExtLeft, 2.0));
                    hv_Ramp = hv_Ramp.TupleConcat(
                        (
                            (
                                (
                                    HTuple.TupleGenConst(
                                        hv_MorphingWidth2 - 1,
                                        2.0 / hv_MorphingWidth2
                                    )
                                ).TupleCumul()
                            )
                        ).TupleInverse()
                    );
                    hv_Ramp = hv_Ramp.TupleConcat(0);
                }
                hv_MorphR.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MorphR = HTuple.TupleGenConst(new HTuple(hv_RowsWI.TupleLength()), 0);
                }
                hv_MorphC.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MorphC = HTuple.TupleGenConst(new HTuple(hv_RowsWI.TupleLength()), 0);
                }
                HTuple end_val105 = hv_MosaicHeight - 1;
                HTuple step_val105 = 1;
                for (
                    hv_RW = 0;
                    hv_RW.Continue(end_val105, step_val105);
                    hv_RW = hv_RW.TupleAdd(step_val105)
                )
                {
                    if (hv_MorphR == null)
                        hv_MorphR = new HTuple();
                    hv_MorphR[
                        HTuple.TupleGenSequence(
                            hv_RW * hv_MorphingWidth2ExtLeft,
                            ((hv_RW * hv_MorphingWidth2ExtLeft) + hv_MorphingWidth2ExtLeft) - 1,
                            1
                        )
                    ] = hv_Ramp * (hv_DRow.TupleSelect(hv_RW));
                    if (hv_MorphC == null)
                        hv_MorphC = new HTuple();
                    hv_MorphC[
                        HTuple.TupleGenSequence(
                            hv_RW * hv_MorphingWidth2ExtLeft,
                            ((hv_RW * hv_MorphingWidth2ExtLeft) + hv_MorphingWidth2ExtLeft) - 1,
                            1
                        )
                    ] = hv_Ramp * (hv_DCol.TupleSelect(hv_RW));
                }
                HOperatorSet.SetGrayval(ho_ImageWR, hv_RowsWI, hv_ColumnsWI, hv_MorphR);
                HOperatorSet.SetGrayval(ho_ImageWC, hv_RowsWI, hv_ColumnsWI, hv_MorphC);
                ho_VectorField.Dispose();
                HOperatorSet.RealToVectorField(
                    ho_ImageWR,
                    ho_ImageWC,
                    out ho_VectorField,
                    "vector_field_relative"
                );
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_ImagePart.Dispose();
                    HOperatorSet.CropRectangle1(
                        ho_ImageTo,
                        out ho_ImagePart,
                        0,
                        (hv_ColumnCut - hv_MorphingWidth) - hv_MorphingExtLeft,
                        hv_MosaicHeight - 1,
                        hv_ColumnCut + hv_MorphingWidth
                    );
                }
                if ((int)(new HTuple(hv_Channels.TupleEqual(3))) != 0)
                {
                    ho_Image1.Dispose();
                    ho_Image2.Dispose();
                    ho_Image3.Dispose();
                    HOperatorSet.Decompose3(
                        ho_ImagePart,
                        out ho_Image1,
                        out ho_Image2,
                        out ho_Image3
                    );
                    ho_ImageUnwarped1.Dispose();
                    HOperatorSet.UnwarpImageVectorField(
                        ho_Image1,
                        ho_VectorField,
                        out ho_ImageUnwarped1
                    );
                    ho_ImageUnwarped2.Dispose();
                    HOperatorSet.UnwarpImageVectorField(
                        ho_Image2,
                        ho_VectorField,
                        out ho_ImageUnwarped2
                    );
                    ho_ImageUnwarped3.Dispose();
                    HOperatorSet.UnwarpImageVectorField(
                        ho_Image3,
                        ho_VectorField,
                        out ho_ImageUnwarped3
                    );
                    ho_MultiChannelImage.Dispose();
                    HOperatorSet.Compose3(
                        ho_ImageUnwarped1,
                        ho_ImageUnwarped2,
                        ho_ImageUnwarped3,
                        out ho_MultiChannelImage
                    );
                    ho_ObjectsConcat.Dispose();
                    HOperatorSet.ConcatObj(ho_ImageTo, ho_MultiChannelImage, out ho_ObjectsConcat);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_MorphedImage.Dispose();
                        HOperatorSet.TileImagesOffset(
                            ho_ObjectsConcat,
                            out ho_MorphedImage,
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(0)).TupleConcat(
                                (hv_ColumnCut - hv_MorphingWidth) - hv_MorphingExtLeft
                            ),
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(-1)).TupleConcat(-1),
                            (new HTuple(-1)).TupleConcat(-1),
                            hv_MosaicWidth,
                            hv_MosaicHeight
                        );
                    }
                }
                else
                {
                    ho_ImageUnwarped.Dispose();
                    HOperatorSet.UnwarpImageVectorField(
                        ho_ImagePart,
                        ho_VectorField,
                        out ho_ImageUnwarped
                    );
                    ho_ObjectsConcat.Dispose();
                    HOperatorSet.ConcatObj(ho_ImageToB, ho_ImageUnwarped, out ho_ObjectsConcat);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_MorphedImage.Dispose();
                        HOperatorSet.TileImagesOffset(
                            ho_ObjectsConcat,
                            out ho_MorphedImage,
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(0)).TupleConcat(
                                (hv_ColumnCut - hv_MorphingWidth) - hv_MorphingExtLeft
                            ),
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(-1)).TupleConcat(-1),
                            (new HTuple(-1)).TupleConcat(-1),
                            hv_MosaicWidth,
                            hv_MosaicHeight
                        );
                    }
                }
                //
                if ((int)(hv_VisualizeMorphing) != 0)
                {
                    ho_ImageToBShiftLocal.Dispose();
                    HOperatorSet.AffineTransImage(
                        ho_MorphedImage,
                        out ho_ImageToBShiftLocal,
                        hv_HomMat2DITrans,
                        "constant",
                        "false"
                    );
                    ho_MultiChannelImageLocal.Dispose();
                    HOperatorSet.Compose3(
                        ho_ImageFromB,
                        ho_ImageFromB,
                        ho_ImageToBShiftLocal,
                        out ho_MultiChannelImageLocal
                    );
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                    }
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.DispObj(
                            ho_MultiChannelImageLocal,
                            HDevWindowStack.GetActive()
                        );
                    }
                    // stop(...); only in hdevelop
                }
                //
                {
                    HTuple ExpTmpOutVar_0;
                    HOperatorSet.HomMat2dCompose(
                        hv_HomMat2DAccumulatedOut,
                        hv_HomMat2DITrans,
                        out ExpTmpOutVar_0
                    );
                    hv_HomMat2DAccumulatedOut.Dispose();
                    hv_HomMat2DAccumulatedOut = ExpTmpOutVar_0;
                }
                if (
                    (int)(new HTuple(hv_FT.TupleLess((new HTuple(hv_From.TupleLength())) - 1))) != 0
                )
                {
                    ho_ImageToShift.Dispose();
                    HOperatorSet.AffineTransImage(
                        ho_MorphedImage,
                        out ho_ImageToShift,
                        hv_HomMat2DAccumulatedOut,
                        "constant",
                        "false"
                    );
                    ho_RegionToShift.Dispose();
                    HOperatorSet.AffineTransRegion(
                        ho_RegionTo,
                        out ho_RegionToShift,
                        hv_HomMat2DAccumulatedOut,
                        "nearest_neighbor"
                    );
                }
                else
                {
                    //Because of the matching results, the final mosaic width may have changed
                    ho_ImageToShift.Dispose();
                    HOperatorSet.AffineTransImage(
                        ho_MorphedImage,
                        out ho_ImageToShift,
                        hv_HomMat2DAccumulatedOut,
                        "constant",
                        "true"
                    );
                    ho_RegionToShift.Dispose();
                    HOperatorSet.AffineTransRegion(
                        ho_RegionTo,
                        out ho_RegionToShift,
                        hv_HomMat2DAccumulatedOut,
                        "nearest_neighbor"
                    );
                    hv_MosaicWidthExt.Dispose();
                    hv_MosaicHeightExt.Dispose();
                    HOperatorSet.GetImageSize(
                        ho_ImageToShift,
                        out hv_MosaicWidthExt,
                        out hv_MosaicHeightExt
                    );
                }
                //
                ho_ImageToShiftReduced.Dispose();
                HOperatorSet.ReduceDomain(
                    ho_ImageToShift,
                    ho_RegionToShift,
                    out ho_ImageToShiftReduced
                );
                {
                    HObject ExpTmpOutVar_0;
                    HOperatorSet.ConcatObj(
                        ho_UnrolledImagesShiftedOut,
                        ho_ImageToShiftReduced,
                        out ExpTmpOutVar_0
                    );
                    ho_UnrolledImagesShiftedOut.Dispose();
                    ho_UnrolledImagesShiftedOut = ExpTmpOutVar_0;
                }
                ho_RegionIntersection1.Dispose();
                HOperatorSet.Intersection(
                    ho_RegionFrom,
                    ho_RegionToShift,
                    out ho_RegionIntersection1
                );
                {
                    HObject ExpTmpOutVar_0;
                    HOperatorSet.Union2(
                        ho_OverlappingAreasOut,
                        ho_RegionIntersection1,
                        out ExpTmpOutVar_0
                    );
                    ho_OverlappingAreasOut.Dispose();
                    ho_OverlappingAreasOut = ExpTmpOutVar_0;
                }
                //
                if ((int)(hv_VisualizeMorphing) != 0)
                {
                    hv_NumberUI.Dispose();
                    HOperatorSet.CountObj(ho_UnrolledImagesShiftedOut, out hv_NumberUI);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageLeft.Dispose();
                        HOperatorSet.SelectObj(
                            ho_UnrolledImagesShiftedOut,
                            out ho_ImageLeft,
                            hv_NumberUI - 1
                        );
                    }
                    ho_ImageRight.Dispose();
                    HOperatorSet.SelectObj(
                        ho_UnrolledImagesShiftedOut,
                        out ho_ImageRight,
                        hv_NumberUI
                    );
                    ho_GrayImageLeft.Dispose();
                    HOperatorSet.Rgb1ToGray(ho_ImageLeft, out ho_GrayImageLeft);
                    ho_GrayImageRight.Dispose();
                    HOperatorSet.Rgb1ToGray(ho_ImageRight, out ho_GrayImageRight);
                    ho_GrayImageLeftB.Dispose();
                    HOperatorSet.ConvertImageType(ho_GrayImageLeft, out ho_GrayImageLeftB, "byte");
                    ho_GrayImageRightB.Dispose();
                    HOperatorSet.ConvertImageType(
                        ho_GrayImageRight,
                        out ho_GrayImageRightB,
                        "byte"
                    );
                    ho_MultiChannelImage1.Dispose();
                    HOperatorSet.Compose3(
                        ho_GrayImageLeftB,
                        ho_GrayImageLeftB,
                        ho_GrayImageRightB,
                        out ho_MultiChannelImage1
                    );
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                    }
                    if (HDevWindowStack.IsOpen())
                    {
                        HOperatorSet.DispObj(ho_MultiChannelImage1, HDevWindowStack.GetActive());
                    }
                    // stop(...); only in hdevelop
                }
                ho_RegionFrom.Dispose();
                ho_RegionTo.Dispose();
                ho_ImageFrom.Dispose();
                ho_ImageTo.Dispose();
                ho_ConnectedRegions.Dispose();
                ho_SortedRegions.Dispose();
                ho_Domain.Dispose();
                ho_RegionBlack.Dispose();
                ho_ImageF1.Dispose();
                ho_ImageF2.Dispose();
                ho_ImageF3.Dispose();
                ho_ImageT1.Dispose();
                ho_ImageT2.Dispose();
                ho_ImageT3.Dispose();
                ho_GrayFrom.Dispose();
                ho_GrayTo.Dispose();
                ho_RegionIntersection.Dispose();
                ho_Rectangle.Dispose();
                ho_ImageFromB.Dispose();
                ho_ImageModel.Dispose();
                ho_RoiSearch.Dispose();
                ho_ImageToB.Dispose();
                ho_ImageSearch.Dispose();
                ho_MultiChannelImageLocal.Dispose();
                ho_ImageWR.Dispose();
                ho_ImageWC.Dispose();
                ho_VectorField.Dispose();
                ho_ImagePart.Dispose();
                ho_Image1.Dispose();
                ho_Image2.Dispose();
                ho_Image3.Dispose();
                ho_ImageUnwarped1.Dispose();
                ho_ImageUnwarped2.Dispose();
                ho_ImageUnwarped3.Dispose();
                ho_MultiChannelImage.Dispose();
                ho_ObjectsConcat.Dispose();
                ho_MorphedImage.Dispose();
                ho_ImageUnwarped.Dispose();
                ho_ImageToBShiftLocal.Dispose();
                ho_ImageToShift.Dispose();
                ho_RegionToShift.Dispose();
                ho_ImageToShiftReduced.Dispose();
                ho_RegionIntersection1.Dispose();
                ho_ImageLeft.Dispose();
                ho_ImageRight.Dispose();
                ho_GrayImageLeft.Dispose();
                ho_GrayImageRight.Dispose();
                ho_GrayImageLeftB.Dispose();
                ho_GrayImageRightB.Dispose();
                ho_MultiChannelImage1.Dispose();

                hv_F.Dispose();
                hv_T.Dispose();
                hv_Number.Dispose();
                hv_RowInters1.Dispose();
                hv_ColumnInters1.Dispose();
                hv_RowInters2.Dispose();
                hv_ColumnInters2.Dispose();
                hv_ColumnCut.Dispose();
                hv_VisualizeMorphing.Dispose();
                hv_Angles.Dispose();
                hv_PaddingTopBottom.Dispose();
                hv_ModelID.Dispose();
                hv_Values.Dispose();
                hv_Row.Dispose();
                hv_Column.Dispose();
                hv_Angle.Dispose();
                hv_Score.Dispose();
                hv_HomMat2DI.Dispose();
                hv_HomMat2DITrans.Dispose();
                hv_HomMat2DITransInvert.Dispose();
                hv_HomMat2DRemainder.Dispose();
                hv_RowOrig.Dispose();
                hv_ColOrig.Dispose();
                hv_RowTrans.Dispose();
                hv_ColTrans.Dispose();
                hv_DRow.Dispose();
                hv_DCol.Dispose();
                hv_RegionWidth.Dispose();
                hv_MorphingWidth.Dispose();
                hv_MorphingExtLeft.Dispose();
                hv_MorphingWidth2.Dispose();
                hv_MorphingWidth2ExtLeft.Dispose();
                hv_RowsWI.Dispose();
                hv_ColumnsWI.Dispose();
                hv_Ramp.Dispose();
                hv_MorphR.Dispose();
                hv_MorphC.Dispose();
                hv_RW.Dispose();
                hv_NumberUI.Dispose();

                return;
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_RegionFrom.Dispose();
                ho_RegionTo.Dispose();
                ho_ImageFrom.Dispose();
                ho_ImageTo.Dispose();
                ho_ConnectedRegions.Dispose();
                ho_SortedRegions.Dispose();
                ho_Domain.Dispose();
                ho_RegionBlack.Dispose();
                ho_ImageF1.Dispose();
                ho_ImageF2.Dispose();
                ho_ImageF3.Dispose();
                ho_ImageT1.Dispose();
                ho_ImageT2.Dispose();
                ho_ImageT3.Dispose();
                ho_GrayFrom.Dispose();
                ho_GrayTo.Dispose();
                ho_RegionIntersection.Dispose();
                ho_Rectangle.Dispose();
                ho_ImageFromB.Dispose();
                ho_ImageModel.Dispose();
                ho_RoiSearch.Dispose();
                ho_ImageToB.Dispose();
                ho_ImageSearch.Dispose();
                ho_MultiChannelImageLocal.Dispose();
                ho_ImageWR.Dispose();
                ho_ImageWC.Dispose();
                ho_VectorField.Dispose();
                ho_ImagePart.Dispose();
                ho_Image1.Dispose();
                ho_Image2.Dispose();
                ho_Image3.Dispose();
                ho_ImageUnwarped1.Dispose();
                ho_ImageUnwarped2.Dispose();
                ho_ImageUnwarped3.Dispose();
                ho_MultiChannelImage.Dispose();
                ho_ObjectsConcat.Dispose();
                ho_MorphedImage.Dispose();
                ho_ImageUnwarped.Dispose();
                ho_ImageToBShiftLocal.Dispose();
                ho_ImageToShift.Dispose();
                ho_RegionToShift.Dispose();
                ho_ImageToShiftReduced.Dispose();
                ho_RegionIntersection1.Dispose();
                ho_ImageLeft.Dispose();
                ho_ImageRight.Dispose();
                ho_GrayImageLeft.Dispose();
                ho_GrayImageRight.Dispose();
                ho_GrayImageLeftB.Dispose();
                ho_GrayImageRightB.Dispose();
                ho_MultiChannelImage1.Dispose();

                hv_F.Dispose();
                hv_T.Dispose();
                hv_Number.Dispose();
                hv_RowInters1.Dispose();
                hv_ColumnInters1.Dispose();
                hv_RowInters2.Dispose();
                hv_ColumnInters2.Dispose();
                hv_ColumnCut.Dispose();
                hv_VisualizeMorphing.Dispose();
                hv_Angles.Dispose();
                hv_PaddingTopBottom.Dispose();
                hv_ModelID.Dispose();
                hv_Values.Dispose();
                hv_Row.Dispose();
                hv_Column.Dispose();
                hv_Angle.Dispose();
                hv_Score.Dispose();
                hv_HomMat2DI.Dispose();
                hv_HomMat2DITrans.Dispose();
                hv_HomMat2DITransInvert.Dispose();
                hv_HomMat2DRemainder.Dispose();
                hv_RowOrig.Dispose();
                hv_ColOrig.Dispose();
                hv_RowTrans.Dispose();
                hv_ColTrans.Dispose();
                hv_DRow.Dispose();
                hv_DCol.Dispose();
                hv_RegionWidth.Dispose();
                hv_MorphingWidth.Dispose();
                hv_MorphingExtLeft.Dispose();
                hv_MorphingWidth2.Dispose();
                hv_MorphingWidth2ExtLeft.Dispose();
                hv_RowsWI.Dispose();
                hv_ColumnsWI.Dispose();
                hv_Ramp.Dispose();
                hv_MorphR.Dispose();
                hv_MorphC.Dispose();
                hv_RW.Dispose();
                hv_NumberUI.Dispose();

                throw HDevExpDefaultException;
            }
        }

        public void stitch_images(
            HObject ho_Regions,
            HObject ho_ImagesRectified,
            out HObject ho_FinalMosaic,
            HTuple hv_WindowHandle,
            HTuple hv_FineAdjustmentMaxShift,
            HTuple hv_FineAdjustmentMatchingWidth,
            HTuple hv_BlendingSeam,
            HTuple hv_CameraSetupModelZeroDistInCylinderOrigin,
            HTuple hv_NumCameras,
            HTuple hv_MosaicWidth,
            HTuple hv_MosaicHeight,
            HTuple hv_CylinderPointsX,
            HTuple hv_CylinderPointsY,
            HTuple hv_CylinderPointsZ,
            HTuple hv_NumSlices,
            HTuple hv_NumPointsPerSlice,
            HTuple hv_CylinderRadius,
            HTuple hv_LabelMinRow,
            HTuple hv_LabelMaxRow
        )
        {
            // Stack for temporary objects
            HObject[] OTemp = new HObject[20];

            // Local iconic variables

            HObject ho_RegionsDilation,
                ho_UnrolledImages;
            HObject ho_ImageUnrolled = null,
                ho_Region = null,
                ho_RegionTrans = null;
            HObject ho_ConnectedRegions = null,
                ho_Image = null,
                ho_ImageReduced = null;
            HObject ho_ImageScaled = null,
                ho_ImageDisp = null,
                ho_ImageGray = null;
            HObject ho_RegionMaskOut = null,
                ho_RegionDifference = null;
            HObject ho_ImageUnrolledDisp = null,
                ho_UnrolledImagesShifted;
            HObject ho_RegionFrom,
                ho_ImageFrom,
                ho_SortedRegions,
                ho_ObjectSelected;
            HObject ho_ImageFromReduced,
                ho_OverlappingAreas,
                ho_RegionTo = null;
            HObject ho_ImageTo = null,
                ho_Domain = null,
                ho_RegionBlack = null;
            HObject ho_RegionIntersection = null,
                ho_Rectangle = null,
                ho_ImageFromB = null;
            HObject ho_ImageModel = null,
                ho_RoiSearch = null,
                ho_ImageToB = null;
            HObject ho_ImageSearch = null,
                ho_MultiChannelImageLocal = null;
            HObject ho_ImageWR = null,
                ho_ImageWC = null,
                ho_VectorField = null;
            HObject ho_ImagePart = null,
                ho_ImageUnwarped = null,
                ho_ObjectsConcat = null;
            HObject ho_MorphedImage = null,
                ho_ImageToBShiftLocal = null;
            HObject ho_ImageToShift = null,
                ho_RegionToShift = null,
                ho_ImageToShiftReduced = null;
            HObject ho_RegionIntersection1 = null,
                ho_ImageLeft = null;
            HObject ho_ImageRight = null,
                ho_GrayImageLeft = null,
                ho_GrayImageRight = null;
            HObject ho_GrayImageLeftB = null,
                ho_GrayImageRightB = null;
            HObject ho_MultiChannelImage1 = null,
                ho_I1 = null,
                ho_I2 = null;
            HObject ho_D1 = null,
                ho_D2 = null,
                ho_BlendingMasks,
                ho_ImageM1;
            HObject ho_ImageM,
                ho_ImageMosaic,
                ho_ImageTest,
                ho_Img = null;
            HObject ho_ImgExt = null,
                ho_ImgReal = null,
                ho_Mas = null,
                ho_ImageForStitching = null;

            // Local control variables

            HTuple hv_Indices = new HTuple(),
                hv_SamplePX = new HTuple();
            HTuple hv_SamplePY = new HTuple(),
                hv_SamplePZ = new HTuple();
            HTuple hv_CamParam0 = new HTuple(),
                hv_CamPose0 = new HTuple();
            HTuple hv_HomMat3D0 = new HTuple(),
                hv_HomMat3D0Invert = new HTuple();
            HTuple hv_Qx = new HTuple(),
                hv_Qy = new HTuple(),
                hv_Qz = new HTuple();
            HTuple hv_ImageSampleRow = new HTuple(),
                hv_ImageSampleColumn = new HTuple();
            HTuple hv_MinSlice = new HTuple(),
                hv_MaxSlice = new HTuple();
            HTuple hv_DilWidth = new HTuple(),
                hv_Cam = new HTuple();
            HTuple hv_CamParam = new HTuple(),
                hv_ImageWidth = new HTuple();
            HTuple hv_ImageHeight = new HTuple(),
                hv_CamPose = new HTuple();
            HTuple hv_HomMat3D = new HTuple(),
                hv_HomMat3DInvert = new HTuple();
            HTuple hv_Rows = new HTuple(),
                hv_Columns = new HTuple();
            HTuple hv_LinCoord = new HTuple(),
                hv_ImageRow = new HTuple();
            HTuple hv_ImageColumn = new HTuple(),
                hv_Mask = new HTuple();
            HTuple hv_ImageRowSub = new HTuple(),
                hv_ImageColumnSub = new HTuple();
            HTuple hv_ClosingRad = new HTuple(),
                hv_Number = new HTuple();
            HTuple hv_Message = new HTuple(),
                hv_MessageWrapped = new HTuple();
            HTuple hv_Grayval = new HTuple(),
                hv_RowBB1 = new HTuple();
            HTuple hv_ColumnBB1 = new HTuple(),
                hv_RowBB2 = new HTuple();
            HTuple hv_ColumnBB2 = new HTuple(),
                hv_From = new HTuple();
            HTuple hv_To = new HTuple(),
                hv_ShiftAccumulated = new HTuple();
            HTuple hv_HomMat2DAccumulated = new HTuple(),
                hv_MaximaS = new HTuple();
            HTuple hv_Maxima = new HTuple(),
                hv_FT = new HTuple();
            HTuple hv_F = new HTuple(),
                hv_T = new HTuple(),
                hv_RowInters1 = new HTuple();
            HTuple hv_ColumnInters1 = new HTuple(),
                hv_RowInters2 = new HTuple();
            HTuple hv_ColumnInters2 = new HTuple(),
                hv_ColumnCut = new HTuple();
            HTuple hv_VisualizeMorphing = new HTuple(),
                hv_Angles = new HTuple();
            HTuple hv_PaddingTopBottom = new HTuple(),
                hv_ModelID = new HTuple();
            HTuple hv_Values = new HTuple(),
                hv_Row = new HTuple();
            HTuple hv_Column = new HTuple(),
                hv_Angle = new HTuple();
            HTuple hv_Score = new HTuple(),
                hv_HomMat2DI = new HTuple();
            HTuple hv_HomMat2DITrans = new HTuple(),
                hv_HomMat2DITransInvert = new HTuple();
            HTuple hv_HomMat2DRemainder = new HTuple(),
                hv_RowOrig = new HTuple();
            HTuple hv_ColOrig = new HTuple(),
                hv_RowTrans = new HTuple();
            HTuple hv_ColTrans = new HTuple(),
                hv_DRow = new HTuple();
            HTuple hv_DCol = new HTuple(),
                hv_RegionWidth = new HTuple();
            HTuple hv_MorphingWidth = new HTuple(),
                hv_MorphingExtLeft = new HTuple();
            HTuple hv_MorphingWidth2 = new HTuple(),
                hv_MorphingWidth2ExtLeft = new HTuple();
            HTuple hv_RowsWI = new HTuple(),
                hv_ColumnsWI = new HTuple();
            HTuple hv_Ramp = new HTuple(),
                hv_MorphR = new HTuple();
            HTuple hv_MorphC = new HTuple(),
                hv_RW = new HTuple();
            HTuple hv_MosaicWidthExt = new HTuple(),
                hv_MosaicHeightExt = new HTuple();
            HTuple hv_NumberUI = new HTuple(),
                hv_ColumnBlendingCenter = new HTuple();
            HTuple hv_NumberUnrolledImages = new HTuple(),
                hv_I = new HTuple();
            HTuple hv_RowI1 = new HTuple(),
                hv_ColumnI1 = new HTuple();
            HTuple hv_RowI2 = new HTuple(),
                hv_ColumnI2 = new HTuple();
            HTuple hv_Dummy = new HTuple(),
                hv_RightBorder = new HTuple();
            HTuple hv_BSEven = new HTuple(),
                hv_BS2 = new HTuple();
            HTuple hv_BSStep = new HTuple(),
                hv_BSLeft = new HTuple();
            HTuple hv_BSRight = new HTuple(),
                hv_MaskOneLine = new HTuple();
            HTuple hv_CylinderPointsX_COPY_INP_TMP = new HTuple(hv_CylinderPointsX);
            HTuple hv_CylinderPointsY_COPY_INP_TMP = new HTuple(hv_CylinderPointsY);
            HTuple hv_CylinderPointsZ_COPY_INP_TMP = new HTuple(hv_CylinderPointsZ);
            HTuple hv_MosaicHeight_COPY_INP_TMP = new HTuple(hv_MosaicHeight);
            HTuple hv_WindowHandle_COPY_INP_TMP = new HTuple(hv_WindowHandle);

            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_FinalMosaic);
            HOperatorSet.GenEmptyObj(out ho_RegionsDilation);
            HOperatorSet.GenEmptyObj(out ho_UnrolledImages);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolled);
            HOperatorSet.GenEmptyObj(out ho_Region);
            HOperatorSet.GenEmptyObj(out ho_RegionTrans);
            HOperatorSet.GenEmptyObj(out ho_ConnectedRegions);
            HOperatorSet.GenEmptyObj(out ho_Image);
            HOperatorSet.GenEmptyObj(out ho_ImageReduced);
            HOperatorSet.GenEmptyObj(out ho_ImageScaled);
            HOperatorSet.GenEmptyObj(out ho_ImageDisp);
            HOperatorSet.GenEmptyObj(out ho_ImageGray);
            HOperatorSet.GenEmptyObj(out ho_RegionMaskOut);
            HOperatorSet.GenEmptyObj(out ho_RegionDifference);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolledDisp);
            HOperatorSet.GenEmptyObj(out ho_UnrolledImagesShifted);
            HOperatorSet.GenEmptyObj(out ho_RegionFrom);
            HOperatorSet.GenEmptyObj(out ho_ImageFrom);
            HOperatorSet.GenEmptyObj(out ho_SortedRegions);
            HOperatorSet.GenEmptyObj(out ho_ObjectSelected);
            HOperatorSet.GenEmptyObj(out ho_ImageFromReduced);
            HOperatorSet.GenEmptyObj(out ho_OverlappingAreas);
            HOperatorSet.GenEmptyObj(out ho_RegionTo);
            HOperatorSet.GenEmptyObj(out ho_ImageTo);
            HOperatorSet.GenEmptyObj(out ho_Domain);
            HOperatorSet.GenEmptyObj(out ho_RegionBlack);
            HOperatorSet.GenEmptyObj(out ho_RegionIntersection);
            HOperatorSet.GenEmptyObj(out ho_Rectangle);
            HOperatorSet.GenEmptyObj(out ho_ImageFromB);
            HOperatorSet.GenEmptyObj(out ho_ImageModel);
            HOperatorSet.GenEmptyObj(out ho_RoiSearch);
            HOperatorSet.GenEmptyObj(out ho_ImageToB);
            HOperatorSet.GenEmptyObj(out ho_ImageSearch);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImageLocal);
            HOperatorSet.GenEmptyObj(out ho_ImageWR);
            HOperatorSet.GenEmptyObj(out ho_ImageWC);
            HOperatorSet.GenEmptyObj(out ho_VectorField);
            HOperatorSet.GenEmptyObj(out ho_ImagePart);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped);
            HOperatorSet.GenEmptyObj(out ho_ObjectsConcat);
            HOperatorSet.GenEmptyObj(out ho_MorphedImage);
            HOperatorSet.GenEmptyObj(out ho_ImageToBShiftLocal);
            HOperatorSet.GenEmptyObj(out ho_ImageToShift);
            HOperatorSet.GenEmptyObj(out ho_RegionToShift);
            HOperatorSet.GenEmptyObj(out ho_ImageToShiftReduced);
            HOperatorSet.GenEmptyObj(out ho_RegionIntersection1);
            HOperatorSet.GenEmptyObj(out ho_ImageLeft);
            HOperatorSet.GenEmptyObj(out ho_ImageRight);
            HOperatorSet.GenEmptyObj(out ho_GrayImageLeft);
            HOperatorSet.GenEmptyObj(out ho_GrayImageRight);
            HOperatorSet.GenEmptyObj(out ho_GrayImageLeftB);
            HOperatorSet.GenEmptyObj(out ho_GrayImageRightB);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImage1);
            HOperatorSet.GenEmptyObj(out ho_I1);
            HOperatorSet.GenEmptyObj(out ho_I2);
            HOperatorSet.GenEmptyObj(out ho_D1);
            HOperatorSet.GenEmptyObj(out ho_D2);
            HOperatorSet.GenEmptyObj(out ho_BlendingMasks);
            HOperatorSet.GenEmptyObj(out ho_ImageM1);
            HOperatorSet.GenEmptyObj(out ho_ImageM);
            HOperatorSet.GenEmptyObj(out ho_ImageMosaic);
            HOperatorSet.GenEmptyObj(out ho_ImageTest);
            HOperatorSet.GenEmptyObj(out ho_Img);
            HOperatorSet.GenEmptyObj(out ho_ImgExt);
            HOperatorSet.GenEmptyObj(out ho_ImgReal);
            HOperatorSet.GenEmptyObj(out ho_Mas);
            HOperatorSet.GenEmptyObj(out ho_ImageForStitching);
            try
            {
                //global tuple DisplayIntermediateResults
                //global tuple WindowWidthLimit
                //global tuple WindowHeightLimit

                //Determine the part of the cylinder that must be used according to the
                //given area of the label in the first image
                hv_Indices.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Indices = new HTuple();
                    hv_Indices[0] = 0;
                    hv_Indices = hv_Indices.TupleConcat(
                        (HTuple.TupleGenConst(hv_NumSlices - 1, hv_NumPointsPerSlice)).TupleCumul()
                    );
                }
                hv_SamplePX.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SamplePX = hv_CylinderPointsX_COPY_INP_TMP.TupleSelect(hv_Indices);
                }
                hv_SamplePY.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SamplePY = hv_CylinderPointsY_COPY_INP_TMP.TupleSelect(hv_Indices);
                }
                hv_SamplePZ.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SamplePZ = hv_CylinderPointsZ_COPY_INP_TMP.TupleSelect(hv_Indices);
                }
                hv_CamParam0.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    0,
                    "params",
                    out hv_CamParam0
                );
                hv_CamPose0.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    0,
                    "pose",
                    out hv_CamPose0
                );
                hv_HomMat3D0.Dispose();
                HOperatorSet.PoseToHomMat3d(hv_CamPose0, out hv_HomMat3D0);
                hv_HomMat3D0Invert.Dispose();
                HOperatorSet.HomMat3dInvert(hv_HomMat3D0, out hv_HomMat3D0Invert);
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                HOperatorSet.AffineTransPoint3d(
                    hv_HomMat3D0Invert,
                    hv_SamplePX,
                    hv_SamplePY,
                    hv_SamplePZ,
                    out hv_Qx,
                    out hv_Qy,
                    out hv_Qz
                );
                hv_ImageSampleRow.Dispose();
                hv_ImageSampleColumn.Dispose();
                HOperatorSet.Project3dPoint(
                    hv_Qx,
                    hv_Qy,
                    hv_Qz,
                    hv_CamParam0,
                    out hv_ImageSampleRow,
                    out hv_ImageSampleColumn
                );
                if (
                    (int)(
                        new HTuple(
                            ((hv_ImageSampleRow.TupleFirstN(1))).TupleLess(
                                hv_ImageSampleRow.TupleLastN(1)
                            )
                        )
                    ) != 0
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_ImageSampleRow = hv_ImageSampleRow.TupleInverse();
                            hv_ImageSampleRow.Dispose();
                            hv_ImageSampleRow = ExpTmpLocalVar_ImageSampleRow;
                        }
                    }
                }
                hv_MinSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MinSlice = (
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (((hv_ImageSampleRow - hv_LabelMaxRow)).TupleSgn())
                                            ).TupleFindLast(1)
                                        )
                                    ).TupleSelect(0)
                                )
                            ).TupleConcat(0)
                        )
                    ).TupleMax();
                }
                hv_MaxSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MaxSlice = (
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (((hv_ImageSampleRow - hv_LabelMinRow)).TupleSgn())
                                            ).TupleFindLast(1)
                                        )
                                    ).TupleSelect(0)
                                )
                            ).TupleConcat(hv_NumSlices - 1)
                        )
                    ).TupleMin();
                }

                hv_MosaicHeight_COPY_INP_TMP.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MosaicHeight_COPY_INP_TMP = (hv_MaxSlice - hv_MinSlice) + 1;
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_CylinderPointsX =
                            hv_CylinderPointsX_COPY_INP_TMP.TupleSelectRange(
                                hv_MinSlice * hv_NumPointsPerSlice,
                                ((hv_MaxSlice * hv_NumPointsPerSlice) + hv_NumPointsPerSlice) - 1
                            );
                        hv_CylinderPointsX_COPY_INP_TMP.Dispose();
                        hv_CylinderPointsX_COPY_INP_TMP = ExpTmpLocalVar_CylinderPointsX;
                    }
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_CylinderPointsY =
                            hv_CylinderPointsY_COPY_INP_TMP.TupleSelectRange(
                                hv_MinSlice * hv_NumPointsPerSlice,
                                ((hv_MaxSlice * hv_NumPointsPerSlice) + hv_NumPointsPerSlice) - 1
                            );
                        hv_CylinderPointsY_COPY_INP_TMP.Dispose();
                        hv_CylinderPointsY_COPY_INP_TMP = ExpTmpLocalVar_CylinderPointsY;
                    }
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_CylinderPointsZ =
                            hv_CylinderPointsZ_COPY_INP_TMP.TupleSelectRange(
                                hv_MinSlice * hv_NumPointsPerSlice,
                                ((hv_MaxSlice * hv_NumPointsPerSlice) + hv_NumPointsPerSlice) - 1
                            );
                        hv_CylinderPointsZ_COPY_INP_TMP.Dispose();
                        hv_CylinderPointsZ_COPY_INP_TMP = ExpTmpLocalVar_CylinderPointsZ;
                    }
                }

                //Extend the regions such that they overlap each other to allow
                //some matching for the fine adjustment
                hv_DilWidth.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_DilWidth =
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (
                                                    hv_FineAdjustmentMatchingWidth
                                                    + (2 * hv_FineAdjustmentMaxShift)
                                                )
                                            ).TupleConcat(
                                                hv_BlendingSeam + hv_FineAdjustmentMaxShift
                                            )
                                        )
                                    ).TupleMax()
                                ) / 2
                            ) * 2
                        ) + 1;
                }
                ho_RegionsDilation.Dispose();
                HOperatorSet.DilationRectangle1(ho_Regions, out ho_RegionsDilation, hv_DilWidth, 1);
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    HObject ExpTmpOutVar_0;
                    HOperatorSet.ClipRegion(
                        ho_RegionsDilation,
                        out ExpTmpOutVar_0,
                        0,
                        0,
                        hv_MosaicHeight_COPY_INP_TMP - 1,
                        hv_MosaicWidth - 1
                    );
                    ho_RegionsDilation.Dispose();
                    ho_RegionsDilation = ExpTmpOutVar_0;
                }

                //Unrole the images from the individual cameras such that they overlap each other
                ho_UnrolledImages.Dispose();
                HOperatorSet.GenEmptyObj(out ho_UnrolledImages);
                HTuple end_val35 = hv_NumCameras - 1;
                HTuple step_val35 = 1;
                for (
                    hv_Cam = 0;
                    hv_Cam.Continue(end_val35, step_val35);
                    hv_Cam = hv_Cam.TupleAdd(step_val35)
                )
                {
                    ho_ImageUnrolled.Dispose();
                    HOperatorSet.GenImageConst(
                        out ho_ImageUnrolled,
                        "byte",
                        hv_MosaicWidth,
                        hv_MosaicHeight_COPY_INP_TMP
                    );
                    hv_CamParam.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDistInCylinderOrigin,
                        hv_Cam,
                        "params",
                        out hv_CamParam
                    );
                    hv_ImageWidth.Dispose();
                    get_cam_par_data(hv_CamParam, "image_width", out hv_ImageWidth);
                    hv_ImageHeight.Dispose();
                    get_cam_par_data(hv_CamParam, "image_height", out hv_ImageHeight);
                    hv_CamPose.Dispose();
                    HOperatorSet.GetCameraSetupParam(
                        hv_CameraSetupModelZeroDistInCylinderOrigin,
                        hv_Cam,
                        "pose",
                        out hv_CamPose
                    );
                    hv_HomMat3D.Dispose();
                    HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                    hv_HomMat3DInvert.Dispose();
                    HOperatorSet.HomMat3dInvert(hv_HomMat3D, out hv_HomMat3DInvert);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_Region.Dispose();
                        HOperatorSet.SelectObj(ho_RegionsDilation, out ho_Region, hv_Cam + 1);
                    }
                    hv_Rows.Dispose();
                    hv_Columns.Dispose();
                    HOperatorSet.GetRegionPoints(ho_Region, out hv_Rows, out hv_Columns);
                    hv_LinCoord.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_LinCoord = (hv_Rows * hv_NumPointsPerSlice) + hv_Columns;
                    }

                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Qx.Dispose();
                        hv_Qy.Dispose();
                        hv_Qz.Dispose();
                        HOperatorSet.AffineTransPoint3d(
                            hv_HomMat3DInvert,
                            hv_CylinderPointsX_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                            hv_CylinderPointsY_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                            hv_CylinderPointsZ_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                            out hv_Qx,
                            out hv_Qy,
                            out hv_Qz
                        );
                    }
                    hv_ImageRow.Dispose();
                    hv_ImageColumn.Dispose();
                    HOperatorSet.Project3dPoint(
                        hv_Qx,
                        hv_Qy,
                        hv_Qz,
                        hv_CamParam,
                        out hv_ImageRow,
                        out hv_ImageColumn
                    );

                    hv_Mask.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Mask = (
                            new HTuple(
                                (
                                    new HTuple(
                                        ((hv_ImageRow.TupleGreaterEqualElem(0))).TupleAnd(
                                            hv_ImageRow.TupleLessEqualElem(hv_ImageHeight - 1)
                                        )
                                    )
                                ).TupleAnd(hv_ImageColumn.TupleGreaterEqualElem(0))
                            )
                        ).TupleAnd(hv_ImageColumn.TupleLessEqualElem(hv_ImageWidth - 1));
                    }
                    hv_ImageRowSub.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_ImageRowSub = hv_ImageRow.TupleSelectMask(hv_Mask);
                    }
                    hv_ImageColumnSub.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_ImageColumnSub = hv_ImageColumn.TupleSelectMask(hv_Mask);
                    }

                    if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                    {
                        ho_Region.Dispose();
                        HOperatorSet.GenRegionPoints(
                            out ho_Region,
                            hv_ImageRowSub,
                            hv_ImageColumnSub
                        );
                        for (
                            hv_ClosingRad = 1.5;
                            (double)hv_ClosingRad <= 15.5;
                            hv_ClosingRad = (double)hv_ClosingRad + 1
                        )
                        {
                            ho_RegionTrans.Dispose();
                            HOperatorSet.ClosingCircle(
                                ho_Region,
                                out ho_RegionTrans,
                                hv_ClosingRad
                            );
                            ho_ConnectedRegions.Dispose();
                            HOperatorSet.Connection(ho_RegionTrans, out ho_ConnectedRegions);
                            hv_Number.Dispose();
                            HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                            if ((int)(new HTuple(hv_Number.TupleEqual(1))) != 0)
                            {
                                {
                                    HObject ExpTmpOutVar_0;
                                    HOperatorSet.FillUp(ho_RegionTrans, out ExpTmpOutVar_0);
                                    ho_RegionTrans.Dispose();
                                    ho_RegionTrans = ExpTmpOutVar_0;
                                }
                                break;
                            }
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_Image.Dispose();
                            HOperatorSet.SelectObj(ho_ImagesRectified, out ho_Image, hv_Cam + 1);
                        }
                        ho_ImageReduced.Dispose();
                        HOperatorSet.ReduceDomain(ho_Image, ho_RegionTrans, out ho_ImageReduced);
                        ho_ImageScaled.Dispose();
                        HOperatorSet.ScaleImage(ho_ImageReduced, out ho_ImageScaled, 0.25, 150);
                        ho_ImageDisp.Dispose();
                        HOperatorSet.CopyImage(ho_Image, out ho_ImageDisp);
                        HOperatorSet.OverpaintGray(ho_ImageDisp, ho_ImageScaled);
                        if (HDevWindowStack.IsOpen())
                        {
                            hv_WindowHandle_COPY_INP_TMP = HDevWindowStack.GetActive();
                        }
                        dev_resize_window_fit_image(
                            ho_ImageDisp,
                            0,
                            0,
                            ExpGetGlobalVar_WindowWidthLimit(),
                            ExpGetGlobalVar_WindowHeightLimit()
                        );
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.DispObj(ho_ImageDisp, HDevWindowStack.GetActive());
                        }
                        hv_Message.Dispose();
                        hv_Message = "Image part that will be unrolled";
                        hv_MessageWrapped.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MessageWrapped = ((hv_Message + " ")).TupleRegexpReplace(
                                (new HTuple("(.{0,40})\\s")).TupleConcat("replace_all"),
                                "$1\n"
                            );
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            disp_message(
                                hv_WindowHandle_COPY_INP_TMP,
                                ((("Camera " + (hv_Cam + 1)) + ":")).TupleConcat(hv_MessageWrapped),
                                "window",
                                12,
                                12,
                                "black",
                                "true"
                            );
                        }
                        // stop(...); only in hdevelop
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageGray.Dispose();
                        HOperatorSet.SelectObj(ho_ImagesRectified, out ho_ImageGray, hv_Cam + 1);
                    }
                    hv_Grayval.Dispose();
                    HOperatorSet.GetGrayvalInterpolated(
                        ho_ImageGray,
                        hv_ImageRowSub,
                        hv_ImageColumnSub,
                        "bilinear",
                        out hv_Grayval
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        HOperatorSet.SetGrayval(
                            ho_ImageUnrolled,
                            hv_Rows.TupleSelectMask(hv_Mask),
                            hv_Columns.TupleSelectMask(hv_Mask),
                            hv_Grayval
                        );
                    }
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConcatObj(
                            ho_UnrolledImages,
                            ho_ImageUnrolled,
                            out ExpTmpOutVar_0
                        );
                        ho_UnrolledImages.Dispose();
                        ho_UnrolledImages = ExpTmpOutVar_0;
                    }
                    if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                    {
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_RegionMaskOut.Dispose();
                            HOperatorSet.GenRegionPoints(
                                out ho_RegionMaskOut,
                                hv_Rows.TupleSelectMask(hv_Mask),
                                hv_Columns.TupleSelectMask(hv_Mask)
                            );
                        }
                        ho_RegionDifference.Dispose();
                        HOperatorSet.Difference(
                            ho_ImageUnrolled,
                            ho_RegionMaskOut,
                            out ho_RegionDifference
                        );
                        ho_ImageUnrolledDisp.Dispose();
                        HOperatorSet.CopyImage(ho_ImageUnrolled, out ho_ImageUnrolledDisp);
                        HOperatorSet.OverpaintRegion(
                            ho_ImageUnrolledDisp,
                            ho_RegionDifference,
                            255,
                            "fill"
                        );
                        dev_resize_window_fit_image(
                            ho_ImageUnrolledDisp,
                            0,
                            0,
                            ExpGetGlobalVar_WindowWidthLimit(),
                            ExpGetGlobalVar_WindowHeightLimit()
                        );
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.DispObj(ho_ImageUnrolledDisp, HDevWindowStack.GetActive());
                        }
                        hv_Message.Dispose();
                        hv_Message = "Unrolled image";
                        hv_MessageWrapped.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MessageWrapped = ((hv_Message + " ")).TupleRegexpReplace(
                                (new HTuple("(.{0,40})\\s")).TupleConcat("replace_all"),
                                "$1\n"
                            );
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            disp_message(
                                hv_WindowHandle_COPY_INP_TMP,
                                ((("Camera " + (hv_Cam + 1)) + ":")).TupleConcat(hv_MessageWrapped),
                                "window",
                                12,
                                12,
                                "black",
                                "true"
                            );
                        }
                        // stop(...); only in hdevelop
                    }
                }

                //Determine the images that overlap each other
                hv_RowBB1.Dispose();
                hv_ColumnBB1.Dispose();
                hv_RowBB2.Dispose();
                hv_ColumnBB2.Dispose();
                HOperatorSet.SmallestRectangle1(
                    ho_RegionsDilation,
                    out hv_RowBB1,
                    out hv_ColumnBB1,
                    out hv_RowBB2,
                    out hv_ColumnBB2
                );
                hv_From.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_From = hv_ColumnBB1.TupleSortIndex();
                }
                hv_To.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_To = new HTuple();
                    hv_To = hv_To.TupleConcat(
                        hv_From.TupleSelectRange(1, (new HTuple(hv_From.TupleLength())) - 1)
                    );
                    hv_To = hv_To.TupleConcat(hv_From.TupleSelect(0));
                }
                //From := [0,1,2,3]
                //To := [1,2,3,0]

                //Determine the shift between the unrolled images
                ho_UnrolledImagesShifted.Dispose();
                HOperatorSet.GenEmptyObj(out ho_UnrolledImagesShifted);

                //Copy left part of first unrolled image because it can remain unshifted
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_RegionFrom.Dispose();
                    HOperatorSet.SelectObj(
                        ho_RegionsDilation,
                        out ho_RegionFrom,
                        (hv_From.TupleSelect(0)) + 1
                    );
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    ho_ImageFrom.Dispose();
                    HOperatorSet.SelectObj(
                        ho_UnrolledImages,
                        out ho_ImageFrom,
                        (hv_From.TupleSelect(0)) + 1
                    );
                }
                {
                    HObject ExpTmpOutVar_0;
                    HOperatorSet.CopyImage(ho_ImageFrom, out ExpTmpOutVar_0);
                    ho_ImageFrom.Dispose();
                    ho_ImageFrom = ExpTmpOutVar_0;
                }
                ho_ConnectedRegions.Dispose();
                HOperatorSet.Connection(ho_RegionFrom, out ho_ConnectedRegions);
                ho_SortedRegions.Dispose();
                HOperatorSet.SortRegion(
                    ho_ConnectedRegions,
                    out ho_SortedRegions,
                    "character",
                    "true",
                    "column"
                );
                ho_ObjectSelected.Dispose();
                HOperatorSet.SelectObj(ho_SortedRegions, out ho_ObjectSelected, 1);
                ho_ImageFromReduced.Dispose();
                HOperatorSet.ReduceDomain(ho_ImageFrom, ho_ObjectSelected, out ho_ImageFromReduced);
                {
                    HObject ExpTmpOutVar_0;
                    HOperatorSet.ConcatObj(
                        ho_UnrolledImagesShifted,
                        ho_ImageFromReduced,
                        out ExpTmpOutVar_0
                    );
                    ho_UnrolledImagesShifted.Dispose();
                    ho_UnrolledImagesShifted = ExpTmpOutVar_0;
                }
                //
                hv_ShiftAccumulated.Dispose();
                hv_ShiftAccumulated = 0;
                hv_HomMat2DAccumulated.Dispose();
                HOperatorSet.HomMat2dIdentity(out hv_HomMat2DAccumulated);

                //Determine the shift for the mosaicking
                ho_OverlappingAreas.Dispose();
                HOperatorSet.GenEmptyObj(out ho_OverlappingAreas);
                hv_MaximaS.Dispose();
                hv_MaximaS = new HTuple();
                hv_Maxima.Dispose();
                hv_Maxima = new HTuple();
                for (
                    hv_FT = 0;
                    (int)hv_FT <= (int)((new HTuple(hv_From.TupleLength())) - 1);
                    hv_FT = (int)hv_FT + 1
                )
                {
                    hv_F.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_F = hv_From.TupleSelect(hv_FT);
                    }
                    hv_T.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_T = hv_To.TupleSelect(hv_FT);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_RegionFrom.Dispose();
                        HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionFrom, hv_F + 1);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_RegionTo.Dispose();
                        HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionTo, hv_T + 1);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageFrom.Dispose();
                        HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageFrom, hv_F + 1);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageTo.Dispose();
                        HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageTo, hv_T + 1);
                    }
                    if (
                        (int)(new HTuple(hv_FT.TupleEqual((new HTuple(hv_From.TupleLength())) - 1)))
                        != 0
                    )
                    {
                        //Add only right part of last image
                        ho_ConnectedRegions.Dispose();
                        HOperatorSet.Connection(ho_RegionTo, out ho_ConnectedRegions);
                        hv_Number.Dispose();
                        HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                        if ((int)(new HTuple(hv_Number.TupleGreater(1))) != 0)
                        {
                            ho_SortedRegions.Dispose();
                            HOperatorSet.SortRegion(
                                ho_ConnectedRegions,
                                out ho_SortedRegions,
                                "character",
                                "true",
                                "column"
                            );
                            ho_RegionTo.Dispose();
                            HOperatorSet.SelectObj(ho_SortedRegions, out ho_RegionTo, 2);
                            ho_Domain.Dispose();
                            HOperatorSet.GetDomain(ho_ImageTo, out ho_Domain);
                            ho_RegionBlack.Dispose();
                            HOperatorSet.Difference(ho_Domain, ho_RegionTo, out ho_RegionBlack);
                            HOperatorSet.OverpaintRegion(
                                ho_ImageTo,
                                ho_RegionBlack,
                                ((new HTuple(0)).TupleConcat(0)).TupleConcat(0),
                                "fill"
                            );
                        }
                    }
                    //Select the kind of image used for matching
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConvertImageType(ho_ImageFrom, out ExpTmpOutVar_0, "real");
                        ho_ImageFrom.Dispose();
                        ho_ImageFrom = ExpTmpOutVar_0;
                    }
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConvertImageType(ho_ImageTo, out ExpTmpOutVar_0, "real");
                        ho_ImageTo.Dispose();
                        ho_ImageTo = ExpTmpOutVar_0;
                    }
                    ho_RegionIntersection.Dispose();
                    HOperatorSet.Intersection(
                        ho_RegionFrom,
                        ho_RegionTo,
                        out ho_RegionIntersection
                    );
                    hv_RowInters1.Dispose();
                    hv_ColumnInters1.Dispose();
                    hv_RowInters2.Dispose();
                    hv_ColumnInters2.Dispose();
                    HOperatorSet.SmallestRectangle1(
                        ho_RegionIntersection,
                        out hv_RowInters1,
                        out hv_ColumnInters1,
                        out hv_RowInters2,
                        out hv_ColumnInters2
                    );
                    hv_ColumnCut.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_ColumnCut = (hv_ColumnInters1 + hv_ColumnInters2) / 2;
                    }
                    hv_VisualizeMorphing.Dispose();
                    hv_VisualizeMorphing = 0;
                    //Create Ncc model
                    hv_Angles.Dispose();
                    hv_Angles = new HTuple();
                    hv_Angles[0] = -3;
                    hv_Angles[1] = 3;
                    hv_PaddingTopBottom.Dispose();
                    hv_PaddingTopBottom = 0;
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_Rectangle.Dispose();
                        HOperatorSet.GenRectangle1(
                            out ho_Rectangle,
                            hv_PaddingTopBottom,
                            hv_ColumnCut - (hv_FineAdjustmentMatchingWidth / 2),
                            (hv_MosaicHeight_COPY_INP_TMP - 1) - hv_PaddingTopBottom,
                            hv_ColumnCut + (hv_FineAdjustmentMatchingWidth / 2)
                        );
                    }
                    ho_ImageFromB.Dispose();
                    HOperatorSet.ConvertImageType(ho_ImageFrom, out ho_ImageFromB, "byte");
                    ho_ImageModel.Dispose();
                    HOperatorSet.ReduceDomain(ho_ImageFromB, ho_Rectangle, out ho_ImageModel);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_ModelID.Dispose();
                        HOperatorSet.CreateNccModel(
                            ho_ImageModel,
                            1,
                            ((hv_Angles.TupleSelect(0))).TupleRad(),
                            (((hv_Angles.TupleSelect(1)) - (hv_Angles.TupleSelect(0)))).TupleRad(),
                            "auto",
                            "use_polarity",
                            out hv_ModelID
                        );
                    }
                    hv_Values.Dispose();
                    HOperatorSet.RegionFeatures(
                        ho_ImageModel,
                        ((new HTuple("row")).TupleConcat("column")).TupleConcat("width"),
                        out hv_Values
                    );

                    //Create the search image
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_RoiSearch.Dispose();
                        HOperatorSet.GenRectangle2(
                            out ho_RoiSearch,
                            hv_Values.TupleSelect(0),
                            hv_Values.TupleSelect(1),
                            0,
                            hv_FineAdjustmentMaxShift,
                            hv_NumSlices / 4
                        );
                    }
                    ho_ImageToB.Dispose();
                    HOperatorSet.ConvertImageType(ho_ImageTo, out ho_ImageToB, "byte");
                    ho_ImageSearch.Dispose();
                    HOperatorSet.ReduceDomain(ho_ImageToB, ho_RoiSearch, out ho_ImageSearch);

                    if ((int)(hv_VisualizeMorphing) != 0)
                    {
                        ho_MultiChannelImageLocal.Dispose();
                        HOperatorSet.Compose3(
                            ho_ImageFromB,
                            ho_ImageFromB,
                            ho_ImageToB,
                            out ho_MultiChannelImageLocal
                        );
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                        }
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.DispObj(
                                ho_MultiChannelImageLocal,
                                HDevWindowStack.GetActive()
                            );
                        }
                        // stop(...); only in hdevelop
                    }

                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Row.Dispose();
                        hv_Column.Dispose();
                        hv_Angle.Dispose();
                        hv_Score.Dispose();
                        HOperatorSet.FindNccModel(
                            ho_ImageSearch,
                            hv_ModelID,
                            ((hv_Angles.TupleSelect(0))).TupleRad(),
                            (((hv_Angles.TupleSelect(1)) - (hv_Angles.TupleSelect(0)))).TupleRad(),
                            0.3,
                            1,
                            1.0,
                            "true",
                            0,
                            out hv_Row,
                            out hv_Column,
                            out hv_Angle,
                            out hv_Score
                        );
                    }
                    if ((int)(new HTuple((new HTuple(hv_Score.TupleLength())).TupleEqual(0))) != 0)
                    {
                        hv_Row.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Row = hv_Values.TupleSelect(0);
                        }
                        hv_Column.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Column = hv_Values.TupleSelect(1);
                        }
                        hv_Angle.Dispose();
                        hv_Angle = 0;
                        hv_Score.Dispose();
                        hv_Score = 0;
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageTo.Dispose();
                        HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageTo, hv_T + 1);
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_ShiftAccumulated =
                                hv_ShiftAccumulated + ((hv_Values.TupleSelect(1)) - hv_Column);
                            hv_ShiftAccumulated.Dispose();
                            hv_ShiftAccumulated = ExpTmpLocalVar_ShiftAccumulated;
                        }
                    }

                    //The transformation to move the search image onto the model image
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_HomMat2DI.Dispose();
                        HOperatorSet.VectorAngleToRigid(
                            hv_Row,
                            hv_Column,
                            hv_Angle,
                            hv_Values.TupleSelect(0),
                            hv_Values.TupleSelect(1),
                            0,
                            out hv_HomMat2DI
                        );
                    }

                    //Split the transformation into a translation part in column direction
                    //and the remainder
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_HomMat2DITrans.Dispose();
                        HOperatorSet.VectorAngleToRigid(
                            0,
                            hv_Column,
                            0,
                            0,
                            hv_Values.TupleSelect(1),
                            0,
                            out hv_HomMat2DITrans
                        );
                    }
                    hv_HomMat2DITransInvert.Dispose();
                    HOperatorSet.HomMat2dInvert(hv_HomMat2DITrans, out hv_HomMat2DITransInvert);
                    hv_HomMat2DRemainder.Dispose();
                    HOperatorSet.HomMat2dCompose(
                        hv_HomMat2DI,
                        hv_HomMat2DITransInvert,
                        out hv_HomMat2DRemainder
                    );

                    //Apply the remainder of the transformation in some kind of local morphing
                    //such that the right image fits the left image
                    hv_RowOrig.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_RowOrig = HTuple.TupleGenSequence(
                            0,
                            hv_MosaicHeight_COPY_INP_TMP - 1,
                            1
                        );
                    }
                    hv_ColOrig.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_ColOrig = HTuple.TupleGenConst(
                            hv_MosaicHeight_COPY_INP_TMP,
                            hv_ColumnCut
                        );
                    }
                    hv_RowTrans.Dispose();
                    hv_ColTrans.Dispose();
                    HOperatorSet.AffineTransPixel(
                        hv_HomMat2DRemainder,
                        hv_RowOrig,
                        hv_ColOrig,
                        out hv_RowTrans,
                        out hv_ColTrans
                    );
                    hv_DRow.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DRow = hv_RowOrig - hv_RowTrans;
                    }
                    hv_DCol.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DCol = hv_ColOrig - hv_ColTrans;
                    }

                    hv_RegionWidth.Dispose();
                    HOperatorSet.RegionFeatures(ho_Regions, "width", out hv_RegionWidth);
                    hv_MorphingWidth.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MorphingWidth = ((0.2 * (hv_RegionWidth.TupleMin()))).TupleInt();
                    }
                    hv_MorphingExtLeft.Dispose();
                    hv_MorphingExtLeft = 10;
                    hv_MorphingWidth2.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MorphingWidth2 = (2 * hv_MorphingWidth) + 1;
                    }
                    hv_MorphingWidth2ExtLeft.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MorphingWidth2ExtLeft = hv_MorphingWidth2 + hv_MorphingExtLeft;
                    }
                    ho_ImageWR.Dispose();
                    HOperatorSet.GenImageConst(
                        out ho_ImageWR,
                        "real",
                        hv_MorphingWidth2ExtLeft,
                        hv_MosaicHeight_COPY_INP_TMP
                    );
                    ho_ImageWC.Dispose();
                    HOperatorSet.GenImageConst(
                        out ho_ImageWC,
                        "real",
                        hv_MorphingWidth2ExtLeft,
                        hv_MosaicHeight_COPY_INP_TMP
                    );
                    hv_RowsWI.Dispose();
                    hv_ColumnsWI.Dispose();
                    HOperatorSet.GetRegionPoints(ho_ImageWR, out hv_RowsWI, out hv_ColumnsWI);
                    hv_Ramp.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_Ramp = new HTuple();
                        hv_Ramp = hv_Ramp.TupleConcat(
                            HTuple.TupleGenConst(hv_MorphingExtLeft, 2.0)
                        );
                        hv_Ramp = hv_Ramp.TupleConcat(
                            (
                                (
                                    (
                                        HTuple.TupleGenConst(
                                            hv_MorphingWidth2 - 1,
                                            2.0 / hv_MorphingWidth2
                                        )
                                    ).TupleCumul()
                                )
                            ).TupleInverse()
                        );
                        hv_Ramp = hv_Ramp.TupleConcat(0);
                    }
                    hv_MorphR.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MorphR = HTuple.TupleGenConst(new HTuple(hv_RowsWI.TupleLength()), 0);
                    }
                    hv_MorphC.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MorphC = HTuple.TupleGenConst(new HTuple(hv_RowsWI.TupleLength()), 0);
                    }
                    HTuple end_val208 = hv_MosaicHeight_COPY_INP_TMP - 1;
                    HTuple step_val208 = 1;
                    for (
                        hv_RW = 0;
                        hv_RW.Continue(end_val208, step_val208);
                        hv_RW = hv_RW.TupleAdd(step_val208)
                    )
                    {
                        if (hv_MorphR == null)
                            hv_MorphR = new HTuple();
                        hv_MorphR[
                            HTuple.TupleGenSequence(
                                hv_RW * hv_MorphingWidth2ExtLeft,
                                ((hv_RW * hv_MorphingWidth2ExtLeft) + hv_MorphingWidth2ExtLeft) - 1,
                                1
                            )
                        ] = hv_Ramp * (hv_DRow.TupleSelect(hv_RW));
                        if (hv_MorphC == null)
                            hv_MorphC = new HTuple();
                        hv_MorphC[
                            HTuple.TupleGenSequence(
                                hv_RW * hv_MorphingWidth2ExtLeft,
                                ((hv_RW * hv_MorphingWidth2ExtLeft) + hv_MorphingWidth2ExtLeft) - 1,
                                1
                            )
                        ] = hv_Ramp * (hv_DCol.TupleSelect(hv_RW));
                    }
                    HOperatorSet.SetGrayval(ho_ImageWR, hv_RowsWI, hv_ColumnsWI, hv_MorphR);
                    HOperatorSet.SetGrayval(ho_ImageWC, hv_RowsWI, hv_ColumnsWI, hv_MorphC);
                    ho_VectorField.Dispose();
                    HOperatorSet.RealToVectorField(
                        ho_ImageWR,
                        ho_ImageWC,
                        out ho_VectorField,
                        "vector_field_relative"
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImagePart.Dispose();
                        HOperatorSet.CropRectangle1(
                            ho_ImageTo,
                            out ho_ImagePart,
                            0,
                            (hv_ColumnCut - hv_MorphingWidth) - hv_MorphingExtLeft,
                            hv_MosaicHeight_COPY_INP_TMP - 1,
                            hv_ColumnCut + hv_MorphingWidth
                        );
                    }
                    ho_ImageUnwarped.Dispose();
                    HOperatorSet.UnwarpImageVectorField(
                        ho_ImagePart,
                        ho_VectorField,
                        out ho_ImageUnwarped
                    );
                    ho_ObjectsConcat.Dispose();
                    HOperatorSet.ConcatObj(ho_ImageToB, ho_ImageUnwarped, out ho_ObjectsConcat);
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_MorphedImage.Dispose();
                        HOperatorSet.TileImagesOffset(
                            ho_ObjectsConcat,
                            out ho_MorphedImage,
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(0)).TupleConcat(
                                (hv_ColumnCut - hv_MorphingWidth) - hv_MorphingExtLeft
                            ),
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(0)).TupleConcat(0),
                            (new HTuple(-1)).TupleConcat(-1),
                            (new HTuple(-1)).TupleConcat(-1),
                            hv_MosaicWidth,
                            hv_MosaicHeight_COPY_INP_TMP
                        );
                    }

                    if ((int)(hv_VisualizeMorphing) != 0)
                    {
                        ho_ImageToBShiftLocal.Dispose();
                        HOperatorSet.AffineTransImage(
                            ho_MorphedImage,
                            out ho_ImageToBShiftLocal,
                            hv_HomMat2DITrans,
                            "constant",
                            "false"
                        );
                        ho_MultiChannelImageLocal.Dispose();
                        HOperatorSet.Compose3(
                            ho_ImageFromB,
                            ho_ImageFromB,
                            ho_ImageToBShiftLocal,
                            out ho_MultiChannelImageLocal
                        );
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                        }
                        if (HDevWindowStack.IsOpen())
                        {
                            HOperatorSet.DispObj(
                                ho_MultiChannelImageLocal,
                                HDevWindowStack.GetActive()
                            );
                        }
                        // stop(...); only in hdevelop
                    }

                    {
                        HTuple ExpTmpOutVar_0;
                        HOperatorSet.HomMat2dCompose(
                            hv_HomMat2DAccumulated,
                            hv_HomMat2DITrans,
                            out ExpTmpOutVar_0
                        );
                        hv_HomMat2DAccumulated.Dispose();
                        hv_HomMat2DAccumulated = ExpTmpOutVar_0;
                    }
                    if (
                        (int)(new HTuple(hv_FT.TupleLess((new HTuple(hv_From.TupleLength())) - 1)))
                        != 0
                    )
                    {
                        ho_ImageToShift.Dispose();
                        HOperatorSet.AffineTransImage(
                            ho_MorphedImage,
                            out ho_ImageToShift,
                            hv_HomMat2DAccumulated,
                            "constant",
                            "false"
                        );
                        ho_RegionToShift.Dispose();
                        HOperatorSet.AffineTransRegion(
                            ho_RegionTo,
                            out ho_RegionToShift,
                            hv_HomMat2DAccumulated,
                            "nearest_neighbor"
                        );
                    }
                    else
                    {
                        //Because of the matching results, the final mosaic width may have changed
                        ho_ImageToShift.Dispose();
                        HOperatorSet.AffineTransImage(
                            ho_MorphedImage,
                            out ho_ImageToShift,
                            hv_HomMat2DAccumulated,
                            "constant",
                            "true"
                        );
                        ho_RegionToShift.Dispose();
                        HOperatorSet.AffineTransRegion(
                            ho_RegionTo,
                            out ho_RegionToShift,
                            hv_HomMat2DAccumulated,
                            "nearest_neighbor"
                        );
                        hv_MosaicWidthExt.Dispose();
                        hv_MosaicHeightExt.Dispose();
                        HOperatorSet.GetImageSize(
                            ho_ImageToShift,
                            out hv_MosaicWidthExt,
                            out hv_MosaicHeightExt
                        );
                    }

                    ho_ImageToShiftReduced.Dispose();
                    HOperatorSet.ReduceDomain(
                        ho_ImageToShift,
                        ho_RegionToShift,
                        out ho_ImageToShiftReduced
                    );
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ConcatObj(
                            ho_UnrolledImagesShifted,
                            ho_ImageToShiftReduced,
                            out ExpTmpOutVar_0
                        );
                        ho_UnrolledImagesShifted.Dispose();
                        ho_UnrolledImagesShifted = ExpTmpOutVar_0;
                    }
                    ho_RegionIntersection1.Dispose();
                    HOperatorSet.Intersection(
                        ho_RegionFrom,
                        ho_RegionToShift,
                        out ho_RegionIntersection1
                    );
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.Union2(
                            ho_OverlappingAreas,
                            ho_RegionIntersection1,
                            out ExpTmpOutVar_0
                        );
                        ho_OverlappingAreas.Dispose();
                        ho_OverlappingAreas = ExpTmpOutVar_0;
                    }

                    if ((int)(hv_VisualizeMorphing) != 0)
                    {
                        hv_NumberUI.Dispose();
                        HOperatorSet.CountObj(ho_UnrolledImagesShifted, out hv_NumberUI);
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_ImageLeft.Dispose();
                            HOperatorSet.SelectObj(
                                ho_UnrolledImagesShifted,
                                out ho_ImageLeft,
