                                    hv_ImageColumnSub,
                                    "bilinear",
                                    out hv_Grayval
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageUnrolled,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval
                                    );
                                }
                            }
                            else
                            {
                                hv_Grayval1.Dispose();
                                HOperatorSet.GetGrayval(
                                    ho_ImageGray,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    out hv_Grayval1
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageUnrolled,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval1
                                    );
                                }
                            }
                            {
                                HObject ExpTmpOutVar_0;
                                HOperatorSet.ConcatObj(
                                    ho_UnrolledImages,
                                    ho_ImageUnrolled,
                                    out ExpTmpOutVar_0
                                );
                                ho_UnrolledImages.Dispose();
                                ho_UnrolledImages = ExpTmpOutVar_0;
                            }
                        }

                        if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                        {
                            hv_NumberUnrolled.Dispose();
                            HOperatorSet.CountObj(ho_UnrolledImages, out hv_NumberUnrolled);
                            ho_UnrolledOut.Dispose();
                            HOperatorSet.SelectObj(
                                ho_UnrolledImages,
                                out ho_UnrolledOut,
                                hv_NumberUnrolled
                            );
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_RegionMaskOut.Dispose();
                                HOperatorSet.GenRegionPoints(
                                    out ho_RegionMaskOut,
                                    hv_Rows.TupleSelectMask(hv_Mask),
                                    hv_Columns.TupleSelectMask(hv_Mask)
                                );
                            }
                            ho_DomainUnrolledOut.Dispose();
                            HOperatorSet.GetDomain(ho_UnrolledOut, out ho_DomainUnrolledOut);
                            ho_RegionDifference.Dispose();
                            HOperatorSet.Difference(
                                ho_DomainUnrolledOut,
                                ho_RegionMaskOut,
                                out ho_RegionDifference
                            );
                            if ((int)(hv_ColorMosaic) != 0)
                            {
                                hv_FillColor.Dispose();
                                hv_FillColor = new HTuple();
                                hv_FillColor[0] = 255;
                                hv_FillColor[1] = 255;
                                hv_FillColor[2] = 255;
                            }
                            else
                            {
                                hv_FillColor.Dispose();
                                hv_FillColor = 255;
                            }
                            HOperatorSet.OverpaintRegion(
                                ho_UnrolledOut,
                                ho_RegionDifference,
                                hv_FillColor,
                                "fill"
                            );
                            dev_resize_window_fit_image(
                                ho_UnrolledOut,
                                0,
                                0,
                                ExpGetGlobalVar_WindowWidthLimit(),
                                ExpGetGlobalVar_WindowHeightLimit()
                            );
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.DispObj(ho_UnrolledOut, HDevWindowStack.GetActive());
                            }
                            hv_Message.Dispose();
                            hv_Message = "Unrolled image";
                            hv_MessageWrapped.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_MessageWrapped = ((hv_Message + " ")).TupleRegexpReplace(
                                    (new HTuple("(.{0,40})\\s")).TupleConcat("replace_all"),
                                    "$1\n"
                                );
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                disp_message(
                                    hv_WindowHandle_COPY_INP_TMP,
                                    ((("Camera " + (hv_Cam + 1)) + ":")).TupleConcat(
                                        hv_MessageWrapped
                                    ),
                                    "window",
                                    12,
                                    12,
                                    "black",
                                    "true"
                                );
                            }
                            // stop(...); only in hdevelop
                        }
                    }

                    //Determine the images that overlap each other
                    hv_RowBB1.Dispose();
                    hv_ColumnBB1.Dispose();
                    hv_RowBB2.Dispose();
                    hv_ColumnBB2.Dispose();
                    HOperatorSet.SmallestRectangle1(
                        ho_RegionsDilation,
                        out hv_RowBB1,
                        out hv_ColumnBB1,
                        out hv_RowBB2,
                        out hv_ColumnBB2
                    );
                    hv_From.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_From = hv_ColumnBB1.TupleSortIndex();
                    }
                    hv_To.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_To = new HTuple();
                        hv_To = hv_To.TupleConcat(
                            hv_From.TupleSelectRange(1, (new HTuple(hv_From.TupleLength())) - 1)
                        );
                        hv_To = hv_To.TupleConcat(hv_From.TupleSelect(0));
                    }

                    //Determine the shift between the unrolled images
                    ho_UnrolledImagesShifted.Dispose();
                    HOperatorSet.GenEmptyObj(out ho_UnrolledImagesShifted);

                    //Copy left part of first unrolled image because it can remain unshifted
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_RegionFrom.Dispose();
                        HOperatorSet.SelectObj(
                            ho_RegionsDilation,
                            out ho_RegionFrom,
                            (hv_From.TupleSelect(0)) + 1
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageFrom.Dispose();
                        HOperatorSet.SelectObj(
                            ho_UnrolledImages,
                            out ho_ImageFrom,
                            (hv_From.TupleSelect(0)) + 1
                        );
                    }
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.CopyImage(ho_ImageFrom, out ExpTmpOutVar_0);
                        ho_ImageFrom.Dispose();
                        ho_ImageFrom = ExpTmpOutVar_0;
                    }
                    ho_ConnectedRegions.Dispose();
                    HOperatorSet.Connection(ho_RegionFrom, out ho_ConnectedRegions);
                    hv_Number.Dispose();
                    HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                    if ((int)(new HTuple(hv_Number.TupleGreater(1))) != 0)
                    {
                        ho_SortedRegions.Dispose();
                        HOperatorSet.SortRegion(
                            ho_ConnectedRegions,
                            out ho_SortedRegions,
                            "character",
                            "true",
                            "column"
                        );
                        ho_ObjectSelected.Dispose();
                        HOperatorSet.SelectObj(ho_SortedRegions, out ho_ObjectSelected, 1);
                        ho_ImageFromReduced.Dispose();
                        HOperatorSet.ReduceDomain(
                            ho_ImageFrom,
                            ho_ObjectSelected,
                            out ho_ImageFromReduced
                        );
                        {
                            HObject ExpTmpOutVar_0;
                            HOperatorSet.ConcatObj(
                                ho_UnrolledImagesShifted,
                                ho_ImageFromReduced,
                                out ExpTmpOutVar_0
                            );
                            ho_UnrolledImagesShifted.Dispose();
                            ho_UnrolledImagesShifted = ExpTmpOutVar_0;
                        }
                    }
                    hv_ShiftAccumulated.Dispose();
                    hv_ShiftAccumulated = 0;
                    hv_HomMat2DAccumulated.Dispose();
                    HOperatorSet.HomMat2dIdentity(out hv_HomMat2DAccumulated);

                    //Determine the shift for the mosaicking
                    ho_ObjectSelected.Dispose();
                    HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ObjectSelected, 1);
                    hv_Channels.Dispose();
                    HOperatorSet.CountChannels(ho_ObjectSelected, out hv_Channels);
                    ho_OverlappingAreas.Dispose();
                    HOperatorSet.GenEmptyObj(out ho_OverlappingAreas);
                    hv_MaximaS.Dispose();
                    hv_MaximaS = new HTuple();
                    hv_Maxima.Dispose();
                    hv_Maxima = new HTuple();
                    for (
                        hv_FT = 0;
                        (int)hv_FT <= (int)((new HTuple(hv_From.TupleLength())) - 1);
                        hv_FT = (int)hv_FT + 1
                    )
                    {
                        hv_F.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_F = hv_From.TupleSelect(hv_FT);
                        }
                        hv_T.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_T = hv_To.TupleSelect(hv_FT);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_RegionFrom.Dispose();
                            HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionFrom, hv_F + 1);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_RegionTo.Dispose();
                            HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionTo, hv_T + 1);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_ImageFrom.Dispose();
                            HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageFrom, hv_F + 1);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_ImageTo.Dispose();
                            HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageTo, hv_T + 1);
                        }
                        if (
                            (int)(
                                new HTuple(
                                    hv_FT.TupleEqual((new HTuple(hv_From.TupleLength())) - 1)
                                )
                            ) != 0
                        )
                        {
                            //Add only right part of last image
                            ho_ConnectedRegions.Dispose();
                            HOperatorSet.Connection(ho_RegionTo, out ho_ConnectedRegions);
                            hv_Number.Dispose();
                            HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                            if ((int)(new HTuple(hv_Number.TupleGreater(1))) != 0)
                            {
                                ho_SortedRegions.Dispose();
                                HOperatorSet.SortRegion(
                                    ho_ConnectedRegions,
                                    out ho_SortedRegions,
                                    "character",
                                    "true",
                                    "column"
                                );
                                ho_RegionTo.Dispose();
                                HOperatorSet.SelectObj(ho_SortedRegions, out ho_RegionTo, 2);
                                ho_Domain.Dispose();
                                HOperatorSet.GetDomain(ho_ImageTo, out ho_Domain);
                                ho_RegionBlack.Dispose();
                                HOperatorSet.Difference(ho_Domain, ho_RegionTo, out ho_RegionBlack);
                                HOperatorSet.OverpaintRegion(
                                    ho_ImageTo,
                                    ho_RegionBlack,
                                    ((new HTuple(0)).TupleConcat(0)).TupleConcat(0),
                                    "fill"
                                );
                            }
                        }
                        //Select the kind of image used for matching
                        if ((int)(new HTuple(hv_Channels.TupleEqual(3))) != 0)
                        {
                            switch (2)
                            {
                                case 1:
                                    ho_ImageF1.Dispose();
                                    ho_ImageF2.Dispose();
                                    ho_ImageF3.Dispose();
                                    HOperatorSet.Decompose3(
                                        ho_ImageFrom,
                                        out ho_ImageF1,
                                        out ho_ImageF2,
                                        out ho_ImageF3
                                    );
                                    ho_ImageT1.Dispose();
                                    ho_ImageT2.Dispose();
                                    ho_ImageT3.Dispose();
                                    HOperatorSet.Decompose3(
                                        ho_ImageTo,
                                        out ho_ImageT1,
                                        out ho_ImageT2,
                                        out ho_ImageT3
                                    );
                                    ho_ImageFrom.Dispose();
                                    HOperatorSet.ConvertImageType(
                                        ho_ImageF1,
                                        out ho_ImageFrom,
                                        "real"
                                    );
                                    ho_ImageTo.Dispose();
                                    HOperatorSet.ConvertImageType(
                                        ho_ImageT1,
                                        out ho_ImageTo,
                                        "real"
                                    );
                                    break;
                                case 2:
                                    ho_GrayFrom.Dispose();
                                    HOperatorSet.Rgb1ToGray(ho_ImageFrom, out ho_GrayFrom);
                                    ho_GrayTo.Dispose();
                                    HOperatorSet.Rgb1ToGray(ho_ImageTo, out ho_GrayTo);
                                    ho_ImageFrom.Dispose();
                                    HOperatorSet.ConvertImageType(
                                        ho_GrayFrom,
                                        out ho_ImageFrom,
                                        "real"
                                    );
                                    ho_ImageTo.Dispose();
                                    HOperatorSet.ConvertImageType(
                                        ho_GrayTo,
                                        out ho_ImageTo,
                                        "real"
                                    );
                                    break;
                            }
                        }
                        else
                        {
                            {
                                HObject ExpTmpOutVar_0;
                                HOperatorSet.ConvertImageType(
                                    ho_ImageFrom,
                                    out ExpTmpOutVar_0,
                                    "real"
                                );
                                ho_ImageFrom.Dispose();
                                ho_ImageFrom = ExpTmpOutVar_0;
                            }
                            {
                                HObject ExpTmpOutVar_0;
                                HOperatorSet.ConvertImageType(
                                    ho_ImageTo,
                                    out ExpTmpOutVar_0,
                                    "real"
                                );
                                ho_ImageTo.Dispose();
                                ho_ImageTo = ExpTmpOutVar_0;
                            }
                        }
                        ho_RegionIntersection.Dispose();
                        HOperatorSet.Intersection(
                            ho_RegionFrom,
                            ho_RegionTo,
                            out ho_RegionIntersection
                        );
                        hv_RowInters1.Dispose();
                        hv_ColumnInters1.Dispose();
                        hv_RowInters2.Dispose();
                        hv_ColumnInters2.Dispose();
                        HOperatorSet.SmallestRectangle1(
                            ho_RegionIntersection,
                            out hv_RowInters1,
                            out hv_ColumnInters1,
                            out hv_RowInters2,
                            out hv_ColumnInters2
                        );
                        hv_ColumnCut.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_ColumnCut = (hv_ColumnInters1 + hv_ColumnInters2) / 2;
                        }
                        hv_VisualizeMorphing.Dispose();
                        hv_VisualizeMorphing = 0;
                        //Create Ncc model
                        hv_Angles.Dispose();
                        hv_Angles = new HTuple();
                        hv_Angles[0] = -3;
                        hv_Angles[1] = 3;
                        hv_PaddingTopBottom.Dispose();
                        hv_PaddingTopBottom = 20;
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_Rectangle.Dispose();
                            HOperatorSet.GenRectangle1(
                                out ho_Rectangle,
                                hv_PaddingTopBottom,
                                hv_ColumnCut - (hv_FineAdjustmentMatchingWidth / 2),
                                (hv_MosaicHeight_COPY_INP_TMP - 1) - hv_PaddingTopBottom,
                                hv_ColumnCut + (hv_FineAdjustmentMatchingWidth / 2)
                            );
                        }
                        ho_ImageFromB.Dispose();
                        HOperatorSet.ConvertImageType(ho_ImageFrom, out ho_ImageFromB, "byte");
                        ho_ImageModel.Dispose();
                        HOperatorSet.ReduceDomain(ho_ImageFromB, ho_Rectangle, out ho_ImageModel);
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_ModelID.Dispose();
                            HOperatorSet.CreateNccModel(
                                ho_ImageModel,
                                1,
                                ((hv_Angles.TupleSelect(0))).TupleRad(),
                                (
                                    ((hv_Angles.TupleSelect(1)) - (hv_Angles.TupleSelect(0)))
                                ).TupleRad(),
                                "auto",
                                "use_polarity",
                                out hv_ModelID
                            );
                        }
                        hv_Values.Dispose();
                        HOperatorSet.RegionFeatures(
                            ho_ImageModel,
                            ((new HTuple("row")).TupleConcat("column")).TupleConcat("width"),
                            out hv_Values
                        );

                        //Create the search image
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_RoiSearch.Dispose();
                            HOperatorSet.GenRectangle2(
                                out ho_RoiSearch,
                                hv_Values.TupleSelect(0),
                                hv_Values.TupleSelect(1),
                                0,
                                hv_FineAdjustmentMaxShift,
                                1
                            );
                        }
                        ho_ImageToB.Dispose();
                        HOperatorSet.ConvertImageType(ho_ImageTo, out ho_ImageToB, "byte");
                        ho_ImageSearch.Dispose();
                        HOperatorSet.ReduceDomain(ho_ImageToB, ho_RoiSearch, out ho_ImageSearch);

                        if ((int)(hv_VisualizeMorphing) != 0)
                        {
                            ho_MultiChannelImageLocal.Dispose();
                            HOperatorSet.Compose3(
                                ho_ImageFromB,
                                ho_ImageFromB,
                                ho_ImageToB,
                                out ho_MultiChannelImageLocal
                            );
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                            }
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.DispObj(
                                    ho_MultiChannelImageLocal,
                                    HDevWindowStack.GetActive()
                                );
                            }
                            // stop(...); only in hdevelop
                        }

                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Row.Dispose();
                            hv_Column.Dispose();
                            hv_Angle.Dispose();
                            hv_Score.Dispose();
                            HOperatorSet.FindNccModel(
                                ho_ImageSearch,
                                hv_ModelID,
                                ((hv_Angles.TupleSelect(0))).TupleRad(),
                                (
                                    ((hv_Angles.TupleSelect(1)) - (hv_Angles.TupleSelect(0)))
                                ).TupleRad(),
                                0.3,
                                1,
                                1.0,
                                "true",
                                0,
                                out hv_Row,
                                out hv_Column,
                                out hv_Angle,
                                out hv_Score
                            );
                        }
                        if (
                            (int)(new HTuple((new HTuple(hv_Score.TupleLength())).TupleEqual(0)))
                            != 0
                        )
                        {
                            hv_Row.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_Row = hv_Values.TupleSelect(0);
                            }
                            hv_Column.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_Column = hv_Values.TupleSelect(1);
                            }
                            hv_Angle.Dispose();
                            hv_Angle = 0;
                            hv_Score.Dispose();
                            hv_Score = 0;
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_ImageTo.Dispose();
                            HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageTo, hv_T + 1);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            {
                                HTuple ExpTmpLocalVar_ShiftAccumulated =
                                    hv_ShiftAccumulated + ((hv_Values.TupleSelect(1)) - hv_Column);
                                hv_ShiftAccumulated.Dispose();
                                hv_ShiftAccumulated = ExpTmpLocalVar_ShiftAccumulated;
                            }
                        }

                        //The transformation to move the search image onto the model image
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_HomMat2DI.Dispose();
                            HOperatorSet.VectorAngleToRigid(
                                hv_Row,
                                hv_Column,
                                hv_Angle,
                                hv_Values.TupleSelect(0),
                                hv_Values.TupleSelect(1),
                                0,
                                out hv_HomMat2DI
                            );
                        }

                        //Split the transformation into a translation part in column direction
                        //and the remainder
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_HomMat2DITrans.Dispose();
                            HOperatorSet.VectorAngleToRigid(
                                0,
                                hv_Column,
                                0,
                                0,
                                hv_Values.TupleSelect(1),
                                0,
                                out hv_HomMat2DITrans
                            );
                        }
                        hv_HomMat2DITransInvert.Dispose();
                        HOperatorSet.HomMat2dInvert(hv_HomMat2DITrans, out hv_HomMat2DITransInvert);
                        hv_HomMat2DRemainder.Dispose();
                        HOperatorSet.HomMat2dCompose(
                            hv_HomMat2DI,
                            hv_HomMat2DITransInvert,
                            out hv_HomMat2DRemainder
                        );

                        //Apply the remainder of the transformation in some kind of local morphing
                        //such that the right image fits the left image
                        hv_RowOrig.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_RowOrig = HTuple.TupleGenSequence(
                                0,
                                hv_MosaicHeight_COPY_INP_TMP - 1,
                                1
                            );
                        }
                        hv_ColOrig.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_ColOrig = HTuple.TupleGenConst(
                                hv_MosaicHeight_COPY_INP_TMP,
                                hv_ColumnCut
                            );
                        }
                        hv_RowTrans.Dispose();
                        hv_ColTrans.Dispose();
                        HOperatorSet.AffineTransPixel(
                            hv_HomMat2DRemainder,
                            hv_RowOrig,
                            hv_ColOrig,
                            out hv_RowTrans,
                            out hv_ColTrans
                        );
                        hv_DRow.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_DRow = hv_RowOrig - hv_RowTrans;
                        }
                        hv_DCol.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_DCol = hv_ColOrig - hv_ColTrans;
                        }

                        hv_RegionWidth.Dispose();
                        HOperatorSet.RegionFeatures(
                            ho_Regions_COPY_INP_TMP,
                            "width",
                            out hv_RegionWidth
                        );
                        hv_MorphingWidth.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphingWidth = ((0.2 * (hv_RegionWidth.TupleMin()))).TupleInt();
                        }
                        hv_MorphingExtLeft.Dispose();
                        hv_MorphingExtLeft = 10;
                        hv_MorphingWidth2.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphingWidth2 = (2 * hv_MorphingWidth) + 1;
                        }
                        hv_MorphingWidth2ExtLeft.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphingWidth2ExtLeft = hv_MorphingWidth2 + hv_MorphingExtLeft;
                        }
                        ho_ImageWR.Dispose();
                        HOperatorSet.GenImageConst(
                            out ho_ImageWR,
                            "real",
                            hv_MorphingWidth2ExtLeft,
                            hv_MosaicHeight_COPY_INP_TMP
                        );
                        ho_ImageWC.Dispose();
                        HOperatorSet.GenImageConst(
                            out ho_ImageWC,
                            "real",
                            hv_MorphingWidth2ExtLeft,
                            hv_MosaicHeight_COPY_INP_TMP
                        );
                        hv_RowsWI.Dispose();
                        hv_ColumnsWI.Dispose();
                        HOperatorSet.GetRegionPoints(ho_ImageWR, out hv_RowsWI, out hv_ColumnsWI);
                        hv_Ramp.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Ramp = new HTuple();
                            hv_Ramp = hv_Ramp.TupleConcat(
                                HTuple.TupleGenConst(hv_MorphingExtLeft, 2.0)
                            );
                            hv_Ramp = hv_Ramp.TupleConcat(
                                (
                                    (
                                        (
                                            HTuple.TupleGenConst(
                                                hv_MorphingWidth2 - 1,
                                                2.0 / hv_MorphingWidth2
                                            )
                                        ).TupleCumul()
                                    )
                                ).TupleInverse()
                            );
                            hv_Ramp = hv_Ramp.TupleConcat(0);
                        }
                        hv_MorphR.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphR = HTuple.TupleGenConst(
                                new HTuple(hv_RowsWI.TupleLength()),
                                0
                            );
                        }
                        hv_MorphC.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphC = HTuple.TupleGenConst(
                                new HTuple(hv_RowsWI.TupleLength()),
                                0
                            );
                        }
                        HTuple end_val339 = hv_MosaicHeight_COPY_INP_TMP - 1;
                        HTuple step_val339 = 1;
                        for (
                            hv_RW = 0;
                            hv_RW.Continue(end_val339, step_val339);
                            hv_RW = hv_RW.TupleAdd(step_val339)
                        )
                        {
                            if (hv_MorphR == null)
                                hv_MorphR = new HTuple();
                            hv_MorphR[
                                HTuple.TupleGenSequence(
                                    hv_RW * hv_MorphingWidth2ExtLeft,
                                    ((hv_RW * hv_MorphingWidth2ExtLeft) + hv_MorphingWidth2ExtLeft)
                                        - 1,
                                    1
