            HTuple hv_RW = new HTuple(),
                hv_MosaicWidthExt = new HTuple();
            HTuple hv_MosaicHeightExt = new HTuple(),
                hv_NumberUI = new HTuple();
            HTuple hv_ColumnBlendingCenter = new HTuple(),
                hv_NumberUnrolledImages = new HTuple();
            HTuple hv_I = new HTuple(),
                hv_RowI1 = new HTuple(),
                hv_ColumnI1 = new HTuple();
            HTuple hv_RowI2 = new HTuple(),
                hv_ColumnI2 = new HTuple();
            HTuple hv_Dummy = new HTuple(),
                hv_RightBorder = new HTuple();
            HTuple hv_BSEven = new HTuple(),
                hv_BS2 = new HTuple();
            HTuple hv_BSStep = new HTuple(),
                hv_BSLeft = new HTuple();
            HTuple hv_BSRight = new HTuple(),
                hv_MaskOneLine = new HTuple();
            HTuple hv_CylinderPointsX_COPY_INP_TMP = new HTuple(hv_CylinderPointsX);
            HTuple hv_CylinderPointsY_COPY_INP_TMP = new HTuple(hv_CylinderPointsY);
            HTuple hv_CylinderPointsZ_COPY_INP_TMP = new HTuple(hv_CylinderPointsZ);
            HTuple hv_MosaicHeight_COPY_INP_TMP = new HTuple(hv_MosaicHeight);
            HTuple hv_WindowHandle_COPY_INP_TMP = new HTuple(hv_WindowHandle);

            // Initialize local and output iconic variables
            HOperatorSet.GenEmptyObj(out ho_FinalMosaic);
            HOperatorSet.GenEmptyObj(out ho_ImageMosaicR);
            HOperatorSet.GenEmptyObj(out ho_ImageMosaicG);
            HOperatorSet.GenEmptyObj(out ho_ImageMosaicB);
            HOperatorSet.GenEmptyObj(out ho_ImageMosaic);
            HOperatorSet.GenEmptyObj(out ho_Region);
            HOperatorSet.GenEmptyObj(out ho_ObjectSelected);
            HOperatorSet.GenEmptyObj(out ho_ImageR);
            HOperatorSet.GenEmptyObj(out ho_ImageG);
            HOperatorSet.GenEmptyObj(out ho_ImageB);
            HOperatorSet.GenEmptyObj(out ho_ImageGray);
            HOperatorSet.GenEmptyObj(out ho_RegionsDilation);
            HOperatorSet.GenEmptyObj(out ho_UnrolledImages);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolledR);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolledG);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolledB);
            HOperatorSet.GenEmptyObj(out ho_ImageUnrolled);
            HOperatorSet.GenEmptyObj(out ho_RegionTrans);
            HOperatorSet.GenEmptyObj(out ho_ConnectedRegions);
            HOperatorSet.GenEmptyObj(out ho_Image);
            HOperatorSet.GenEmptyObj(out ho_ImagePart);
            HOperatorSet.GenEmptyObj(out ho_ImageReduced);
            HOperatorSet.GenEmptyObj(out ho_ImageScaled);
            HOperatorSet.GenEmptyObj(out ho_ImageDisp);
            HOperatorSet.GenEmptyObj(out ho_ImageRotate);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImage);
            HOperatorSet.GenEmptyObj(out ho_UnrolledOut);
            HOperatorSet.GenEmptyObj(out ho_RegionMaskOut);
            HOperatorSet.GenEmptyObj(out ho_DomainUnrolledOut);
            HOperatorSet.GenEmptyObj(out ho_RegionDifference);
            HOperatorSet.GenEmptyObj(out ho_UnrolledImagesShifted);
            HOperatorSet.GenEmptyObj(out ho_RegionFrom);
            HOperatorSet.GenEmptyObj(out ho_ImageFrom);
            HOperatorSet.GenEmptyObj(out ho_SortedRegions);
            HOperatorSet.GenEmptyObj(out ho_ImageFromReduced);
            HOperatorSet.GenEmptyObj(out ho_OverlappingAreas);
            HOperatorSet.GenEmptyObj(out ho_RegionTo);
            HOperatorSet.GenEmptyObj(out ho_ImageTo);
            HOperatorSet.GenEmptyObj(out ho_Domain);
            HOperatorSet.GenEmptyObj(out ho_RegionBlack);
            HOperatorSet.GenEmptyObj(out ho_ImageF1);
            HOperatorSet.GenEmptyObj(out ho_ImageF2);
            HOperatorSet.GenEmptyObj(out ho_ImageF3);
            HOperatorSet.GenEmptyObj(out ho_ImageT1);
            HOperatorSet.GenEmptyObj(out ho_ImageT2);
            HOperatorSet.GenEmptyObj(out ho_ImageT3);
            HOperatorSet.GenEmptyObj(out ho_GrayFrom);
            HOperatorSet.GenEmptyObj(out ho_GrayTo);
            HOperatorSet.GenEmptyObj(out ho_RegionIntersection);
            HOperatorSet.GenEmptyObj(out ho_Rectangle);
            HOperatorSet.GenEmptyObj(out ho_ImageFromB);
            HOperatorSet.GenEmptyObj(out ho_ImageModel);
            HOperatorSet.GenEmptyObj(out ho_RoiSearch);
            HOperatorSet.GenEmptyObj(out ho_ImageToB);
            HOperatorSet.GenEmptyObj(out ho_ImageSearch);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImageLocal);
            HOperatorSet.GenEmptyObj(out ho_ImageWR);
            HOperatorSet.GenEmptyObj(out ho_ImageWC);
            HOperatorSet.GenEmptyObj(out ho_VectorField);
            HOperatorSet.GenEmptyObj(out ho_Image1);
            HOperatorSet.GenEmptyObj(out ho_Image2);
            HOperatorSet.GenEmptyObj(out ho_Image3);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped1);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped2);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped3);
            HOperatorSet.GenEmptyObj(out ho_ObjectsConcat);
            HOperatorSet.GenEmptyObj(out ho_MorphedImage);
            HOperatorSet.GenEmptyObj(out ho_ImageUnwarped);
            HOperatorSet.GenEmptyObj(out ho_ImageToBShiftLocal);
            HOperatorSet.GenEmptyObj(out ho_ImageToShift);
            HOperatorSet.GenEmptyObj(out ho_RegionToShift);
            HOperatorSet.GenEmptyObj(out ho_ImageToShiftReduced);
            HOperatorSet.GenEmptyObj(out ho_RegionIntersection1);
            HOperatorSet.GenEmptyObj(out ho_ImageLeft);
            HOperatorSet.GenEmptyObj(out ho_ImageRight);
            HOperatorSet.GenEmptyObj(out ho_GrayImageLeft);
            HOperatorSet.GenEmptyObj(out ho_GrayImageRight);
            HOperatorSet.GenEmptyObj(out ho_GrayImageLeftB);
            HOperatorSet.GenEmptyObj(out ho_GrayImageRightB);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelImage1);
            HOperatorSet.GenEmptyObj(out ho_I1);
            HOperatorSet.GenEmptyObj(out ho_I2);
            HOperatorSet.GenEmptyObj(out ho_D1);
            HOperatorSet.GenEmptyObj(out ho_D2);
            HOperatorSet.GenEmptyObj(out ho_BlendingMasks);
            HOperatorSet.GenEmptyObj(out ho_ImageM1);
            HOperatorSet.GenEmptyObj(out ho_ImageM);
            HOperatorSet.GenEmptyObj(out ho_ImageTest);
            HOperatorSet.GenEmptyObj(out ho_Img);
            HOperatorSet.GenEmptyObj(out ho_ImgExt);
            HOperatorSet.GenEmptyObj(out ho_ImgReal);
            HOperatorSet.GenEmptyObj(out ho_Mas);
            HOperatorSet.GenEmptyObj(out ho_MultiChannelMask);
            HOperatorSet.GenEmptyObj(out ho_ImageForStitching);
            try
            {
                //global tuple DisplayIntermediateResults
                //global tuple WindowWidthLimit
                //global tuple WindowHeightLimit

                //Determine the part of the cylinder that must be used according to the
                //given area of the label in the first image
                hv_Indices.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_Indices = new HTuple();
                    hv_Indices[0] = 0;
                    hv_Indices = hv_Indices.TupleConcat(
                        (HTuple.TupleGenConst(hv_NumSlices - 1, hv_NumPointsPerSlice)).TupleCumul()
                    );
                }
                hv_SamplePX.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SamplePX = hv_CylinderPointsX_COPY_INP_TMP.TupleSelect(hv_Indices);
                }
                hv_SamplePY.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SamplePY = hv_CylinderPointsY_COPY_INP_TMP.TupleSelect(hv_Indices);
                }
                hv_SamplePZ.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SamplePZ = hv_CylinderPointsZ_COPY_INP_TMP.TupleSelect(hv_Indices);
                }
                hv_CamParam0.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    0,
                    "params",
                    out hv_CamParam0
                );
                hv_CamPose0.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    0,
                    "pose",
                    out hv_CamPose0
                );
                hv_HomMat3D0.Dispose();
                HOperatorSet.PoseToHomMat3d(hv_CamPose0, out hv_HomMat3D0);
                hv_HomMat3D0Invert.Dispose();
                HOperatorSet.HomMat3dInvert(hv_HomMat3D0, out hv_HomMat3D0Invert);
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                HOperatorSet.AffineTransPoint3d(
                    hv_HomMat3D0Invert,
                    hv_SamplePX,
                    hv_SamplePY,
                    hv_SamplePZ,
                    out hv_Qx,
                    out hv_Qy,
                    out hv_Qz
                );
                hv_ImageSampleRow.Dispose();
                hv_ImageSampleColumn.Dispose();
                HOperatorSet.Project3dPoint(
                    hv_Qx,
                    hv_Qy,
                    hv_Qz,
                    hv_CamParam0,
                    out hv_ImageSampleRow,
                    out hv_ImageSampleColumn
                );
                hv_MinSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MinSlice = (
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (
                                                    (
                                                        (hv_ImageSampleColumn - hv_LabelMinCol)
                                                    ).TupleSgn()
                                                )
                                            ).TupleFind(1)
                                        )
                                    ).TupleSelect(0)
                                )
                            ).TupleConcat(0)
                        )
                    ).TupleMax();
                }
                hv_MaxSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MaxSlice = (
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (
                                                    (
                                                        (hv_ImageSampleColumn - hv_LabelMaxCol)
                                                    ).TupleSgn()
                                                )
                                            ).TupleFind(1)
                                        )
                                    ).TupleSelect(0)
                                )
                            ).TupleConcat(hv_NumSlices - 1)
                        )
                    ).TupleMin();
                }

                hv_MosaicHeight_COPY_INP_TMP.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MosaicHeight_COPY_INP_TMP = (hv_MaxSlice - hv_MinSlice) + 1;
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_CylinderPointsX =
                            hv_CylinderPointsX_COPY_INP_TMP.TupleSelectRange(
                                hv_MinSlice * hv_NumPointsPerSlice,
                                ((hv_MaxSlice * hv_NumPointsPerSlice) + hv_NumPointsPerSlice) - 1
                            );
                        hv_CylinderPointsX_COPY_INP_TMP.Dispose();
                        hv_CylinderPointsX_COPY_INP_TMP = ExpTmpLocalVar_CylinderPointsX;
                    }
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_CylinderPointsY =
                            hv_CylinderPointsY_COPY_INP_TMP.TupleSelectRange(
                                hv_MinSlice * hv_NumPointsPerSlice,
                                ((hv_MaxSlice * hv_NumPointsPerSlice) + hv_NumPointsPerSlice) - 1
                            );
                        hv_CylinderPointsY_COPY_INP_TMP.Dispose();
                        hv_CylinderPointsY_COPY_INP_TMP = ExpTmpLocalVar_CylinderPointsY;
                    }
                }
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    {
                        HTuple ExpTmpLocalVar_CylinderPointsZ =
                            hv_CylinderPointsZ_COPY_INP_TMP.TupleSelectRange(
                                hv_MinSlice * hv_NumPointsPerSlice,
                                ((hv_MaxSlice * hv_NumPointsPerSlice) + hv_NumPointsPerSlice) - 1
                            );
                        hv_CylinderPointsZ_COPY_INP_TMP.Dispose();
                        hv_CylinderPointsZ_COPY_INP_TMP = ExpTmpLocalVar_CylinderPointsZ;
                    }
                }

                if ((int)(hv_PerformFineAdjustment.TupleNot()) != 0)
                {
                    if ((int)(hv_ColorMosaic) != 0)
                    {
                        ho_ImageMosaicR.Dispose();
                        HOperatorSet.GenImageConst(
                            out ho_ImageMosaicR,
                            "byte",
                            hv_MosaicWidth,
                            hv_MosaicHeight_COPY_INP_TMP
                        );
                        ho_ImageMosaicG.Dispose();
                        HOperatorSet.GenImageConst(
                            out ho_ImageMosaicG,
                            "byte",
                            hv_MosaicWidth,
                            hv_MosaicHeight_COPY_INP_TMP
                        );
                        ho_ImageMosaicB.Dispose();
                        HOperatorSet.GenImageConst(
                            out ho_ImageMosaicB,
                            "byte",
                            hv_MosaicWidth,
                            hv_MosaicHeight_COPY_INP_TMP
                        );
                        ho_ImageMosaic.Dispose();
                        HOperatorSet.Compose3(
                            ho_ImageMosaicR,
                            ho_ImageMosaicG,
                            ho_ImageMosaicB,
                            out ho_ImageMosaic
                        );
                    }
                    else
                    {
                        ho_ImageMosaic.Dispose();
                        HOperatorSet.GenImageConst(
                            out ho_ImageMosaic,
                            "byte",
                            hv_MosaicWidth,
                            hv_MosaicHeight_COPY_INP_TMP
                        );
                    }

                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ClipRegion(
                            ho_Regions_COPY_INP_TMP,
                            out ExpTmpOutVar_0,
                            0,
                            0,
                            hv_MosaicHeight_COPY_INP_TMP - 1,
                            hv_MosaicWidth - 1
                        );
                        ho_Regions_COPY_INP_TMP.Dispose();
                        ho_Regions_COPY_INP_TMP = ExpTmpOutVar_0;
                    }

                    HTuple end_val37 = hv_NumCameras - 1;
                    HTuple step_val37 = 1;
                    for (
                        hv_Cam = 0;
                        hv_Cam.Continue(end_val37, step_val37);
                        hv_Cam = hv_Cam.TupleAdd(step_val37)
                    )
                    {
                        hv_CamParam.Dispose();
                        HOperatorSet.GetCameraSetupParam(
                            hv_CameraSetupModelZeroDistInCylinderOrigin,
                            hv_Cam,
                            "params",
                            out hv_CamParam
                        );
                        hv_ImageWidth.Dispose();
                        get_cam_par_data(hv_CamParam, "image_width", out hv_ImageWidth);
                        hv_ImageHeight.Dispose();
                        get_cam_par_data(hv_CamParam, "image_height", out hv_ImageHeight);
                        hv_CamPose.Dispose();
                        HOperatorSet.GetCameraSetupParam(
                            hv_CameraSetupModelZeroDistInCylinderOrigin,
                            hv_Cam,
                            "pose",
                            out hv_CamPose
                        );
                        hv_HomMat3D.Dispose();
                        HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                        hv_HomMat3DInvert.Dispose();
                        HOperatorSet.HomMat3dInvert(hv_HomMat3D, out hv_HomMat3DInvert);
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_Region.Dispose();
                            HOperatorSet.SelectObj(
                                ho_Regions_COPY_INP_TMP,
                                out ho_Region,
                                hv_Cam + 1
                            );
                        }
                        hv_Rows.Dispose();
                        hv_Columns.Dispose();
                        HOperatorSet.GetRegionPoints(ho_Region, out hv_Rows, out hv_Columns);
                        hv_LinCoord.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_LinCoord = (hv_Rows * hv_NumPointsPerSlice) + hv_Columns;
                        }

                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Qx.Dispose();
                            hv_Qy.Dispose();
                            hv_Qz.Dispose();
                            HOperatorSet.AffineTransPoint3d(
                                hv_HomMat3DInvert,
                                hv_CylinderPointsX_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                                hv_CylinderPointsY_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                                hv_CylinderPointsZ_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                                out hv_Qx,
                                out hv_Qy,
                                out hv_Qz
                            );
                        }
                        hv_ImageRow.Dispose();
                        hv_ImageColumn.Dispose();
                        HOperatorSet.Project3dPoint(
                            hv_Qx,
                            hv_Qy,
                            hv_Qz,
                            hv_CamParam,
                            out hv_ImageRow,
                            out hv_ImageColumn
                        );

                        hv_Mask.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Mask = (
                                new HTuple(
                                    (
                                        new HTuple(
                                            ((hv_ImageRow.TupleGreaterEqualElem(0))).TupleAnd(
                                                hv_ImageRow.TupleLessEqualElem(hv_ImageHeight - 1)
                                            )
                                        )
                                    ).TupleAnd(hv_ImageColumn.TupleGreaterEqualElem(0))
                                )
                            ).TupleAnd(hv_ImageColumn.TupleLessEqualElem(hv_ImageWidth - 1));
                        }
                        hv_ImageRowSub.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_ImageRowSub = hv_ImageRow.TupleSelectMask(hv_Mask);
                        }
                        hv_ImageColumnSub.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_ImageColumnSub = hv_ImageColumn.TupleSelectMask(hv_Mask);
                        }

                        if ((int)(hv_ColorMosaic) != 0)
                        {
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_ObjectSelected.Dispose();
                                HOperatorSet.SelectObj(
                                    ho_ImagesRectified,
                                    out ho_ObjectSelected,
                                    hv_Cam + 1
                                );
                            }
                            ho_ImageR.Dispose();
                            ho_ImageG.Dispose();
                            ho_ImageB.Dispose();
                            HOperatorSet.Decompose3(
                                ho_ObjectSelected,
                                out ho_ImageR,
                                out ho_ImageG,
                                out ho_ImageB
                            );

                            if ((int)(hv_HighImageQuality) != 0)
                            {
                                hv_BicubicInterpolation.Dispose();
                                hv_BicubicInterpolation = 1;
                                if ((int)(hv_BicubicInterpolation) != 0)
                                {
                                    hv_Grayval.Dispose();
                                    HOperatorSet.GetGrayvalInterpolated(
                                        ho_ImageR,
                                        hv_ImageRowSub,
                                        hv_ImageColumnSub,
                                        "bicubic",
                                        out hv_Grayval
                                    );
                                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                    {
                                        HOperatorSet.SetGrayval(
                                            ho_ImageMosaicR,
                                            hv_Rows.TupleSelectMask(hv_Mask),
                                            hv_Columns.TupleSelectMask(hv_Mask),
                                            hv_Grayval
                                        );
                                    }
                                    hv_Grayval.Dispose();
                                    HOperatorSet.GetGrayvalInterpolated(
                                        ho_ImageG,
                                        hv_ImageRowSub,
                                        hv_ImageColumnSub,
                                        "bicubic",
                                        out hv_Grayval
                                    );
                                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                    {
                                        HOperatorSet.SetGrayval(
                                            ho_ImageMosaicG,
                                            hv_Rows.TupleSelectMask(hv_Mask),
                                            hv_Columns.TupleSelectMask(hv_Mask),
                                            hv_Grayval
                                        );
                                    }
                                    hv_Grayval.Dispose();
                                    HOperatorSet.GetGrayvalInterpolated(
                                        ho_ImageB,
                                        hv_ImageRowSub,
                                        hv_ImageColumnSub,
                                        "bicubic",
                                        out hv_Grayval
                                    );
                                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                    {
                                        HOperatorSet.SetGrayval(
                                            ho_ImageMosaicB,
                                            hv_Rows.TupleSelectMask(hv_Mask),
                                            hv_Columns.TupleSelectMask(hv_Mask),
                                            hv_Grayval
                                        );
                                    }
                                }
                                else
                                {
                                    hv_Grayval.Dispose();
                                    HOperatorSet.GetGrayvalInterpolated(
                                        ho_ImageR,
                                        hv_ImageRowSub,
                                        hv_ImageColumnSub,
                                        "bilinear",
                                        out hv_Grayval
                                    );
                                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                    {
                                        HOperatorSet.SetGrayval(
                                            ho_ImageMosaicR,
                                            hv_Rows.TupleSelectMask(hv_Mask),
                                            hv_Columns.TupleSelectMask(hv_Mask),
                                            hv_Grayval
                                        );
                                    }
                                    hv_Grayval.Dispose();
                                    HOperatorSet.GetGrayvalInterpolated(
                                        ho_ImageG,
                                        hv_ImageRowSub,
                                        hv_ImageColumnSub,
                                        "bilinear",
                                        out hv_Grayval
                                    );
                                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                    {
                                        HOperatorSet.SetGrayval(
                                            ho_ImageMosaicG,
                                            hv_Rows.TupleSelectMask(hv_Mask),
                                            hv_Columns.TupleSelectMask(hv_Mask),
                                            hv_Grayval
                                        );
                                    }
                                    hv_Grayval.Dispose();
                                    HOperatorSet.GetGrayvalInterpolated(
                                        ho_ImageB,
                                        hv_ImageRowSub,
                                        hv_ImageColumnSub,
                                        "bilinear",
                                        out hv_Grayval
                                    );
                                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                    {
                                        HOperatorSet.SetGrayval(
                                            ho_ImageMosaicB,
                                            hv_Rows.TupleSelectMask(hv_Mask),
                                            hv_Columns.TupleSelectMask(hv_Mask),
                                            hv_Grayval
                                        );
                                    }
                                }
                            }
                            else
                            {
                                hv_Grayval1.Dispose();
                                HOperatorSet.GetGrayval(
                                    ho_ObjectSelected,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    out hv_Grayval1
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageMosaic,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval1
                                    );
                                }
                            }
                        }
                        else
                        {
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_ImageGray.Dispose();
                                HOperatorSet.SelectObj(
                                    ho_ImagesGrayRectified,
                                    out ho_ImageGray,
                                    hv_Cam + 1
                                );
                            }

                            if ((int)(hv_HighImageQuality) != 0)
                            {
                                hv_Grayval.Dispose();
                                HOperatorSet.GetGrayvalInterpolated(
                                    ho_ImageGray,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    "bilinear",
                                    out hv_Grayval
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageMosaic,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval
                                    );
                                }
                            }
                            else
                            {
                                hv_Grayval1.Dispose();
                                HOperatorSet.GetGrayval(
                                    ho_ImageGray,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    out hv_Grayval1
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageMosaic,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval1
                                    );
                                }
                            }
                        }
                    }
                    ho_FinalMosaic.Dispose();
                    HOperatorSet.CopyImage(ho_ImageMosaic, out ho_FinalMosaic);
                }
                else
                {
                    //Extend the regions such that they overlap each other to allow
                    //some matching for the fine adjustment
                    hv_DilWidth.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_DilWidth =
                            (
                                (
                                    (
                                        (
                                            (
                                                (
                                                    (
                                                        hv_FineAdjustmentMatchingWidth
                                                        + (2 * hv_FineAdjustmentMaxShift)
                                                    )
                                                ).TupleConcat(
                                                    hv_BlendingSeam + hv_FineAdjustmentMaxShift
                                                )
                                            )
                                        ).TupleMax()
                                    ) / 2
                                ) * 2
                            ) + 1;
                    }
                    ho_RegionsDilation.Dispose();
                    HOperatorSet.DilationRectangle1(
                        ho_Regions_COPY_INP_TMP,
                        out ho_RegionsDilation,
                        hv_DilWidth,
                        1
                    );
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.ClipRegion(
                            ho_RegionsDilation,
                            out ExpTmpOutVar_0,
                            0,
                            0,
                            hv_MosaicHeight_COPY_INP_TMP - 1,
                            hv_MosaicWidth - 1
                        );
                        ho_RegionsDilation.Dispose();
                        ho_RegionsDilation = ExpTmpOutVar_0;
                    }

                    //Unroll the images from the individual cameras such that they overlap each other
                    ho_UnrolledImages.Dispose();
                    HOperatorSet.GenEmptyObj(out ho_UnrolledImages);
                    HTuple end_val103 = hv_NumCameras - 1;
                    HTuple step_val103 = 1;
                    for (
                        hv_Cam = 0;
                        hv_Cam.Continue(end_val103, step_val103);
                        hv_Cam = hv_Cam.TupleAdd(step_val103)
                    )
                    {
                        if ((int)(hv_ColorMosaic) != 0)
                        {
                            ho_ImageUnrolledR.Dispose();
                            HOperatorSet.GenImageConst(
                                out ho_ImageUnrolledR,
                                "byte",
                                hv_MosaicWidth,
                                hv_MosaicHeight_COPY_INP_TMP
                            );
                            ho_ImageUnrolledG.Dispose();
                            HOperatorSet.GenImageConst(
                                out ho_ImageUnrolledG,
                                "byte",
                                hv_MosaicWidth,
                                hv_MosaicHeight_COPY_INP_TMP
                            );
                            ho_ImageUnrolledB.Dispose();
                            HOperatorSet.GenImageConst(
                                out ho_ImageUnrolledB,
                                "byte",
                                hv_MosaicWidth,
                                hv_MosaicHeight_COPY_INP_TMP
                            );
                        }
                        else
                        {
                            ho_ImageUnrolled.Dispose();
                            HOperatorSet.GenImageConst(
                                out ho_ImageUnrolled,
                                "byte",
                                hv_MosaicWidth,
                                hv_MosaicHeight_COPY_INP_TMP
                            );
                        }

                        hv_CamParam.Dispose();
                        HOperatorSet.GetCameraSetupParam(
                            hv_CameraSetupModelZeroDistInCylinderOrigin,
                            hv_Cam,
                            "params",
                            out hv_CamParam
                        );
                        hv_ImageWidth.Dispose();
                        get_cam_par_data(hv_CamParam, "image_width", out hv_ImageWidth);
                        hv_ImageHeight.Dispose();
                        get_cam_par_data(hv_CamParam, "image_height", out hv_ImageHeight);
                        hv_CamPose.Dispose();
                        HOperatorSet.GetCameraSetupParam(
                            hv_CameraSetupModelZeroDistInCylinderOrigin,
                            hv_Cam,
                            "pose",
                            out hv_CamPose
                        );
                        hv_HomMat3D.Dispose();
                        HOperatorSet.PoseToHomMat3d(hv_CamPose, out hv_HomMat3D);
                        hv_HomMat3DInvert.Dispose();
                        HOperatorSet.HomMat3dInvert(hv_HomMat3D, out hv_HomMat3DInvert);
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_Region.Dispose();
                            HOperatorSet.SelectObj(ho_RegionsDilation, out ho_Region, hv_Cam + 1);
                        }
                        hv_Rows.Dispose();
                        hv_Columns.Dispose();
                        HOperatorSet.GetRegionPoints(ho_Region, out hv_Rows, out hv_Columns);
                        hv_LinCoord.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_LinCoord = (hv_Rows * hv_NumPointsPerSlice) + hv_Columns;
                        }

                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Qx.Dispose();
                            hv_Qy.Dispose();
                            hv_Qz.Dispose();
                            HOperatorSet.AffineTransPoint3d(
                                hv_HomMat3DInvert,
                                hv_CylinderPointsX_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                                hv_CylinderPointsY_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                                hv_CylinderPointsZ_COPY_INP_TMP.TupleSelect(hv_LinCoord),
                                out hv_Qx,
                                out hv_Qy,
                                out hv_Qz
                            );
                        }
                        hv_ImageRow.Dispose();
                        hv_ImageColumn.Dispose();
                        HOperatorSet.Project3dPoint(
                            hv_Qx,
                            hv_Qy,
                            hv_Qz,
                            hv_CamParam,
                            out hv_ImageRow,
                            out hv_ImageColumn
                        );

                        hv_Mask.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_Mask = (
                                new HTuple(
                                    (
                                        new HTuple(
                                            ((hv_ImageRow.TupleGreaterEqualElem(0))).TupleAnd(
                                                hv_ImageRow.TupleLessEqualElem(hv_ImageHeight - 1)
                                            )
                                        )
                                    ).TupleAnd(hv_ImageColumn.TupleGreaterEqualElem(0))
                                )
                            ).TupleAnd(hv_ImageColumn.TupleLessEqualElem(hv_ImageWidth - 1));
                        }
                        hv_ImageRowSub.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_ImageRowSub = hv_ImageRow.TupleSelectMask(hv_Mask);
                        }
                        hv_ImageColumnSub.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_ImageColumnSub = hv_ImageColumn.TupleSelectMask(hv_Mask);
                        }

                        if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                        {
                            ho_Region.Dispose();
                            HOperatorSet.GenRegionPoints(
                                out ho_Region,
                                hv_ImageRowSub,
                                hv_ImageColumnSub
                            );
                            for (
                                hv_ClosingRad = 1.5;
                                (double)hv_ClosingRad <= 15.5;
                                hv_ClosingRad = (double)hv_ClosingRad + 1
                            )
                            {
                                ho_RegionTrans.Dispose();
                                HOperatorSet.ClosingCircle(
                                    ho_Region,
                                    out ho_RegionTrans,
                                    hv_ClosingRad
                                );
                                ho_ConnectedRegions.Dispose();
                                HOperatorSet.Connection(ho_RegionTrans, out ho_ConnectedRegions);
                                hv_Number.Dispose();
                                HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                                if ((int)(new HTuple(hv_Number.TupleEqual(1))) != 0)
                                {
                                    break;
                                }
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_Image.Dispose();
                                HOperatorSet.SelectObj(
                                    ho_ImagesRectified,
                                    out ho_Image,
                                    hv_Cam + 1
                                );
                            }
                            ho_ImagePart.Dispose();
                            HOperatorSet.CopyImage(ho_Image, out ho_ImagePart);
                            ho_ImageReduced.Dispose();
                            HOperatorSet.ReduceDomain(
                                ho_ImagePart,
                                ho_RegionTrans,
                                out ho_ImageReduced
                            );
                            ho_ImageScaled.Dispose();
                            HOperatorSet.ScaleImage(ho_ImageReduced, out ho_ImageScaled, 0.25, 150);
                            ho_ImageDisp.Dispose();
                            HOperatorSet.CopyImage(ho_Image, out ho_ImageDisp);
                            HOperatorSet.OverpaintGray(ho_ImageDisp, ho_ImageScaled);
                            ho_ImageRotate.Dispose();
                            HOperatorSet.RotateImage(
                                ho_ImageDisp,
                                out ho_ImageRotate,
                                -90,
                                "constant"
                            );
                            if (HDevWindowStack.IsOpen())
                            {
                                hv_WindowHandle_COPY_INP_TMP = HDevWindowStack.GetActive();
                            }
                            dev_resize_window_fit_image(
                                ho_ImageRotate,
                                0,
                                0,
                                ExpGetGlobalVar_WindowWidthLimit(),
                                ExpGetGlobalVar_WindowHeightLimit()
                            );
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.DispObj(ho_ImageRotate, HDevWindowStack.GetActive());
                            }
                            hv_Message.Dispose();
                            hv_Message = "Image part that will be unrolled";
                            hv_MessageWrapped.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_MessageWrapped = ((hv_Message + " ")).TupleRegexpReplace(
                                    (new HTuple("(.{0,40})\\s")).TupleConcat("replace_all"),
                                    "$1\n"
                                );
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                disp_message(
                                    hv_WindowHandle_COPY_INP_TMP,
                                    ((("Camera " + (hv_Cam + 1)) + ":")).TupleConcat(
                                        hv_MessageWrapped
                                    ),
                                    "window",
                                    12,
                                    12,
                                    "black",
                                    "true"
                                );
                            }
                            // stop(...); only in hdevelop
                        }

                        if ((int)(hv_ColorMosaic) != 0)
                        {
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_ObjectSelected.Dispose();
                                HOperatorSet.SelectObj(
                                    ho_ImagesRectified,
                                    out ho_ObjectSelected,
                                    hv_Cam + 1
                                );
                            }
                            ho_ImageR.Dispose();
                            ho_ImageG.Dispose();
                            ho_ImageB.Dispose();
                            HOperatorSet.Decompose3(
                                ho_ObjectSelected,
                                out ho_ImageR,
                                out ho_ImageG,
                                out ho_ImageB
                            );

                            if ((int)(hv_HighImageQuality) != 0)
                            {
                                hv_Grayval.Dispose();
                                HOperatorSet.GetGrayvalInterpolated(
                                    ho_ImageR,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    "bilinear",
                                    out hv_Grayval
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageUnrolledR,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval
                                    );
                                }
                                hv_Grayval.Dispose();
                                HOperatorSet.GetGrayvalInterpolated(
                                    ho_ImageG,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    "bilinear",
                                    out hv_Grayval
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageUnrolledG,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval
                                    );
                                }
                                hv_Grayval.Dispose();
                                HOperatorSet.GetGrayvalInterpolated(
                                    ho_ImageB,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    "bilinear",
                                    out hv_Grayval
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageUnrolledB,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval
                                    );
                                }
                                ho_MultiChannelImage.Dispose();
                                HOperatorSet.Compose3(
                                    ho_ImageUnrolledR,
                                    ho_ImageUnrolledG,
                                    ho_ImageUnrolledB,
                                    out ho_MultiChannelImage
                                );
                            }
                            else
                            {
                                hv_Grayval1.Dispose();
                                HOperatorSet.GetGrayval(
                                    ho_ObjectSelected,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    out hv_Grayval1
                                );
                                ho_MultiChannelImage.Dispose();
                                HOperatorSet.Compose3(
                                    ho_ImageUnrolledR,
                                    ho_ImageUnrolledG,
                                    ho_ImageUnrolledB,
                                    out ho_MultiChannelImage
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_MultiChannelImage,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval1
                                    );
                                }
                            }
                            {
                                HObject ExpTmpOutVar_0;
                                HOperatorSet.ConcatObj(
                                    ho_UnrolledImages,
                                    ho_MultiChannelImage,
                                    out ExpTmpOutVar_0
                                );
                                ho_UnrolledImages.Dispose();
                                ho_UnrolledImages = ExpTmpOutVar_0;
                            }
                        }
                        else
                        {
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_ImageGray.Dispose();
                                HOperatorSet.SelectObj(
                                    ho_ImagesGrayRectified,
                                    out ho_ImageGray,
                                    hv_Cam + 1
                                );
                            }

                            if ((int)(hv_HighImageQuality) != 0)
                            {
                                hv_Grayval.Dispose();
                                HOperatorSet.GetGrayvalInterpolated(
                                    ho_ImageGray,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    "bilinear",
                                    out hv_Grayval
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageUnrolled,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval
                                    );
                                }
                            }
                            else
                            {
                                hv_Grayval1.Dispose();
                                HOperatorSet.GetGrayval(
                                    ho_ImageGray,
                                    hv_ImageRowSub,
                                    hv_ImageColumnSub,
                                    out hv_Grayval1
                                );
                                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                                {
                                    HOperatorSet.SetGrayval(
                                        ho_ImageUnrolled,
                                        hv_Rows.TupleSelectMask(hv_Mask),
                                        hv_Columns.TupleSelectMask(hv_Mask),
                                        hv_Grayval1
                                    );
                                }
                            }
                            {
                                HObject ExpTmpOutVar_0;
                                HOperatorSet.ConcatObj(
                                    ho_UnrolledImages,
                                    ho_ImageUnrolled,
                                    out ExpTmpOutVar_0
                                );
                                ho_UnrolledImages.Dispose();
                                ho_UnrolledImages = ExpTmpOutVar_0;
                            }
                        }

                        if ((int)(ExpGetGlobalVar_DisplayIntermediateResults()) != 0)
                        {
                            hv_NumberUnrolled.Dispose();
                            HOperatorSet.CountObj(ho_UnrolledImages, out hv_NumberUnrolled);
                            ho_UnrolledOut.Dispose();
                            HOperatorSet.SelectObj(
                                ho_UnrolledImages,
                                out ho_UnrolledOut,
                                hv_NumberUnrolled
                            );
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_RegionMaskOut.Dispose();
                                HOperatorSet.GenRegionPoints(
                                    out ho_RegionMaskOut,
                                    hv_Rows.TupleSelectMask(hv_Mask),
                                    hv_Columns.TupleSelectMask(hv_Mask)
                                );
                            }
                            ho_DomainUnrolledOut.Dispose();
                            HOperatorSet.GetDomain(ho_UnrolledOut, out ho_DomainUnrolledOut);
                            ho_RegionDifference.Dispose();
                            HOperatorSet.Difference(
                                ho_DomainUnrolledOut,
                                ho_RegionMaskOut,
                                out ho_RegionDifference
                            );
                            if ((int)(hv_ColorMosaic) != 0)
                            {
                                hv_FillColor.Dispose();
                                hv_FillColor = new HTuple();
                                hv_FillColor[0] = 255;
                                hv_FillColor[1] = 255;
                                hv_FillColor[2] = 255;
                            }
                            else
                            {
                                hv_FillColor.Dispose();
                                hv_FillColor = 255;
                            }
                            HOperatorSet.OverpaintRegion(
                                ho_UnrolledOut,
                                ho_RegionDifference,
                                hv_FillColor,
                                "fill"
                            );
                            dev_resize_window_fit_image(
                                ho_UnrolledOut,
                                0,
                                0,
                                ExpGetGlobalVar_WindowWidthLimit(),
                                ExpGetGlobalVar_WindowHeightLimit()
                            );
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.DispObj(ho_UnrolledOut, HDevWindowStack.GetActive());
                            }
                            hv_Message.Dispose();
                            hv_Message = "Unrolled image";
                            hv_MessageWrapped.Dispose();
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                hv_MessageWrapped = ((hv_Message + " ")).TupleRegexpReplace(
                                    (new HTuple("(.{0,40})\\s")).TupleConcat("replace_all"),
                                    "$1\n"
                                );
                            }
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                disp_message(
                                    hv_WindowHandle_COPY_INP_TMP,
                                    ((("Camera " + (hv_Cam + 1)) + ":")).TupleConcat(
                                        hv_MessageWrapped
                                    ),
                                    "window",
                                    12,
                                    12,
                                    "black",
                                    "true"
                                );
                            }
                            // stop(...); only in hdevelop
                        }
                    }

                    //Determine the images that overlap each other
                    hv_RowBB1.Dispose();
                    hv_ColumnBB1.Dispose();
                    hv_RowBB2.Dispose();
                    hv_ColumnBB2.Dispose();
                    HOperatorSet.SmallestRectangle1(
                        ho_RegionsDilation,
                        out hv_RowBB1,
                        out hv_ColumnBB1,
                        out hv_RowBB2,
                        out hv_ColumnBB2
                    );
                    hv_From.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_From = hv_ColumnBB1.TupleSortIndex();
                    }
                    hv_To.Dispose();
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_To = new HTuple();
                        hv_To = hv_To.TupleConcat(
                            hv_From.TupleSelectRange(1, (new HTuple(hv_From.TupleLength())) - 1)
                        );
                        hv_To = hv_To.TupleConcat(hv_From.TupleSelect(0));
                    }

                    //Determine the shift between the unrolled images
                    ho_UnrolledImagesShifted.Dispose();
                    HOperatorSet.GenEmptyObj(out ho_UnrolledImagesShifted);

                    //Copy left part of first unrolled image because it can remain unshifted
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_RegionFrom.Dispose();
                        HOperatorSet.SelectObj(
                            ho_RegionsDilation,
                            out ho_RegionFrom,
                            (hv_From.TupleSelect(0)) + 1
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_ImageFrom.Dispose();
                        HOperatorSet.SelectObj(
                            ho_UnrolledImages,
                            out ho_ImageFrom,
                            (hv_From.TupleSelect(0)) + 1
                        );
                    }
                    {
                        HObject ExpTmpOutVar_0;
                        HOperatorSet.CopyImage(ho_ImageFrom, out ExpTmpOutVar_0);
                        ho_ImageFrom.Dispose();
                        ho_ImageFrom = ExpTmpOutVar_0;
                    }
                    ho_ConnectedRegions.Dispose();
                    HOperatorSet.Connection(ho_RegionFrom, out ho_ConnectedRegions);
                    hv_Number.Dispose();
                    HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                    if ((int)(new HTuple(hv_Number.TupleGreater(1))) != 0)
                    {
                        ho_SortedRegions.Dispose();
                        HOperatorSet.SortRegion(
                            ho_ConnectedRegions,
                            out ho_SortedRegions,
                            "character",
                            "true",
                            "column"
                        );
                        ho_ObjectSelected.Dispose();
                        HOperatorSet.SelectObj(ho_SortedRegions, out ho_ObjectSelected, 1);
                        ho_ImageFromReduced.Dispose();
                        HOperatorSet.ReduceDomain(
                            ho_ImageFrom,
                            ho_ObjectSelected,
                            out ho_ImageFromReduced
                        );
                        {
                            HObject ExpTmpOutVar_0;
                            HOperatorSet.ConcatObj(
                                ho_UnrolledImagesShifted,
                                ho_ImageFromReduced,
                                out ExpTmpOutVar_0
                            );
                            ho_UnrolledImagesShifted.Dispose();
                            ho_UnrolledImagesShifted = ExpTmpOutVar_0;
                        }
                    }
                    hv_ShiftAccumulated.Dispose();
                    hv_ShiftAccumulated = 0;
                    hv_HomMat2DAccumulated.Dispose();
                    HOperatorSet.HomMat2dIdentity(out hv_HomMat2DAccumulated);

                    //Determine the shift for the mosaicking
                    ho_ObjectSelected.Dispose();
                    HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ObjectSelected, 1);
                    hv_Channels.Dispose();
                    HOperatorSet.CountChannels(ho_ObjectSelected, out hv_Channels);
                    ho_OverlappingAreas.Dispose();
                    HOperatorSet.GenEmptyObj(out ho_OverlappingAreas);
                    hv_MaximaS.Dispose();
                    hv_MaximaS = new HTuple();
                    hv_Maxima.Dispose();
                    hv_Maxima = new HTuple();
                    for (
                        hv_FT = 0;
                        (int)hv_FT <= (int)((new HTuple(hv_From.TupleLength())) - 1);
                        hv_FT = (int)hv_FT + 1
                    )
                    {
                        hv_F.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_F = hv_From.TupleSelect(hv_FT);
                        }
                        hv_T.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_T = hv_To.TupleSelect(hv_FT);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_RegionFrom.Dispose();
                            HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionFrom, hv_F + 1);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_RegionTo.Dispose();
                            HOperatorSet.SelectObj(ho_RegionsDilation, out ho_RegionTo, hv_T + 1);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_ImageFrom.Dispose();
                            HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageFrom, hv_F + 1);
                        }
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_ImageTo.Dispose();
                            HOperatorSet.SelectObj(ho_UnrolledImages, out ho_ImageTo, hv_T + 1);
                        }
                        if (
                            (int)(
                                new HTuple(
                                    hv_FT.TupleEqual((new HTuple(hv_From.TupleLength())) - 1)
                                )
                            ) != 0
                        )
                        {
                            //Add only right part of last image
                            ho_ConnectedRegions.Dispose();
                            HOperatorSet.Connection(ho_RegionTo, out ho_ConnectedRegions);
                            hv_Number.Dispose();
                            HOperatorSet.CountObj(ho_ConnectedRegions, out hv_Number);
                            if ((int)(new HTuple(hv_Number.TupleGreater(1))) != 0)
                            {
                                ho_SortedRegions.Dispose();
                                HOperatorSet.SortRegion(
                                    ho_ConnectedRegions,
                                    out ho_SortedRegions,
                                    "character",
                                    "true",
                                    "column"
                                );
                                ho_RegionTo.Dispose();
                                HOperatorSet.SelectObj(ho_SortedRegions, out ho_RegionTo, 2);
                                ho_Domain.Dispose();
                                HOperatorSet.GetDomain(ho_ImageTo, out ho_Domain);
                                ho_RegionBlack.Dispose();
                                HOperatorSet.Difference(ho_Domain, ho_RegionTo, out ho_RegionBlack);
                                HOperatorSet.OverpaintRegion(
                                    ho_ImageTo,
                                    ho_RegionBlack,
                                    ((new HTuple(0)).TupleConcat(0)).TupleConcat(0),
                                    "fill"
                                );
                            }
                        }
                        //Select the kind of image used for matching
                        if ((int)(new HTuple(hv_Channels.TupleEqual(3))) != 0)
                        {
                            switch (2)
                            {
                                case 1:
                                    ho_ImageF1.Dispose();
                                    ho_ImageF2.Dispose();
                                    ho_ImageF3.Dispose();
                                    HOperatorSet.Decompose3(
                                        ho_ImageFrom,
                                        out ho_ImageF1,
                                        out ho_ImageF2,
                                        out ho_ImageF3
                                    );
                                    ho_ImageT1.Dispose();
                                    ho_ImageT2.Dispose();
                                    ho_ImageT3.Dispose();
                                    HOperatorSet.Decompose3(
                                        ho_ImageTo,
                                        out ho_ImageT1,
                                        out ho_ImageT2,
                                        out ho_ImageT3
                                    );
                                    ho_ImageFrom.Dispose();
                                    HOperatorSet.ConvertImageType(
                                        ho_ImageF1,
                                        out ho_ImageFrom,
                                        "real"
                                    );
                                    ho_ImageTo.Dispose();
                                    HOperatorSet.ConvertImageType(
                                        ho_ImageT1,
                                        out ho_ImageTo,
                                        "real"
                                    );
                                    break;
                                case 2:
                                    ho_GrayFrom.Dispose();
                                    HOperatorSet.Rgb1ToGray(ho_ImageFrom, out ho_GrayFrom);
                                    ho_GrayTo.Dispose();
                                    HOperatorSet.Rgb1ToGray(ho_ImageTo, out ho_GrayTo);
