                        hv_DRow.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_DRow = hv_RowOrig - hv_RowTrans;
                        }
                        hv_DCol.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_DCol = hv_ColOrig - hv_ColTrans;
                        }

                        hv_RegionWidth.Dispose();
                        HOperatorSet.RegionFeatures(
                            ho_Regions_COPY_INP_TMP,
                            "width",
                            out hv_RegionWidth
                        );
                        hv_MorphingWidth.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphingWidth = ((0.2 * (hv_RegionWidth.TupleMin()))).TupleInt();
                        }
                        hv_MorphingExtLeft.Dispose();
                        hv_MorphingExtLeft = 10;
                        hv_MorphingWidth2.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphingWidth2 = (2 * hv_MorphingWidth) + 1;
                        }
                        hv_MorphingWidth2ExtLeft.Dispose();
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            hv_MorphingWidth2ExtLeft = hv_MorphingWidth2 + hv_MorphingExtLeft;
                        }
                        ho_ImageWR.Dispose();
                        HOperatorSet.GenImageConst(
                            out ho_ImageWR,
                            "real",
                            hv_MorphingWidth2ExtLeft,
                            hv_MosaicHeight_COPY_INP_TMP
