                            hv_MorphC[
                                HTuple.TupleGenSequence(
                                    hv_RW * hv_MorphingWidth2ExtLeft,
                                    ((hv_RW * hv_MorphingWidth2ExtLeft) + hv_MorphingWidth2ExtLeft)
                                        - 1,
                                    1
                                )
                            ] = hv_Ramp * (hv_DCol.TupleSelect(hv_RW));
                        }
                        HOperatorSet.SetGrayval(ho_ImageWR, hv_RowsWI, hv_ColumnsWI, hv_MorphR);
                        HOperatorSet.SetGrayval(ho_ImageWC, hv_RowsWI, hv_ColumnsWI, hv_MorphC);
