                                ho_MorphedImage.Dispose();
                                HOperatorSet.TileImagesOffset(
                                    ho_ObjectsConcat,
                                    out ho_MorphedImage,
                                    (new HTuple(0)).TupleConcat(0),
                                    (new HTuple(0)).TupleConcat(
                                        (hv_ColumnCut - hv_MorphingWidth) - hv_MorphingExtLeft
                                    ),
                                    (new HTuple(0)).TupleConcat(0),
                                    (new HTuple(0)).TupleConcat(0),
                                    (new HTuple(-1)).TupleConcat(-1),
                                    (new HTuple(-1)).TupleConcat(-1),
                                    hv_MosaicWidth,
                                    hv_MosaicHeight_COPY_INP_TMP
                                );
                            }
                        }

                        if ((int)(hv_VisualizeMorphing) != 0)
                        {
                            ho_ImageToBShiftLocal.Dispose();
                            HOperatorSet.AffineTransImage(
                                ho_MorphedImage,
                                out ho_ImageToBShiftLocal,
                                hv_HomMat2DITrans,
                                "constant",
                                "false"
                            );
                            ho_MultiChannelImageLocal.Dispose();
                            HOperatorSet.Compose3(
                                ho_ImageFromB,
