                        if (
                            (int)(
                                new HTuple(hv_FT.TupleLess((new HTuple(hv_From.TupleLength())) - 1))
                            ) != 0
                        )
                        {
                            ho_ImageToShift.Dispose();
                            HOperatorSet.AffineTransImage(
                                ho_MorphedImage,
