                                out ho_ImageToShift,
                                hv_HomMat2DAccumulated,
                                "constant",
                                "true"
                            );
                            ho_RegionToShift.Dispose();
                            HOperatorSet.AffineTransRegion(
                                ho_RegionTo,
                                out ho_RegionToShift,
                                hv_HomMat2DAccumulated,
                                "nearest_neighbor"
                            );
                            hv_MosaicWidthExt.Dispose();
                            hv_MosaicHeightExt.Dispose();
                            HOperatorSet.GetImageSize(
                                ho_ImageToShift,
                                out hv_MosaicWidthExt,
                                out hv_MosaicHeightExt
                            );
                        }

                        ho_ImageToShiftReduced.Dispose();
                        HOperatorSet.ReduceDomain(
                            ho_ImageToShift,
                            ho_RegionToShift,
                            out ho_ImageToShiftReduced
                        );
                        {
                            HObject ExpTmpOutVar_0;
                            HOperatorSet.ConcatObj(
                                ho_UnrolledImagesShifted,
                                ho_ImageToShiftReduced,
                                out ExpTmpOutVar_0
                            );
                            ho_UnrolledImagesShifted.Dispose();
                            ho_UnrolledImagesShifted = ExpTmpOutVar_0;
                        }
                        ho_RegionIntersection1.Dispose();
                        HOperatorSet.Intersection(
                            ho_RegionFrom,
                            ho_RegionToShift,
                            out ho_RegionIntersection1
                        );
                        {
                            HObject ExpTmpOutVar_0;
                            HOperatorSet.Union2(
                                ho_OverlappingAreas,
                                ho_RegionIntersection1,
                                out ExpTmpOutVar_0
                            );
                            ho_OverlappingAreas.Dispose();
                            ho_OverlappingAreas = ExpTmpOutVar_0;
                        }

                        if ((int)(hv_VisualizeMorphing) != 0)
                        {
                            hv_NumberUI.Dispose();
                            HOperatorSet.CountObj(ho_UnrolledImagesShifted, out hv_NumberUI);
                            using (HDevDisposeHelper dh = new HDevDisposeHelper())
                            {
                                ho_ImageLeft.Dispose();
                                HOperatorSet.SelectObj(
                                    ho_UnrolledImagesShifted,
                                    out ho_ImageLeft,
                                    hv_NumberUI - 1
                                );
                            }
                            ho_ImageRight.Dispose();
                            HOperatorSet.SelectObj(
                                ho_UnrolledImagesShifted,
                                out ho_ImageRight,
                                hv_NumberUI
                            );
                            ho_GrayImageLeft.Dispose();
                            HOperatorSet.Rgb1ToGray(ho_ImageLeft, out ho_GrayImageLeft);
                            ho_GrayImageRight.Dispose();
                            HOperatorSet.Rgb1ToGray(ho_ImageRight, out ho_GrayImageRight);
                            ho_GrayImageLeftB.Dispose();
                            HOperatorSet.ConvertImageType(
                                ho_GrayImageLeft,
                                out ho_GrayImageLeftB,
                                "byte"
                            );
                            ho_GrayImageRightB.Dispose();
                            HOperatorSet.ConvertImageType(
                                ho_GrayImageRight,
                                out ho_GrayImageRightB,
                                "byte"
                            );
                            ho_MultiChannelImage1.Dispose();
                            HOperatorSet.Compose3(
                                ho_GrayImageLeftB,
                                ho_GrayImageLeftB,
                                ho_GrayImageRightB,
                                out ho_MultiChannelImage1
                            );
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
                            }
                            if (HDevWindowStack.IsOpen())
                            {
                                HOperatorSet.DispObj(
                                    ho_MultiChannelImage1,
                                    HDevWindowStack.GetActive()
                                );
                            }
                            // stop(...); only in hdevelop
                        }
                    }
                    //Adapt brightness in overlapping areas
                    //- First determine the centers of the blending areas
                    hv_ColumnBlendingCenter.Dispose();
                    hv_ColumnBlendingCenter = new HTuple();
                    hv_NumberUnrolledImages.Dispose();
                    HOperatorSet.CountObj(ho_UnrolledImagesShifted, out hv_NumberUnrolledImages);
                    HTuple end_val403 = hv_NumberUnrolledImages - 1;
                    HTuple step_val403 = 1;
                    for (
                        hv_I = 1;
                        hv_I.Continue(end_val403, step_val403);
                        hv_I = hv_I.TupleAdd(step_val403)
                    )
                    {
                        ho_I1.Dispose();
                        HOperatorSet.SelectObj(ho_UnrolledImagesShifted, out ho_I1, hv_I);
                        using (HDevDisposeHelper dh = new HDevDisposeHelper())
                        {
                            ho_I2.Dispose();
                            HOperatorSet.SelectObj(ho_UnrolledImagesShifted, out ho_I2, hv_I + 1);
