                hv_SamplePZ.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SamplePZ = hv_CylinderPointsZ_COPY_INP_TMP.TupleSelect(hv_Indices);
                }
                hv_CamParam0.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    0,
                    "params",
                    out hv_CamParam0
                );
                hv_CamPose0.Dispose();
                HOperatorSet.GetCameraSetupParam(
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    0,
                    "pose",
                    out hv_CamPose0
                );
                hv_HomMat3D0.Dispose();
                HOperatorSet.PoseToHomMat3d(hv_CamPose0, out hv_HomMat3D0);

                hv_HomMat3D0Invert.Dispose();
                HOperatorSet.HomMat3dInvert(hv_HomMat3D0, out hv_HomMat3D0Invert);
                hv_Qx.Dispose();
                hv_Qy.Dispose();
                hv_Qz.Dispose();
                HOperatorSet.AffineTransPoint3d(
                    hv_HomMat3D0Invert,
                    hv_SamplePX,
                    hv_SamplePY,
                    hv_SamplePZ,
                    out hv_Qx,
                    out hv_Qy,
                    out hv_Qz
                );
                hv_ImageSampleRow.Dispose();
                hv_ImageSampleColumn.Dispose();
                HOperatorSet.Project3dPoint(
                    hv_Qx,
                    hv_Qy,
                    hv_Qz,
                    hv_CamParam0,
                    out hv_ImageSampleRow,
                    out hv_ImageSampleColumn
                );
                if (
                    (int)(
                        new HTuple(
                            ((hv_ImageSampleRow.TupleFirstN(1))).TupleLess(
                                hv_ImageSampleRow.TupleLastN(1)
                            )
                        )
                    ) != 0
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_ImageSampleRow = hv_ImageSampleRow.TupleInverse();
                            hv_ImageSampleRow.Dispose();
                            hv_ImageSampleRow = ExpTmpLocalVar_ImageSampleRow;
                        }
                    }
                }
                hv_MinSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MinSlice = (
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (((hv_ImageSampleRow - hv_LabelMaxRow)).TupleSgn())
                                            ).TupleFindLast(1)
                                        )
                                    ).TupleSelect(0)
                                )
                            ).TupleConcat(0)
                        )
                    ).TupleMax();
                }
                hv_MaxSlice.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MaxSlice = (
                        (
                            (
                                (
                                    (
                                        (
                                            (
                                                (((hv_ImageSampleRow - hv_LabelMinRow)).TupleSgn())
                                            ).TupleFindLast(1)
                                        )
                                    ).TupleSelect(0)
                                )
                            ).TupleConcat(hv_NumSlices - 1)
                        )
                    ).TupleMin();
                }

                hv_MosaicHeight_COPY_INP_TMP.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_MosaicHeight_COPY_INP_TMP = (hv_MaxSlice - hv_MinSlice) + 1;
                }
                hv_SliceStart.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
