                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_SilhouetteMaxTilt = (new HTuple(camSetting.SilhouetteMaxTilt)).TupleRad();
                }
                //
                //Control the graphics output.
                ExpTmpLocalVar_WindowWidthLimit = 800;
                ExpSetGlobalVar_WindowWidthLimit(ExpTmpLocalVar_WindowWidthLimit);
                ExpTmpLocalVar_WindowHeightLimit = 600;
                ExpSetGlobalVar_WindowHeightLimit(ExpTmpLocalVar_WindowHeightLimit);
                dev_update_off();
                //
                //Ensure a correct value for the control of the display of intermediate results and
                //set initial state for displaying intermediate results
                ExpTmpLocalVar_DisplayIntermediateResults = 0;
                ExpSetGlobalVar_DisplayIntermediateResults(
                    ExpTmpLocalVar_DisplayIntermediateResults
                );
                //
                //Read one image to determine the image size.
                hv_Width.Dispose();
                hv_Height.Dispose();
                hv_Width = width;
                hv_Height = height;
                hv_CameraSetupModel.Dispose();
                HOperatorSet.ReadCameraSetupModel(
                    "Camera_Setup_model.csm",
                    out hv_CameraSetupModel
                );
                //
                //Ensure that the origin of the camera setup model lies in the
                //projection center of camera 0.
                hv_CamPose0.Dispose();
                HOperatorSet.GetCameraSetupParam(hv_CameraSetupModel, 0, "pose", out hv_CamPose0);
                HOperatorSet.SetCameraSetupParam(
                    hv_CameraSetupModel,
                    "general",
                    "coord_transf_pose",
                    hv_CamPose0
                );
                //
                //Set suitable data of object
                hv_CylinderRadiusInMM.Dispose();
                hv_CylinderRadiusInMM = camSetting.CylinderRadiusInMM;
                hv_LabelMinRow.Dispose();
                hv_LabelMinRow = camSetting.LabelMinRow;
                hv_LabelMaxRow.Dispose();
                hv_LabelMaxRow = camSetting.LabelMaxRow;
                //
                //Convert control parameters into meters.
                hv_PixelSize.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_PixelSize = 0.001 * hv_PixelSizeInMM;
                }
                hv_CylinderRadius.Dispose();
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_CylinderRadius = 0.001 * hv_CylinderRadiusInMM;
                }
                //
                //Prepare measures for silhouette extraction.
                hv_MeasureHandles1.Dispose();
                hv_MeasureHandles1 = new HTuple();
                HTuple end_val58 = hv_LabelMaxRow;
                HTuple step_val58 = hv_SilhouetteMeasureDistance;
                for (
                    hv_Row = hv_LabelMinRow;
                    hv_Row.Continue(end_val58, step_val58);
                    hv_Row = hv_Row.TupleAdd(step_val58)
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MeasureHandle.Dispose();
                        HOperatorSet.GenMeasureRectangle2(
                            hv_Row,
                            hv_Width / 2,
                            (new HTuple(0)).TupleRad(),
                            (hv_Width / 2) - 100,
                            hv_SilhouetteMeasureLength2,
                            hv_Width,
                            hv_Height,
                            "nearest_neighbor",
                            out hv_MeasureHandle
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MeasureHandles1 = hv_MeasureHandles1.TupleConcat(
                                hv_MeasureHandle
                            );
                            hv_MeasureHandles1.Dispose();
                            hv_MeasureHandles1 = ExpTmpLocalVar_MeasureHandles1;
                        }
                    }
                }
                hv_MeasureHandles2.Dispose();
                hv_MeasureHandles2 = new HTuple();
                HTuple end_val63 = hv_LabelMaxRow;
                HTuple step_val63 = hv_SilhouetteMeasureDistance;
                for (
                    hv_Row = hv_LabelMinRow;
                    hv_Row.Continue(end_val63, step_val63);
                    hv_Row = hv_Row.TupleAdd(step_val63)
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MeasureHandle.Dispose();
                        HOperatorSet.GenMeasureRectangle2(
                            hv_Row,
                            hv_Width / 2,
                            (new HTuple(0)).TupleRad(),
                            (hv_Width / 2) - 100,
                            hv_SilhouetteMeasureLength2,
                            hv_Width,
                            hv_Height,
                            "nearest_neighbor",
                            out hv_MeasureHandle
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MeasureHandles2 = hv_MeasureHandles2.TupleConcat(
                                hv_MeasureHandle
                            );
                            hv_MeasureHandles2.Dispose();
                            hv_MeasureHandles2 = ExpTmpLocalVar_MeasureHandles2;
                        }
                    }
                }
                hv_MeasureHandles3.Dispose();
                hv_MeasureHandles3 = new HTuple();
                HTuple end_val68 = hv_LabelMaxRow;
                HTuple step_val68 = hv_SilhouetteMeasureDistance;
                for (
                    hv_Row = hv_LabelMinRow;
                    hv_Row.Continue(end_val68, step_val68);
                    hv_Row = hv_Row.TupleAdd(step_val68)
                )
