                                hv_MeasureHandle
                            );
                            hv_MeasureHandles3.Dispose();
                            hv_MeasureHandles3 = ExpTmpLocalVar_MeasureHandles3;
                        }
                    }
                }
                hv_MeasureHandles4.Dispose();
                hv_MeasureHandles4 = new HTuple();
                HTuple end_val73 = hv_LabelMaxRow;
                HTuple step_val73 = hv_SilhouetteMeasureDistance;
                for (
                    hv_Row = hv_LabelMinRow;
                    hv_Row.Continue(end_val73, step_val73);
                    hv_Row = hv_Row.TupleAdd(step_val73)
                )
                {
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        hv_MeasureHandle.Dispose();
                        HOperatorSet.GenMeasureRectangle2(
                            hv_Row,
                            hv_Width / 2,
                            (new HTuple(0)).TupleRad(),
                            (hv_Width / 2) - 100,
                            hv_SilhouetteMeasureLength2,
                            hv_Width,
                            hv_Height,
                            "nearest_neighbor",
                            out hv_MeasureHandle
                        );
                    }
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        {
                            HTuple ExpTmpLocalVar_MeasureHandles4 = hv_MeasureHandles4.TupleConcat(
                                hv_MeasureHandle
                            );
                            hv_MeasureHandles4.Dispose();
                            hv_MeasureHandles4 = ExpTmpLocalVar_MeasureHandles4;
                        }
                    }
                }
                HTuple end_val77 = hv_LabelMaxRow;
                HTuple step_val77 = hv_SilhouetteMeasureDistance;
                for (
                    hv_Row = hv_LabelMinRow;
                    hv_Row.Continue(end_val77, step_val77);
                    hv_Row = hv_Row.TupleAdd(step_val77)
                )
                {
                    //gen_measure_rectangle2 (Row, Width / 2, rad(0), Width / 2-100, SilhouetteMeasureLength2, Width, Height, 'nearest_neighbor', MeasureHandle)
                    using (HDevDisposeHelper dh = new HDevDisposeHelper())
                    {
                        ho_Rectangle.Dispose();
                        HOperatorSet.GenRectangle2(
                            out ho_Rectangle,
                            hv_Row,
                            hv_Width / 2,
                            (new HTuple(0)).TupleRad(),
                            (hv_Width / 2) - 100,
                            hv_SilhouetteMeasureLength2
                        );
                    }
                }
                //
                //Create rectification maps for the elimination of the radial distortion
                //and create a camera setup model for the rectified images.
                ho_RectificationMaps.Dispose();
                hv_CameraSetupModelZeroDist.Dispose();
                hv_NumCameras.Dispose();
                prepare_distortion_removal(
                    out ho_RectificationMaps,
                    hv_CameraSetupModel,
                    out hv_CameraSetupModelZeroDist,
                    out hv_NumCameras
                );
                //
                //Determine an approximate pose of the cylinder
                //assuming that it stands upright in the center of the cameras.
                hv_PoseCylinderApprox.Dispose();
                hv_HomMat3DCylinderApprox.Dispose();
                determine_approximate_cylinder_pose_in_center_of_cameras(
                    hv_CameraSetupModelZeroDist,
                    hv_NumCameras,
                    out hv_PoseCylinderApprox,
                    out hv_HomMat3DCylinderApprox
                );
                //
                //Determine approximately the required size (height) of the 3D model
                //of the cylinder such that it covers the area between the given borders.
                hv_MinZ.Dispose();
                hv_MaxZ.Dispose();
                determine_required_cylinder_model_extent(
                    hv_LabelMinRow,
                    hv_LabelMaxRow,
                    hv_Width,
                    hv_CameraSetupModelZeroDist,
                    hv_NumCameras,
                    hv_HomMat3DCylinderApprox,
                    out hv_MinZ,
                    out hv_MaxZ
                );
                //
                //Determine the minimal and maximal distances between the opposite silhouettes.
                hv_MinPairDist.Dispose();
                hv_MaxPairDist.Dispose();
                determine_min_max_silhouette_distance(
                    hv_CameraSetupModelZeroDist,
                    hv_NumCameras,
                    hv_PoseCylinderApprox,
                    hv_CylinderRadius,
                    hv_MinZ,
                    hv_MaxZ,
                    hv_Width,
                    out hv_MinPairDist,
                    out hv_MaxPairDist
                );
                //
                //Create the 3D object model of the cylinder and get the 3D points.
                hv_NumSlices.Dispose();
                hv_NumPointsPerSlice.Dispose();
                hv_MinZI.Dispose();
                hv_MaxZI.Dispose();
                hv_CylinderPointsX.Dispose();
                hv_CylinderPointsY.Dispose();
                hv_CylinderPointsZ.Dispose();
                gen_cylinder_model(
                    hv_PixelSize,
                    hv_CylinderRadius,
                    hv_MinZ,
                    hv_MaxZ,
                    out hv_NumSlices,
                    out hv_NumPointsPerSlice,
                    out hv_MinZI,
                    out hv_MaxZI,
                    out hv_CylinderPointsX,
                    out hv_CylinderPointsY,
                    out hv_CylinderPointsZ
                );
                //
                //Determine the size of the final mosaic image.
                hv_MosaicHeight.Dispose();
                hv_MosaicHeight = new HTuple(hv_NumSlices);
                hv_MosaicWidth.Dispose();
                hv_MosaicWidth = new HTuple(hv_NumPointsPerSlice);
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_Rectangle.Dispose();
                ho_RectificationMaps.Dispose();
                ho_ObjectSelected.Dispose();
                ho_ImagesRectified.Dispose();
                ho_ImagesGrayRectified.Dispose();
                ho_Regions.Dispose();
                ho_FinalMosaic.Dispose();

                hv_PixelSizeInMM.Dispose();
                hv_FineAdjustmentMatchingWidth.Dispose();
                hv_FineAdjustmentMaxShift.Dispose();
                hv_BlendingSeam.Dispose();
                hv_SilhouetteMeasureDistance.Dispose();
                hv_SilhouetteMeasureLength2.Dispose();
                hv_SilhouetteMeasureSigma.Dispose();
                hv_SilhouetteMeasureThreshold.Dispose();
                hv_SilhouetteMaxTilt.Dispose();
                hv_Width.Dispose();
                hv_Height.Dispose();
                hv_WindowHandle.Dispose();
                hv_CameraSetupModel.Dispose();
                hv_CamPose0.Dispose();
                hv_CylinderRadiusInMM.Dispose();
                hv_LabelMinRow.Dispose();
                hv_LabelMaxRow.Dispose();
                hv_PixelSize.Dispose();
                hv_CylinderRadius.Dispose();
                hv_MeasureHandles1.Dispose();
                hv_Row.Dispose();
                hv_MeasureHandle.Dispose();
                hv_MeasureHandles2.Dispose();
                hv_MeasureHandles3.Dispose();
                hv_MeasureHandles4.Dispose();
                hv_CameraSetupModelZeroDist.Dispose();
                hv_NumCameras.Dispose();
                hv_PoseCylinderApprox.Dispose();
                hv_HomMat3DCylinderApprox.Dispose();
                hv_MinZ.Dispose();
                hv_MaxZ.Dispose();
                hv_MinPairDist.Dispose();
                hv_MaxPairDist.Dispose();
                hv_NumSlices.Dispose();
