        IntPtr combinedPtr = IntPtr.Zero;

        public IntPtr GetColorImagePointer(HObject colorImage, out int width, out int height)
        {
            // 获取图像基本信息
            HTuple channels,
                type,
                imgWidth,
                imgHeight;
            HOperatorSet.CountChannels(colorImage, out channels);
            if (channels.I != 3)
                throw new Exception("不是RGB彩色图像");

            // 获取各通道指针
            HTuple ptrR,
                ptrG,
                ptrB;
            HOperatorSet.GetImagePointer3(
                colorImage,
                out ptrR,
                out ptrG,
                out ptrB,
                out type,
                out imgWidth,
                out imgHeight
            );

            width = imgWidth;
            height = imgHeight;

            // 计算总字节数
            int pixelCount = width * height;
            int bytesPerPixel =
                type.S == "byte"
                    ? 1
                    : type.S == "uint2"
                        ? 2
                        : 4;
            int totalBytes = pixelCount * 3 * bytesPerPixel;

            if (combinedPtr == IntPtr.Zero)
            {
                // 分配非托管内存
                combinedPtr = Marshal.AllocHGlobal(totalBytes);
            }

            // 将RGB数据交错排列为连续内存
            unsafe
            {
                byte* dst = (byte*)combinedPtr;
                byte* srcR = (byte*)ptrR.L;
                byte* srcG = (byte*)ptrG.L;
                byte* srcB = (byte*)ptrB.L;

                for (int i = 0; i < pixelCount; i++)
                {
                    *dst++ = *srcR++;
                    *dst++ = *srcG++;
                    *dst++ = *srcB++;
                }
            }

            return combinedPtr;
        }

        HObject TransformBgraImage(CImage data)
        {
            string format = "rgb";
            if (data.PixelFormat == PixelFormats.Bgr32)
            {
                format = "bgrx";
            }
            HOperatorSet.GenImageInterleaved(
                out HObject image1,
                data.ImageData,
                format,
                hv_Width,
                hv_Height,
                0,
                "byte",
                0,
                0,
                0,
                0,
                -1,
                0
            );
            return image1;
        }

        public CImage action(CImage data1, CImage data2, CImage data3, CImage data4)
        {
            HObject image1 = TransformBgraImage(data1);
            HObject image2 = TransformBgraImage(data2);
            HObject image3 = TransformBgraImage(data3);
            HObject image4 = TransformBgraImage(data4);
            HOperatorSet.ConcatObj(image1, image2, out HObject ho_Image);
            HOperatorSet.ConcatObj(ho_Image, image3, out ho_Image);
            HOperatorSet.ConcatObj(ho_Image, image4, out ho_Image);
            try
            {
                hv_ColorMosaic.Dispose();
                hv_ColorMosaic = 1;
                hv_t.Dispose();
                hv_t = new HTuple();
                //
                //Determine if color output is possible.
                if ((int)(hv_ColorMosaic) != 0)
                {
                    ho_ObjectSelected.Dispose();
                    HOperatorSet.SelectObj(ho_Image, out ho_ObjectSelected, 1);
                    hv_Channels.Dispose();
                    HOperatorSet.CountChannels(ho_ObjectSelected, out hv_Channels);
                    if ((int)(new HTuple(hv_Channels.TupleEqual(1))) != 0)
                    {
                        hv_ColorMosaic.Dispose();
                        hv_ColorMosaic = 0;
                    }
                    else if ((int)(new HTuple(hv_Channels.TupleNotEqual(3))) != 0)
                    {
                        //Wrong number of channels: Must be 1 or 3
                        // stop(...); only in hdevelop
                    }
                }

                ho_ImagesRectified.Dispose();
                ho_ImagesGrayRectified.Dispose();
                eliminate_radial_distortions(
                    ho_Image,
                    ho_RectificationMaps,
                    out ho_ImagesRectified,
                    out ho_ImagesGrayRectified,
                    hv_NumCameras,
                    hv_Channels
                );
                //
                //Determine the pose of the rotation axis in 3D and create an additional camera setup model
                //with the origin on the rotation axis.
                hv_BackgroundMayContainTexture.Dispose();
                hv_BackgroundMayContainTexture = 0;
                //determine_rotation_axis_3d (ImagesRectified, CylinderRadius, MeasureHandles, Width, Height, CameraSetupModelZeroDist, NumCameras, PoseCylinderApprox, MinPairDist, MaxPairDist, SilhouetteMeasureSigma, SilhouetteMeasureThreshold, SilhouetteMaxTilt, 0.1 * PixelSize, PoseCylinder, CameraSetupModelZeroDistInCylinderOrigin)
                using (HDevDisposeHelper dh = new HDevDisposeHelper())
                {
                    hv_PoseCylinder.Dispose();
                    hv_Quality.Dispose();
                    hv_CameraSetupModelZeroDistInCylinderOrigin.Dispose();
                    hv_RadiusEstimated.Dispose();
                    determine_rotation_axis_3d_COPY_2(
                        ho_ImagesRectified,
                        ho_ImagesGrayRectified,
                        hv_CylinderRadius,
                        hv_BackgroundMayContainTexture,
                        hv_MeasureHandles1,
                        hv_MeasureHandles2,
                        hv_MeasureHandles3,
                        hv_MeasureHandles4,
                        hv_Width,
                        hv_Height,
                        hv_CameraSetupModelZeroDist,
                        hv_NumCameras,
                        hv_MinPairDist,
                        hv_MaxPairDist,
                        hv_SilhouetteMeasureSigma,
                        hv_SilhouetteMeasureThreshold,
                        hv_SilhouetteMaxTilt,
                        0.1 * hv_PixelSize,
                        out hv_PoseCylinder,
                        out hv_Quality,
                        out hv_CameraSetupModelZeroDistInCylinderOrigin,
                        out hv_RadiusEstimated
                    );
                }
                //
                //确定拼接图像各组成部分的位置
                ho_Regions.Dispose();
                determine_source_cameras_for_mosaic_parts(
                    out ho_Regions,
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    hv_NumCameras,
                    hv_CylinderPointsX,
                    hv_CylinderPointsY,
                    hv_CylinderPointsZ,
                    hv_NumPointsPerSlice,
                    hv_MinZI,
                    hv_MaxZI,
                    hv_MosaicWidth,
                    hv_MosaicHeight
                );
                //
                //拼接图像
                hv_HighImageQuality.Dispose();
                hv_HighImageQuality = camSetting.HighImageQuality ? 1 : 0;
                hv_PerformFineAdjustment.Dispose();
                hv_PerformFineAdjustment = camSetting.PerformFineAdjustment ? 1 : 0;
                ho_FinalMosaic.Dispose();
                stitch_images_WH20250312(
                    ho_Regions,
                    ho_ImagesRectified,
                    ho_ImagesGrayRectified,
                    out ho_FinalMosaic,
                    hv_WindowHandle,
                    hv_ColorMosaic,
                    hv_HighImageQuality,
                    hv_PerformFineAdjustment,
                    hv_FineAdjustmentMaxShift,
                    hv_FineAdjustmentMatchingWidth,
                    hv_BlendingSeam,
                    hv_CameraSetupModelZeroDistInCylinderOrigin,
                    hv_NumCameras,
                    hv_MosaicWidth,
                    hv_MosaicHeight,
                    hv_CylinderPointsX,
                    hv_CylinderPointsY,
                    hv_CylinderPointsZ,
                    hv_NumSlices,
                    hv_NumPointsPerSlice,
                    hv_CylinderRadius,
                    hv_LabelMinRow,
                    hv_LabelMaxRow
                );
                if (camSetting.TiledImage)
                {
                    HOperatorSet.ConcatObj(
                        ho_FinalMosaic,
                        ho_FinalMosaic,
                        out HObject objectsConcat
                    );
                    HOperatorSet.TileImages(objectsConcat, out HObject tiledImage, 2, "vertical");
                    ho_FinalMosaic.Dispose();
                    ho_FinalMosaic = tiledImage;
                }
                HOperatorSet.ConvertImageType(ho_FinalMosaic, out HObject ExpTmpOutVar_0, "byte");
                //HOperatorSet.WriteImage(ExpTmpOutVar_0, "bmp", 0, "image1");
                var ptrFinal = GetColorImagePointer(ExpTmpOutVar_0, out int width, out int height);
                ExpTmpOutVar_0.Dispose();
                ho_FinalMosaic.Dispose();
                ho_Image.Dispose();
                return new CImage(width, height, ptrFinal, PixelFormats.Rgb24);
                //Eliminate distortions from the images.
            }
            catch (HalconException HDevExpDefaultException)
            {
                ho_Image.Dispose();
                throw HDevExpDefaultException;
            }
        }

